window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-reumatologia-reu-1"]={"block":"medcurso:medcurso-reumatologia-reu-1","label":"Medcurso · REU 1","count":454,"questions":[{"id":"medcurso-reumatologia-reu-1-345452","number":"345452","sourceNumber":"345452","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Na artrite reumatóide, quais características clínicas são típicas dessa artropatia:","options":{"A":"Rigidez matinal prolongada, simetria, sintomas gerais, não deformante.","B":"Rigidez matinal prolongada, assimetria, sintomas gerais, deformante.","C":"Rigidez matinal fugaz, simetria, sintomas gerais, deformante.","D":"Rigidez matinal prolongada, simetria, sintomas gerais, deformante."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-343836","number":"343836","sourceNumber":"343836","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher, 45 anos, retorna ao ambulatório de reumatologia com resultado do exames,\nVHS (40 mm) e radiografias de mãos com\naumento de partes moles e erosões marginais em\narticulações interfalangeanas proximais e processo estiloide ulnar. Diante deste quadro qual exame\nlaboratorial com maior probabilidade de vir positivo na paciente?","options":{"A":"HLA-B27.","B":"Anti Sm.","C":"Anti CCP.","D":"ASLO."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-283278","number":"283278","sourceNumber":"283278","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Qual a manifestação ocular esperada para um paciente com artrite reativa?","options":{"A":"Conjuntivite asséptica.","B":"Ceratite.","C":"Irite.","D":"Neurite."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-283283","number":"283283","sourceNumber":"283283","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 48 anos de idade está em seguimento por quadro de poliartrite simétrica de\ngrandes e pequenas articulações há 6 meses. Exames complementares revelaram atividade\ninflamatória elevada e fator reumatoide fortemente positivo. Qual das seguintes medicações é\nmodificadora do curso dessa doença?","options":{"A":"Azatioprina.","B":"Cloroquina.","C":"Pregabalina.","D":"Naproxeno."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-281112","number":"281112","sourceNumber":"281112","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem, 53 anos, hipertenso, portador de doença renal crônica em tratamento\nconservador (creatinina basal = 1,7 mEq/L),\napresenta artrite no joelho esquerdo, que teve início\nsúbito nas últimas 24h, após churrasco em família. Faz uso regular de clortalidona e valsartana, é\ntabagista e etilista. Refere que não apresentou febre nas últimas 24 horas e o exame físico não\nrevela sinais sistêmicos. Nota-se edema articular com hiperemia, dor e limitação funcional à\nmobilização do joelho esquerdo.","options":{"A":"Punção articular e drenagem.","B":"Colchicina.","C":"Clindamicina.","D":"Prednisolona intra-articular.","E":"Alopurinol."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-283307","number":"283307","sourceNumber":"283307","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Com relação a artrites agudas na infância, marque a alternativa CORRETA:","options":{"A":"A artrite da febre reumática é, principalmente, uma poliartrite migratória de grandes\narticulações\nacometendo de forma transitória e intermitente.","B":"A artrite séptica é considerada uma emergência médica, sendo mais frequente nos adolescentes\ndo sexo masculino.","C":"A artrite reativa pode ocorrer em qualquer idade, geralmente, após 1 mês de infecção\ngastrointestinal ou genitourinária, acometendo as articulações de membros superiores.","D":"Os tumores ósseos benignos e malignos, frequentemente, cursam mais com artrite do que com\ndor."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-247186","number":"247186","sourceNumber":"247186","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menina com 9 anos de idade e história de artrite no punho direito por 3 dias, seguida\npor artrite no tornozelo esquerdo com duração\nde 2 dias e por artrite no joelho que também durou 2\ndias. Apresentou melhora com aspirina. Na avaliação laboratorial apresentou aumento das provas\nde atividade inflamatória. Uma semana depois apresentou cansaço aos médios esforços. Quais os\nachados mais prováveis na ausculta cardíaca?","options":{"A":"Bradicardia e sopro diastólico em foco aórtico.","B":"Bradicardia e sopro sistólico em foco aórtico.","C":"Taquicardia e sopro diastólico em foco aórtico.","D":"Taquicardia e sopro sistólico em foco mitral.","E":"Bradicardia e sopro diastólico em foco mitral."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-251928","number":"251928","sourceNumber":"251928","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Os critérios de Jones são utilizados para o diagnóstico de Febre Reumática, sendo sua\nultima modificação realizada em 2015, qual das abaixo consta a assertiva que contém a\ncombinação dos critérios, que fazem o diagnóstico dessa doença no primeiro surto.","options":{"A":"Cardite, febre e ASO positivo.","B":"Artrite, febre e aumento do espaço P-R.","C":"Eritema marginado, artralgia, e ASO positivo.","D":"Poliartralgia, febre e convulsões."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-217713","number":"217713","sourceNumber":"217713","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma mulher de 54 anos evolui há 3 meses com fadiga e anorexia, acompanhadas de\ndor e rigidez, principalmente matinal,\nque acomete a musculatura do pescoço e da cintura\nescapular e perdura por cerca de 45 minutos. Exames laboratoriais solicitados revelam Hb: 9,6 g/dl,\ncom hemácias microcíticas e hipocrômicas; VHS: 96 mm/h; FAN: reativo e ferritina normal. A\nanamnese dirigida identificou apenas artralgia de cotovelos e emagrecimento de 4 kg no período.\n\nAusculta cardíaca, pulmonar e palpação do abdome sem achados anormais. Kerning, Brudzinski e\nLasegue negativos. Considerando a hipótese\ndiagnóstica mais provável, a conduta MAIS\nADEQUADA, dentre as oferecidas é:","options":{"A":"Tomografia computadorizada de tórax e abdome.","B":"Biópsia de artéria temporal.","C":"Punção lombar para análise liquórica.","D":"Prednisona 20 mg pela manhã."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-182694","number":"182694","sourceNumber":"182694","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A Febre Reumática (FR) é uma doença muito frequente nos países em\ndesenvolvimento. Com relação à FR, marque a assertiva CORRETA:","options":{"A":"São sinais menores dos critérios de Jones: artralgia, febre, aumento do VHS, aumento do\nespaço PR e elevação da ASO.","B":"A profilaxia secundária para FR deve ser realizada com penicilina G benzatina de 28 em 28 dias,","C":"As válvulas cardíacas mais frequentemente acometidas são mitral e tricúspide.","D":"A Coréia de Sydenham surge tardiamente (2 meses a 1 ano após infecção estreptocócica), e\nisoladamente faz diagnóstico de FR."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-183129","number":"183129","sourceNumber":"183129","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Nas uveítes associadas com artrite juvenil crônica, é INCORRETO afirmar que:","options":{"A":"20% dos casos são bilaterais.","B":"O olho fica branco mesmo na presença de severa uveíte.","C":"O envolvimento do segundo olho em casos unilaterais é raro após um ano.","D":"25% dos casos são severos e respondem pobremente ao tratamento.","E":"Cerca de 15% dos casos têm um curso que dura menos de 4 meses."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-159109","number":"159109","sourceNumber":"159109","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A febre reumática é uma complicação não supurativa da faringoamigdalite causada\npelo estreptococo beta-hemolítico do grupo A. Em\nrelação ao diagnóstico desta doença, quais são,\nrespectivamente, os critérios maiores e os menores para o diagnóstico de um surto?","options":{"A":"Maiores: cardite, miosite, artrite, cerebelite, amigdalite. Menores: sopro cardíaco,\nprolongamento\ndo intervalo PR, degeneração do folheto posterior\nda valva mitral, eritema.","B":"Maiores: cardiomegalia, eritema marginado, taquicardia, hepatomegalia, artralgia. Menores:\nfebre, artrite, coreia, exantema.","C":"Maiores: cardite, coreia de Sydenham, artrite, eritema marginado, nódulos subcutâneos.\n\nMenores: febre, artralgia, elevação das provas de fase aguda, intervalo PR prolongado.","D":"Maiores: cardite, artralgia, elevação da proteína C-reativa e da velocidade de\nhemossedimentação, coreia, febre. Menores: eritema marginado, nódulos subcutâneos,\nhepatomegalia, taquicardia."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-135982","number":"135982","sourceNumber":"135982","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"É o distúrbio inflamatório mais comum do esqueleto axial. Há uma predominância pelo\nsexo masculino. O início é insidioso de lombalgia que persiste por mais de 3 meses, acompanhada\nde rigidez matinal precoce e tipicamente melhorada pelo exercício. Ocorre em 20% dos indivíduos\nHLA-B27 positivos com um membro da família afetado. Qual a patologia em questão?","options":{"A":"Espondilite anquilosante","B":"Artrite reumatoide","C":"Artrite psoriásica","D":"Artrite enteropática"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-66942","number":"66942","sourceNumber":"66942","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente com edema de tecido mole de três ou mais articulações das mãos, com\nrigidez matinal \"maior ou igual a\" 1 hora,\nnódulos subcutâneos e erosões e/ou osteopenia\nperiarticular nas articulações de mãos e punhos. Qual teste laboratorial é encontrado em 70% dos\npacientes, tem alta especificidade e está frequentemente presente antes que a doença clínica seja\ndiagnosticada?","options":{"A":"FAN;","B":"Fator Reumatoide;","C":"Anti-CCP (Ac Antipeptídeo Citrulinado Cíclico);","D":"VHS;"},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-50116","number":"50116","sourceNumber":"50116","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Trata-se de um exame laboratorial que está fortemente associado à ARTRITE\nREUMATOIDE, ocorre em 60 a 70% dos pacientes com\na doença, pode ocorrer antes do início dos\nsintomas sugerindo sua utilidade na triagem de pacientes com risco e para o diagnóstico precoce\nda doença:","options":{"A":"Fator Reumatoide.","B":"Anticorpo antipeptídeo citrulinado cíclico (anti-CCP).","C":"Proteína C Reativa quantitativa.","D":"VDRL."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-37066","number":"37066","sourceNumber":"37066","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente feminina, 42 anos, branca, com artralgias de mãos, ombros e tornozelos há 3\nmeses, de intensidade crescente, apesar do uso de diclofenaco 50 mg 3x/dia. Refere limitações\ndo movimento por dor ao acordar durante aproximadamente 1 hora diariamente. Ao exame: bom\nestado geral, corada, afebril, sem lesões cutâneas, com aumento das articulações interfalangeanas\nproximais e metacarpofalangeanas de 2º e 3º dedos das duas mãos, sem desvios e com artrite de\ncotovelo direito e tornozelos. Restante do exame físico normal. De acordo com a principal hipótese\ndiagnóstica, qual a droga de escolha a ser introduzida no momento?","options":{"A":"Prednisona 1 mg/kg/dia, em doses divididas","B":"Azatioprina 1 mg/kg/dia, dose única","C":"Metotrexate 7,5 mg/semana","D":"Colchicina 0,5 g de 1/1 hora até passar a dor","E":"Corticosteroide intra-articular via punção"},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-29360","number":"29360","sourceNumber":"29360","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Manifesta-se sob a forma de oligoartrite assimétrica de membros inferiores, com cultura\nde líquido sinovial estéril e associada ao\nHLA-B27 em cerca de 60% dos pacientes?","options":{"A":"Síndrome de Reiter","B":"Artrite enteropática","C":"Artrite psoriásica","D":"Artrite reumatoide","E":"Artrite séptica"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-307030","number":"307030","sourceNumber":"307030","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher, 50 anos de idade, procura atendimento ambulatorial por dores em articulações\ndas mãos. As dores foram iniciadas há 8 meses\ne são acompanhadas de rigidez matinal. De\nantecedentes, refere hipotireoidismo, em uso de levotiroxina. Ao exame físico, sinais vitais e\nausculta sem alterações. Notam-se edema e dor à movimentação passiva das articulações\ninterfalangianas proximais em ambas as mãos, inclusive dos polegares, além de punhos. Realizado\nfator reumatoide, reagente. Frente ao caso, considerando os critérios internacionais mais utilizados\npara o diagnóstico mais provável, é CORRETO afirmar:","options":{"A":"O acometimento de grandes articulações, como o punho, pontua menos.","B":"A presença do fator reumatoide é imprescindível para o diagnóstico.","C":"Para confirmação diagnóstica, é necessária a evidência de deformidade articular.","D":"A duração dos sintomas precisa ser de, no mínimo, seis semanas."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-307031","number":"307031","sourceNumber":"307031","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher, 50 anos de idade, procura atendimento ambulatorial por dores em articulações\ndas mãos. As dores foram iniciadas há 8 meses\ne são acompanhadas de rigidez matinal. De\nantecedentes, refere hipotireoidismo, em uso de levotiroxina. Ao exame físico, sinais vitais e\nausculta sem alterações. Notam-se edema e dor à movimentação passiva das articulações\ninterfalangianas proximais em ambas as mãos, inclusive dos polegares, além de punhos. Realizado\nfator reumatoide, reagente. Frente ao caso, A fisiopatologia mais importante do diagnóstico mais\nprovável envolve:","options":{"A":"Sinovite crônica.","B":"Entesite crônica.","C":"Osteíte crônica.","D":"Capsulite crônica."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-307032","number":"307032","sourceNumber":"307032","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher, 50 anos de idade, procura atendimento ambulatorial por dores em articulações\ndas mãos. As dores foram iniciadas há 8 meses\ne são acompanhadas de rigidez matinal. De\nantecedentes, refere hipotireoidismo, em uso de levotiroxina. Ao exame físico, sinais vitais e\nausculta sem alterações. Notam-se edema e dor à movimentação passiva das articulações\ninterfalangianas proximais em ambas as mãos, inclusive dos polegares, além de punhos. Realizado\nfator reumatoide, reagente. Frente ao caso, Segundo o protocolo do Sistema Único de Saúde, SUS,\na medicação de primeira linha, a ser oferecida, é:","options":{"A":"Prednisolona.","B":"Metotrexate.","C":"Hidroxicloroquina.","D":"Adalimumabe."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-314210","number":"314210","sourceNumber":"314210","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Considerando as causas inflamatórias da Artrite na infância e adolescência, assinale a\nalternativa INCORRETA.","options":{"A":"As artrites reativas são um grupo de artrites inflamatórias que incluem a febre reumática aguda,\nas artrites após infecções do trato\ngenitourinário ou gastrointestinal e as artrites pós-infecciosas e\npós-virais.","B":"A artrite psoriática juvenil é a artrite associada à lesão cutânea da psoríase.","C":"A artrite idiopática juvenil é a doença reumática crônica mais comum da infância e uma causa\nfrequente de incapacidade física.","D":"A denominação de artrite crônica na infância é clara; dessa forma, classificam-se como de início\njuvenil os quadros que começam aos 15 anos de idade."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-315203","number":"315203","sourceNumber":"315203","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A sindrome de Reiter é descrita como uma patologia relacionada a uma Triade bem\ncomo a presença de um determinado agente\ninfeccioso. Cite a alternativa CORRETA:","options":{"A":"Alopecia, artrite e colite / estafilococos.","B":"Anemia, endocardite e artrite / estreptococos.","C":"Uretrite, conjuntivite e artrite/ clamídia.","D":"Gengivite, dermatite e artrite/ hpv.","E":"Nenhuma das alternativas."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-275969","number":"275969","sourceNumber":"275969","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Com relação a ?artrite reativa?, patologia reumática que pertence à família das\nespondiloartropatias, podemos afirmar que:","options":{"A":"Não é precedida por processos infecciosos.","B":"Não apresentam associação com inflamação do esqueleto axial ou alteração da dosagem de\nHLA-B27 (antígeno leucocitário).","C":"Além da artralgia não apresentam alterações clínicas adicionais.","D":"Infecção venérea ou desinteria precedem em geral o quadro articular.","E":"Nenhuma das alternativas."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-216214","number":"216214","sourceNumber":"216214","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A Artrite Psoríaca (AP), comumente chamada de psoriásica ou psoriática, tem sido\ndefinida como uma artrite inflamatória crônica\nassociada à psoríase. Está INADEQUADO o seguinte\nitem:","options":{"A":"Dentre suas manifestações clínicas cardinais, destacam-se acometimentos articulares periférico\ne axial, entesites, tenossinovites e\ndactilites.","B":"A AP caracteriza-se também por apresentar diversas manifestações extra-articulares típicas.","C":"Caracterizam-se também por apresentar diversas manifestações entre elas os envolvimentos\ncutâneo (psoríase cutânea), ungueal\n(onicodistrofia), ocular (uveíte anterior).","D":"Caracteriza-se também por apresentar diversas manifestações cardiovascular (doença valvar\naórtica e aterosclerose), pulmonar (pneumonite intersticial) e renal (amiloidose, nefropatia sem\ndepósito de IgA)."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-216241","number":"216241","sourceNumber":"216241","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em relação ao diagnóstico diferencial, a Artrite Psoríaca - AP se distingue da Artrite\nReumatoide pelas seguintes características clínicas:","options":{"A":"Assimetria do envolvimento articular e acometimento da coluna lombar.","B":"Apresentação oligoarticular, entesite e irite.","C":"Fator reumatoide positivo.","D":"Lesões ungueais."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-215542","number":"215542","sourceNumber":"215542","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A Artrite Reumatoide - AR é bastante variável quanto à apresentação clínica, à\ngravidade e ao prognóstico, está CORRETO apenas que:","options":{"A":"Sua forma clínica mais comum é a poliartrite simétrica de pequenas e grandes articulações com\ncaráter crônico e destrutivo, podendo levar a relevante limitação funcional.","B":"Sua forma clínica mais rara é a poliartrite simétrica de pequenas e grandes articulações com\ncaráter crônico e destrutivo, podendo levar a relevante limitação funcional.","C":"Sua forma clínica mais comum é a poliartrite assimétrica de pequenas e grandes articulações\ncom caráter crônico e destrutivo, podendo levar a\nrelevante limitação funcional.","D":"Sua forma clínica mais comum é a poliartrite simétrica de pequenas e grandes articulações com\ncaráter crônico e destrutivo, que nunca leva a relevante limitação funcional."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-216311","number":"216311","sourceNumber":"216311","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A Artrite Psoríaca (AP), tem sido definida como uma artrite inflamatória crônica\nassociada à psoríase, descrições iniciais da\ndoença sugeriram que a AP possui manifestações\nclínicas mais brandas quando comparada a outras artrites inflamatórias crônicas. Sendo assim,\npodemos apenas aceitar um dos itens abaixo como ERRADO:","options":{"A":"Em relação à patogênese, a AP é uma doença autoimune poligênica, de etiologia indefinida.","B":"As citocinas relacionadas a linfócito T desempenham papel central.","C":"A ocorrência da AP está ligada a uma suscetibilidade genética complexa, associada a fatores\nambientais e não a mecanismos imunológicos.","D":"Os fatores ambientais (microtrauma e agentes infecciosos) têm sido relacionados."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-219899","number":"219899","sourceNumber":"219899","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Escolar de 10 anos de idade é trazida ao controle na unidade básica de saúde com\nhistória de ter cardiopatia reumática:\nprimeiro surto de febre reumática aos seis anos de idade, dois\nsurtos subsequentes, com acometimento das valvas mitral e aórtica. No momento, apesar do\ntratamento utilizado (fez pulsoterapia com corticosteroides no último surto) ainda apresenta\nsintomas (cansaço ao brincar e \"coração disparado\") e na ausculta cardíaca, além de taquicardia\nleve, apresenta sopro sistólico holossistólico de grande intensidade, mas audível na área mitral,\nirradiando para axila. Faz uso regular de penicilina benzatina (21 em 21 dias). O motivo da consulta\né o desejo da mãe de parar de aplicar injeções de penicilina (\"doem muito, fico com pena dela, tão\nmagrinha!\"). Qual a orientação que deve ser dada à mãe a respeito das injeções, após explicações\nsobre a necessidade da profilaxia?","options":{"A":"Deve usar profilaxia com penicilina benzatina até cinco anos após o último surto.","B":"Deve usar profilaxia com penicilina benzatina até os 40 anos de idade ou por toda vida.","C":"Deve usar profilaxia com penicilina benzatina de 21 em 21 dias até os 21 anos de idade.","D":"Deve usar profilaxia com penicilina benzatina por um ano após estar assintomático."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-219911","number":"219911","sourceNumber":"219911","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Com relação à febre reumática aguda, é CORRETO afirmar:","options":{"A":"As manifestações maiores da febre reumática aguda compreendem artralgia, cardite, coreia de\nSydenham, nódulos subcutâneos e eritema nodoso.","B":"Embora as sequelas sejam observadas classicamente a nível do endocárdio, miocardite e\npericardite são mais intensas do que a endocardite.","C":"A evolução das manifestações articulares não é modificada pelo uso de anti-inflamatório não\nesteroide ou corticosteroide.","D":"Os joelhos, tornozelos, punhos e cotovelos são as articulações mais frequentemente\nacometidas."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-215213","number":"215213","sourceNumber":"215213","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A Artrite Reumatoide (AR) é bastante variável quanto à apresentação clínica, à\ngravidade e ao prognóstico. Sua forma clínica\nmais comum é a poliartrite simétrica de pequenas e\ngrandes articulações com caráter crônico e destrutivo, podendo levar a relevante limitação\nfuncional, comprometendo a capacidade laboral e a qualidade de vida, estando inadequado o\nseguinte item:","options":{"A":"Pode resultar em significativo impacto pessoal e social, com elevados custos indiretos, segundo\nestimativas nacionais.","B":"A associação de AR a neutropenia e esplenomegalia, que ocorre mais nos casos de AR de\nlonga evolução, é chamada de síndrome de Felty.","C":"Dados de um estudo brasileiro de pacientes com AR inicial sugerem que a apresentação clínica\nmais comum seja a poliartrite aguda (70%) com sinovite persistente nas mãos (91%) e rigidez\nmatinal prolongada (mais de 2 horas).","D":"A rigidez matinal pode ser o sintoma inicial e costuma ser um indício de doença sem atividade."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-215216","number":"215216","sourceNumber":"215216","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"O tratamento de Artrite reumatoide (AR) deve ser iniciado o mais breve possível, uma\nvez que a terapia medicamentosa intensiva\ninstituída precocemente previne danos estruturais\n(erosões), melhorando a capacidade funcional, sendo CORRETO que:","options":{"A":"O tratamento não medicamentoso de AR exclui educação do paciente e de sua família, que não\napresenta resultados, fisioterapia, apoio psicossocial e cirurgia.","B":"O tratamento não medicamentoso de AR inclui educação do paciente e de sua família, terapia\nocupacional, exercícios, fisioterapia, apoio psicossocial e cirurgia.","C":"O tratamento não medicamentoso de AR inclui educação do paciente e de sua família, terapia\nocupacional, exercícios, fisioterapia e apoio psicossocial se mostram desnecessários.","D":"O tratamento não medicamentoso de AR inclui educação do paciente, não permitindo\nparticipação de sua família."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-215289","number":"215289","sourceNumber":"215289","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A Artrite Reumatoide (AR) é uma doença autoimune, inflamatória, sistêmica e crônica,\ncaracterizada por sinovite periférica e por diversas manifestações extra-articulares. Quanto a isso,\npodemos considerar inadequado que:","options":{"A":"Apesar de a etiopatogenia de AR ainda não ser inteiramente conhecida, muito se avançou no\ntema nos últimos anos.","B":"No início, a observação do aumento da incidência de AR entre familiares, principalmente entre\ngêmeos heterozigóticos, sugeria um componente genético em sua etiopatogênese.","C":"Foi identificado o antígeno leucocitário humano (Human Leukocyte Antigen - HLA), considerado\no principal fator genético no desenvolvimento\ndessa doença.","D":"Diversos alelos de HLA-DRB1 vêm sendo associados a AR em populações variadas."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-212203","number":"212203","sourceNumber":"212203","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Jean, 07 anos de idade, chega ao pronto-socorro com quadro de insuficiência cardíaca\ncaracterizado pela presença de ritmo de galope, sem descrição de patologia cardíaca anterior. Foi\nrealizado ecocardiograma que evidenciou insuficiência mitral, sem outras alterações. Assinale a\nalternativa que apresente diagnóstico mais provável para Jean.","options":{"A":"Sepse.","B":"Miocardite viral.","C":"Febre Reumática.","D":"Doença de Kawasaki.","E":"Miocardiopatia chagásica."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-187772","number":"187772","sourceNumber":"187772","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente sexo feminino, 46 anos, procura atendimento em hospital com queixa principal\nde \"dor no corpo inteiro\". Pela história da\ndoença atual, percebeu-se que as dores são intensas,\ncom início logo ao despertar e duração maior que 18 horas, alternando com dias sem dor e ausente\nem pelo menos 6 meses durante o ano. A história pregressa revelou que a paciente\nfrequentemente acorda com sensação de fadiga, independentemente de estar com dor. É\nportadora de cefaléia de forte intensidade com característica de ser de origem tensional e já fez\nconsulta psiquiátrica para tratamento de depressão. Ao exame físico percebe-se dor a\ndigitopressão em região occipital, músculo trapézio, quadrante superior externo da nádega,\nepicôndilo lateral e joelho (para todos os pontos a dor foi bilateral). Assinale a alternativa\nCORRETA quanto ao diagnóstico MAIS PROVÁVEL:","options":{"A":"Artrite reumatóide","B":"Esclerodermia","C":"Fibromialgia","D":"Gota"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-187783","number":"187783","sourceNumber":"187783","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente sexo feminino, 46 anos, procura atendimento em hospital com queixa principal\nde \"dor no corpo inteiro\". Pela história da\ndoença atual, percebeu-se que as dores são intensas,\ncom início logo ao despertar e duração maior que 18 horas, alternando com dias sem dor e ausente\nem pelo menos 6 meses durante o ano. A história pregressa revelou que a paciente\nfrequentemente acorda com sensação de fadiga, independentemente de estar com dor. É\nportadora de cefaléia com forte intensidade com característica de ser de origem tensional e já fez\nconsulta psiquiátrica para tratamento de depressão. Ao exame físico percebe-se dor a\ndigitopressão em região occipital, músculo trapézio, quadrante superior externo da nádega,\nepicôndilo lateral e joelho (para todos os pontos a dor foi bilateral). Assinale a alternativa\nCORRETA quanto à terapia a ser instituída:","options":{"A":"Agentes antibióticos por 30 dias como doxiciclina por via oral","B":"Colchicina, anti-inflamatório não hormonal e aplicação de compressa gelada","C":"Tratar comorbidades, evitar opioides e utilizar medicação analgésica que promova sono como a\namitriptilina","D":"Utilizar cloreto de vinilia, bleomicina e pentazocina"},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-161265","number":"161265","sourceNumber":"161265","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A artrite reumatoide apresenta caráter crônico e destrutivo, que pode levar à importante\nlimitação funcional, com perda da capacidade laboral e qualidade de vida, a menos que o\ndiagnóstico seja feito em fase inicial da doença e o tratamento determine melhora clínica. A\nrespeito\nda doença, assinale a alternativa INCORRETA.","options":{"A":"O período inicial da doença é considerado uma janela de oportunidade terapêutica.","B":"O período inicial da doença é considerado um momento em que a intervenção farmacológica\nrápida e efetiva pode mudar o curso da doença em\nlongo prazo.","C":"O período inicial da doença, em especial seus 24 primeiros meses, é o chamado AR inicial.","D":"Esses fatores resultaram no melhor controle clínico da doença, com a possibilidade de remissão\nsustentada da AR."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-161280","number":"161280","sourceNumber":"161280","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Quando analisamos a Artrite Reumatoide (AR), conceituamos que é uma doença\nsistêmica, inflamatória, autoimune, que se\ncaracteriza pelo comprometimento da membrana sinovial\npreferencialmente das articulações periféricas. Quanto a sua epidemiologia, podemos considerar\ndiversos fatores, com EXCEÇÃO de um deles. Indique-o.","options":{"A":"Sua prevalência seja de 0,5% a 1% da população.","B":"Ocorre predominando no sexo masculino.","C":"Ocorre mais na faixa etária dos 30 aos 50 anos.","D":"O acometimento em geral simétrico das pequenas e grandes articulações é a característica\nprincipal da AR, sendo comum o envolvimento das\nmãos e pés."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-158761","number":"158761","sourceNumber":"158761","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A profilaxia secundária na febre reumática é indicada para evitar novos surtos da\ndoença. Em que consiste esse tratamento?","options":{"A":"Administração de eritromicina, nos casos de alergia à penicilina e à sulfa, na dose de 500\nmg/dia, de 6/6h.","B":"Aplicação de penicilina G benzatina até a terceira década de vida nos pacientes com lesão\nvalvar residual moderada a\n\nsevera.","C":"Administração de sulfadiazina nos pacientes alérgicos, em dose de 300 mg/dia até 30 kg e 500\nmg/dia naqueles acima desse peso.","D":"Aplicação de penicilina G benzatina a cada 21 dias até 21 anos ou até cinco anos após o último\nsurto nos pacientes com doença cardíaca.","E":"Aplicação de penicilina G benzatina a cada 21 dias até 25 anos ou 10 anos após o último surto\nnos pacientes com febre\n\nreumática com cardite prévia, insuficiência mitral residual ou resolução de lesão valvar."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-158792","number":"158792","sourceNumber":"158792","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A febre reumática pode ser considerada um quebra-cabeças que somente foi\ncompletamente montado em 1886, quando as\nmanifestações articulares, cardíacas e neurológicas\nforam reconhecidas como parte da síndrome. Em 2004, a Organização Mundial de Saúde definiu\nnovos critérios, a partir dos de Jones para o diagnóstico do primeiro surto, e para cardiopatia\nreumática crônica. Esses critérios foram revisados pela American Heart Association, que passou a\nadotar critérios diferenciados conforme populações classificadas em baixo, médio ou alto risco.\n\nAssim, dadas as afirmativas, I. Para populações de baixo risco, a mono ou poliartrite ou\npoliartralgia\ncaracteriza critério maior de Jones revisado.; II. Para populações de baixo risco, a poliartralgia\ncaracteriza critério menor de Jones revisado.; III. Para populações de baixo risco, VHS (velocidade\nde hemossedimentação) maior/igual a 60 mm e/ ou PCR (proteína C reativa) maior/ igual a 3.0\ncaracterizam critério menor de Jones revisado.; IV. Tanto para populações de baixo quanto para de\nmoderado e alto risco, a febre caracteriza critério menor de Jones revisados.; Verifica-se que estão\ncorretas apenas:","options":{"A":"II, III e IV.","B":"I, III e IV.","C":"II e III.","D":"I e IV.","E":"I e II."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-86600","number":"86600","sourceNumber":"86600","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Assinale a alternativa que apresenta manifestações clínicas e/ou alterações em exames\ncomplementares sugestivas de artrite psoriásica: I ? Envolvimento articular assimétrico; II ?\n\nArtropatia de Jaccoud; III ? Envolvimento de articulações interfalangianas distais na ausência de\nosteoartrose; IV - Ausência de fator reumatoide; V ? Síndrome nefrótica.","options":{"A":"I, II e III.","B":"I, IV e V.","C":"II, III e IV.","D":"III, IV e V.","E":"I, III e IV."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-86607","number":"86607","sourceNumber":"86607","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Qual das doenças abaixo NÃO apresenta o Fator Antinuclear (FAN) positivo:","options":{"A":"Artrite reativa.","B":"Hepatite C.","C":"Lúpus Eritematoso Sistêmico.","D":"Linfoma Não Hodgkin.","E":"Tiroidite de Hashimoto."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-49599","number":"49599","sourceNumber":"49599","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"NÃO é uma característica clínica típica de pacientes com artrite reumatoide:","options":{"A":"Artrite destrutiva.","B":"Nódulos reumatoides.","C":"Dedos em \"pescoço de cisne\".","D":"Articulações de Jaccoud.","E":"Desvio ulnar dos dedos."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-362486","number":"362486","sourceNumber":"362486","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Jovem de 15 anos, morador de Parintins procurou o hospital da cidade queixando de\nfalta de ar, mal-estar geral, febre e dores\nem grandes articulações de início há 1 semana. Ao exame\nfísico, paciente se encontrava taquicárdica FC 130 bpm, com temperatura de 38,5ºC. A ausculta\ncardíaca, sopro sistólico 3+/6 em foco mitral irradiando para região axilar, joelho direito com\nhiperemia e calor local com critérios para artrite e nódulos firmes, móveis e indolores em região de\ncoluna vertebral. Foi realizado exames laboratoriais que demonstrou velocidade de\nhemossedimentação (VHS) de 55mm. Segundo os critérios de Jones revisado para o diagnóstico\nde febre reumática, este paciente apresenta:","options":{"A":"Um critério maior e três menores.","B":"Dois critérios maiores e um menor.","C":"Dois critérios maiores e dois menores.","D":"Três critérios maiores e dois menores."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-362481","number":"362481","sourceNumber":"362481","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Doença inflamatória crônica que acomete, preferencialmente, a coluna vertebral. É mais\nfrequente no sexo masculino, no adulto jovem e HLA-B27. Quadro clínico de dor lombar de ritmo\ninflamatório. A evolução costuma ser ascendente, acometendo progressivamente a coluna dorsal e\ncervical. Assinale a alternativa que corresponde CORRETAMENTE à doença caracterizada\nanteriormente.","options":{"A":"Hérnia discal.","B":"Artrite psoriásica.","C":"Artrite reumatoide.","D":"Espondilite anquilosante."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-362480","number":"362480","sourceNumber":"362480","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 67 anos vem à consulta com queixa de dor intensa em joelho direito há 8\ndias. Refere episódios semelhantes autolimitados acometendo punho direito e joelhos, bem como\nartralgia mecânica recorrente de joelhos bilateralmente há cerca de 2 anos. Ao exame, apresenta\ndor, calor, edema e eritema de joelho direito. Sem outros dados clínicos relevantes. Qual o\ndiagnóstico mais provável?","options":{"A":"Artrite viral.","B":"Artrite reativa","C":"Artrite tuberculosa.","D":"Artrite microcristalina."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-327239","number":"327239","sourceNumber":"327239","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Na artrite reumatoide, qual é o padrão mais comum de comprometimento articular?\nAssinale a alternativa CORRETA:","options":{"A":"Oligoarticular assimétrico, aditivo.","B":"Poliarticular migratório, assimétrico.","C":"Poliarticular, simétrico, aditivo.","D":"Monoarticular recorrente."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-298207","number":"298207","sourceNumber":"298207","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 19 anos apresentando há 4 dias poliartralgia e febre de 38,7ºC. Ao exame\nfísico artrite de tornozelo esquerdo e tenossinovite de punho direito e presença de lesões pápulo\neritematosas e algumas pústulas em região anterior das pernas. No hemograma leucócitos de\n\n18.000 e PCR de 40. Diante deste quadro, assinale a alternativa com a melhor opção de hipótese\ndiagnóstica/conduta:","options":{"A":"Artrite reativa; iniciar anti-inflamatório não hormonal.","B":"Gota; solicitar dosagem de ácido úrico sérico e iniciar corticoide oral.","C":"Artrite infecciosa; iniciar ceftriaxona e azitromicina.","D":"Artrite infecciosa; iniciar oxacilina."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-286715","number":"286715","sourceNumber":"286715","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Artrite reativa é definida como artrite que se desenvolve logo depois de uma infecção\nem outros órgãos que não sejam as\narticulações. A relação de germes mais frequentemente\nimplicados no desenvolvimento da artrite reativa NÃO inclui:","options":{"A":"Chlamydia pneumoniae.","B":"Staphylococcus aureus.","C":"Campylobacter jejuni.","D":"Clostridioides (antigo Clostridium) difficile."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-286716","number":"286716","sourceNumber":"286716","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem, 30 anos, queixa-se de dor lombar que persiste há 10 meses, com rigidez local\nprolongada, que piora com o repouso, resultando em dificuldade para sair da cama de manhã e\nnecessidade de rolar de lado, tentando não flexionar ou girar a coluna vertebral para diminuir a\ndor.\nAo analisar as radiografias de coluna lombossacra e bacia é provável observar:","options":{"A":"Osteófitos e redução dos espaços discais.","B":"Sacroileíte com irregularidade no contorno das articulações sacroilíacas e esclerose óssea de\nsacro e ilíaco.","C":"Destruição de corpo vertebral com fraturas em cunha.","D":"Osteoporose com fraturas por compressão de L3?L5."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-252214","number":"252214","sourceNumber":"252214","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente de 10 anos com diagnóstico de febre reumática, sem cardite, deve manter\nprofilaxia secundária com penicilina benzatina\naté quando? Assinale a alternativa com o esquema\nCORRETO de profilaxia para este caso:","options":{"A":"Penicilina benzatina IM a cada 21 dias até os 21 anos ou 5 anos após o último surto (vale o que\ncobrir maior tempo).","B":"Penicilina benzatina IM a cada 30 dias até os 21 anos ou 10 anos após o último surto (vale o que\ncobrir maior tempo).","C":"Penicilina benzatina IM a cada 15 dias até os 18 anos ou 5 anos após o último surto (vale o que\ncobrir maior tempo).","D":"Penicilina benzatina IM a cada 21 dias até os 25 anos ou 10 anos após o último surto (vale o\nque cobrir maior tempo)."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-252215","number":"252215","sourceNumber":"252215","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente 50 anos, sexo masculino, diagnóstico de artrite reumatoide há 5 anos em uso\nde Metotrexato e Prednisona. Vem para consulta\nqueixando de dor em joelho D iniciada há 4\nmeses. Relata ainda febre baixa intermitente e perda ponderal de 3 kg. Ao exame nota-se edema\ncom derrame, calor e limitação de movimentos no joelho D. Tem dor a palpação em punhos, mas\nsem edema ou calor. Qual a provável etiologia da artrite e conduta apropriada?","options":{"A":"Artrite infecciosa / iniciar antibioticoterapia empírica","B":"Atividade da doença / infiltrar joelho com corticoide","C":"Atividade da doença / aumentar corticoide oral","D":"Artrite infecciosa / artrocentese e análise do líquido sinovial"},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-208392","number":"208392","sourceNumber":"208392","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Os nódulos de Heberden são características de:","options":{"A":"Artropatia de Jaccoud.","B":"Artrite psoriásica.","C":"Osteoartrite.","D":"Osteoartropatia hipertrófica."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-208408","number":"208408","sourceNumber":"208408","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente de 42 anos, sexo masculino, obeso, procura atendimento por crise de\nmonoartrite de joelho direito com início há\n24 horas, de forte intensidade, com calor e derrame\narticular. Relata ser o terceiro episódio de artrite em menos de 1 ano e que as crises melhoram com\nuso de AINH. Assinale a alternativa com a melhor opção para esclarecimento diagnóstico:","options":{"A":"Artrocentese + pesquisa de cristais no líquido sinovial.","B":"Solicitar hemograma.","C":"Solicitar hemocultura.","D":"Dosar ácido úrico sérico e urinário."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-176033","number":"176033","sourceNumber":"176033","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"São características da lombalgia de ritmo inflamatório:","options":{"A":"Dor lombar aguda que piora com a atividade física e melhora após repouso prolongado.","B":"Dor lombar crônica que piora após o repouso prolongado e melhora com a atividade física.","C":"Dor lombar crônica que piora com a atividade física e melhora após o repouso, especialmente\npela manhã.","D":"Dor lombar crônica que não varia com repouso ou atividade física."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-151937","number":"151937","sourceNumber":"151937","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"O antibiótico de primeira linha para erradicação do Estreptococo beta hemolítico (do\ngrupo A) da orofaringe, no tratamento da febre reumática é:","options":{"A":"Cefalexina.","B":"Tetraciclina.","C":"Claritromicin.","D":"Penicilina benzatina."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-129767","number":"129767","sourceNumber":"129767","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um adolescente de 15 anos apresenta-se com dor no joelho direito. Ao exame físico,\nele não consegue apoiar seu próprio peso\nsobre a articulação afetada. O joelho está dolorido,\nedemaciado, quente, eritematoso e apresenta uma significativa redução da amplitude de\nmovimento. Qual das opções a seguir representa o melhor passo na avaliação?","options":{"A":"Prescrever um curso de esteroides sistêmicos.","B":"Obter mais dados da história, incluindo história sexual.","C":"Marcar uma consulta ambulatorial com ortopedista.","D":"Prescrever anti-inflamatórios."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-108011","number":"108011","sourceNumber":"108011","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"São achados radiológicos da osteoartrite: I. Osteófitos; II. Erosões; III. Cistos\nsubcondrais; IV. Esclerose do osso subcondral.\nCom relação às afirmativas acima, é CORRETO\nafirmar que: (VER IMAGEM)","options":{"A":"Somente as afirmativas I, II e III são corretas.","B":"Somente as afirmativas II, III e IV são corretas.","C":"Somente as afirmativas I, III e IV são corretas.","D":"Somente as afirmativas I, II e IV são corretas."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-103845","number":"103845","sourceNumber":"103845","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente do sexo masculino, 19 anos, evoluindo há 10 meses com artrite do tornozelo\ndireito, joelho esquerdo, cotovelo direito e\nlombalgia tipo inflamatória. A hipótese diagnóstica é de\nespondilite anquilosante. Qual o exame que auxilia no diagnóstico?","options":{"A":"HLA-B27.","B":"VHS.","C":"Anti-DNA de dupla hélice.","D":"Waaler-Rose."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-81980","number":"81980","sourceNumber":"81980","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Dos medicamentos abaixo, todos são utilizados no tratamento da artrite reumatoide,\nEXCETO:","options":{"A":"Metotrexato.","B":"Rituximabe.","C":"Hidroxicloroquina.","D":"Leflunomida.","E":"Belimumabe."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-60821","number":"60821","sourceNumber":"60821","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Na Artrite Reumatoide é correto afirmar, EXCETO:","options":{"A":"A PCR e VHS são exames frequentemente utilizados para avaliar a presença e intensidade do\nprocesso inflamatório da doença.","B":"Metotrexato, Hidroxicloroquina, sulfassalazina e leflunomida são fármacos antirreumáticos\nmodificadores do curso da doença.","C":"O envolvimento pulmonar é comum e geralmente se manifesta de maneira discreta.","D":"Anti-CCP e Fator Reumatoide são os principais marcadores imunológicos.","E":"Infliximabe é um agente biológico utilizado no tratamento e atua depletando linfócito B."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-60827","number":"60827","sourceNumber":"60827","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Quanto às espondiloartrites, é CORRETO afirmar:","options":{"A":"Não existe um marcador genético.","B":"O acometimento ocular é raro, principalmente os casos de uveíte.","C":"No início da doença, o paciente costuma queixar-se de lombalgia tipo mecânica.","D":"Os anti-inflamatórios não hormonais devem ser utilizados desde o início do tratamento.","E":"O acometimento articular periférico cursa com oligoartrite, tendendo a poupar as ênteses."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-46674","number":"46674","sourceNumber":"46674","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Quanto à Artrite Reumatoide (AR) é INCORRETO afirmar:","options":{"A":"Na AR, a membrana sinovial caracteriza-se por uma neoformação vascular importante e uma\ninvasão marcante de células inflamatórias e imunes, formando um tecido chamado pannus.","B":"As articulações esternoclaviculares e manubrioesternal não são acometidas na AR por não\npossuírem sinóvia.","C":"Nódulos reumatoides, escleromalácia e doença pulmonar intersticial são manifestações\nextra-articulares da AR.","D":"A presença de Velocidade de Hemossedimentação (VHS) e Proteína C-Reativa (PCR) elevados,\ne Fator Reumatoide e Anti-CCP positivos ajudam\na caracterizar a natureza imunoinflamatória da\nAR.","E":"Metotrexato, Leflunomida e Hidroxicloroquina são fármacos antirreumáticos modificadores da\ndoença (DMARD)."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-26447","number":"26447","sourceNumber":"26447","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Comprometimento pulmonar grave é mais frequente em:","options":{"A":"esclerose sistêmica progressiva","B":"artrite reumatoide","C":"lúpus eritematoso sistêmico","D":"doença de Beçhet","E":"síndrome de Raynoud"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-7491","number":"7491","sourceNumber":"7491","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Com relação às artrites reativas, assinale a afirmativa CORRETA:","options":{"A":"O estreptococo é agente causal mais comum.","B":"O agente causal é cultivado facilmente a partir do líquido sinovial da articulação afetada.","C":"Os dois principais tipos de artrite reativa são pós-uretrite e pós-disentérica.","D":"Podem ocorrer manifestações associadas tais como conjuntivite, enterite, sacroileíte e GN.","E":"Antibioticoterapia é a principal medida terapêutica."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-13278","number":"13278","sourceNumber":"13278","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente tem diagnóstico de lúpus eritematoso sistêmico há 4 anos, com acometimento\nrenal hematológico, neurológico e cutâneo,\ndependente de corticoide. Nos últimos 6 meses usou 10\ngramas de corticoide e 6 gramas de ciclofosfamida. Há dois meses vem queixando-se de dor na\nregião do quadril direito, principalmente no final do dia após longas caminhadas. A provável causa\nda dor é:","options":{"A":"Artrite pelo LES.","B":"Artrite séptica.","C":"Necrose avascular de colo do fêmur.","D":"Bursite hansênica.","E":"Lombociatalgia."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-324695","number":"324695","sourceNumber":"324695","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menina, 5 anos de idade, é atendida na UPA com história de dor no joelho esquerdo,\nreferindo, também, aumento de volume e limitação\nde movimentos, principalmente ao acordar.\n\nRelata que essa dor iniciou há 2 meses, sem trauma, evoluindo para acometimento de ombro\nesquerdo, joelho direito e quadris,\nbilateralmente. Há 15 dias, vem com envolvimento de punhos,\ncom mesmas características, além de febre com exantema. Queixa-se de dor ocular, que \"\"piora\ncom luz forte\"\" e que seus olhos ficam, permanentemente, vermelhos. Relata, ainda, dor ao\nmastigar e abrir a boca. Ao exame, a menor apresenta hiperemia ocular. Temperatura 38,0ºC.\nNota-se exantema cor de salmão em axilas e zonas de pressão. Apresenta discreta\nhepatoesplenomegalia. Linfonodos sem características patológicas. Nas articulações em foco,\nobservam-se edema, calor e redução da amplitude de movimentos. Hemograma mostra 15mil\nleucócitos/mm³ às custas de polimorfonucleares, com 400mil plaquetas/mm³. Considerando o\ndiagnóstico mais provável, sobre a avaliação laboratorial dessa criança, é correto afirmar:","options":{"A":"Fator Antinuclear é sempre positivo.","B":"Proteína C Reativa não é exame indicado.","C":"VHS normal não exclui diagnóstico","D":"Fator Reumatóide é positivo em mais de 80% dos casos iniciais."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-324696","number":"324696","sourceNumber":"324696","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menina, 5 anos de idade, é atendida na UPA com história de dor no joelho esquerdo,\nreferindo, também, aumento de volume e limitação\nde movimentos, principalmente ao acordar.\n\nRelata que essa dor iniciou há 2 meses, sem trauma, evoluindo para acometimento de ombro\nesquerdo, joelho direito e quadris,\nbilateralmente. Há 15 dias, vem com envolvimento de punhos,\ncom mesmas características, além de febre com exantema. Queixa-se de dor ocular, que \"\"piora\ncom luz forte\"\" e que seus olhos ficam, permanentemente, vermelhos. Relata, ainda, dor ao\nmastigar e abrir a boca. Ao exame, a menor apresenta hiperemia ocular. Temperatura 38,0ºC.\nNota-se exantema cor de salmão em axilas e zonas de pressão. Apresenta discreta\nhepatoesplenomegalia. Linfonodos sem características patológicas. Nas articulações em foco,\nobservam-se edema, calor e redução da amplitude de movimentos. Hemograma mostra 15mil\nleucócitos/mm³ às custas de polimorfonucleares, com 400mil plaquetas/mm³. Considerando a febre\nque, usualmente, acompanha quadros semelhantes, pode-se afirmar que costuma ser:","options":{"A":"Diária e elevada, em picos, com retorno à temperatura normal.","B":"Irregular, com variação de horários e dias sem febre.","C":"Contínua e baixa, associada à cefaleia.","D":"Elevada e contínua, com prostração intensa."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-324697","number":"324697","sourceNumber":"324697","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menina, 5 anos de idade, é atendida na UPA com história de dor no joelho esquerdo,\nreferindo, também, aumento de volume e limitação\nde movimentos, principalmente ao acordar.\n\nRelata que essa dor iniciou há 2 meses, sem trauma, evoluindo para acometimento de ombro\nesquerdo, joelho direito e quadris,\nbilateralmente. Há 15 dias, vem com envolvimento de punhos,\ncom mesmas características, além de febre com exantema. Queixa-se de dor ocular, que \"\"piora\ncom luz forte\"\" e que seus olhos ficam, permanentemente, vermelhos. Relata, ainda, dor ao\nmastigar e abrir a boca. Ao exame, a menor apresenta hiperemia ocular. Temperatura 38,0ºC.\nNota-se exantema cor de salmão em axilas e zonas de pressão. Apresenta discreta\nhepatoesplenomegalia. Linfonodos sem características patológicas. Nas articulações em foco,\nobservam-se edema, calor e redução da amplitude de movimentos. Hemograma mostra 15mil\nleucócitos/mm³ às custas de polimorfonucleares, com 400mil plaquetas/mm³. Considerando a\nhipótese diagnóstica mais provável, a complicação grave mais temível é:","options":{"A":"Insuficiência renal crônica.","B":"Insuficiência hepática aguda.","C":"Lesão de válvulas cardíacas.","D":"Síndrome de ativação macrofágica."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-49308","number":"49308","sourceNumber":"49308","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente, cinco anos de idade, sexo masculino, pardo, internado com história de febre e\ndor articular há seis meses. A dor iniciou nos braços, evoluindo para pernas, tornozelos e pescoço,\ncom edema e calor nas articulações dos cotovelos, punhos, mãos, joelhos e tornozelos, com\nrestrição de movimentos. Tem história de exantema maculopapular em tronco, que durou duas\nsemanas. REG, descorado ++/IV, febril, emagrecido, limitação na extensão da coluna cervical,\nfígado palpável a 2 cm de RCD. Exames: Hb = 6,8; Ht = 23; leuc. = 10.700 (Bt. = 0%, seg. = 46%,\neos. = 3%, linf. = 43%, mon. = 8%); reticulócitos = 1,1%; plaq. = 959.000/mm³; VHS = 37;\ncoagulograma normal; função renal e função hepática normais; fator reumatoide negativo;\nultrassonografia do joelho esquerdo: derrame articular. O diagnóstico mais provável é:","options":{"A":"FR.","B":"AIJ.","C":"Osteomielite aguda.","D":"Osteopenia própria da infância.","E":"Dor do crescimento."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-34971","number":"34971","sourceNumber":"34971","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente, 5 anos de idade, vem há quatro meses com dor articular e febre em picos\ndiários. Ao exame, FC: 128 bpm, FR: 26 ipm,\nfebril, edema e calor em joelho e tornozelo\nesquerdos, ausculta cardíaca com bulhas abafadas, sem sopros. Hemograma com Hb de 12, série\nbranca e plaquetas normais, VHS elevado. Reticulócitos normais. O quadro apresentado sugere:","options":{"A":"doença de Kawasaki.","B":"febre reumática.","C":"AIJ.","D":"citomegalovirose aguda.","E":"esferocitose."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-11138","number":"11138","sourceNumber":"11138","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Com o uso prolongado de corticosteroides, são efeitos colaterais esperados, exceto:","options":{"A":"perda de massa óssea","B":"doença aterosclerótica periférica","C":"amenorreia","D":"atrofia muscular","E":"leucopenia"},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-215612","number":"215612","sourceNumber":"215612","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Embora os estudos epidemiológicos sobre a Artrite Psoríaca (AP) tenham sido\ninfluenciados por uma série de fatores,\nincluindo a falta de consenso em relação aos critérios de\nclassificação, a frequência da psoríase em diferentes áreas geográficas, os diversos métodos\nutilizados no diagnóstico, bem como os diferentes desenhos de estudos avaliados, determinam os\ndados abaixo. Indique a alternativa que se mostra INCORRETA:","options":{"A":"Dois aspectos devem ser considerados na análise epidemiológica: as incidência e prevalência e\na frequência de AP em pacientes com psoríase.","B":"Estudos revelaram incidência de 3,0-23,1 casos/100.000 pessoas e prevalência de 1-420\ncasos/100.000 pessoas.","C":"Resultados similares entre os países ocidentais.","D":"Essa grande variação decorre especialmente dos diferentes critérios utilizados no diagnóstico,\nmas não do tempo de evolução da psoríase\ncutânea."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-292821","number":"292821","sourceNumber":"292821","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem, 33 anos, obeso, etilista, hipertenso em uso de hidroclorotiazida, com história\nde alta hospitalar, há 24 horas, após\ncolecistectomia, procura UPA com relato de dor intensa e\nalodínia em hálux esquerdo há 3 horas. Ao exame: estado geral regular, fácies de dor, T: 37,9°C;\nabdome flácido e ferida operatória sem sinais flogísticos; sistema osteoarticular: edema, rubor e\ndor\nà movimentação de hálux. Qual conduta está indicada neste momento?","options":{"A":"Coleta de duas amostras de hemoculturas.","B":"Punção de metatarsofalangiana.","C":"Dosagem de ácido úrico sérico.","D":"Iniciar cefalexina."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-259724","number":"259724","sourceNumber":"259724","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher, 33 anos, há 2 meses apresenta fadiga, dor em mãos, joelho esquerdo e\ntornozelo direito que pioram no repouso e\nmelhoram com atividade física. Nega queixas axiais. Há\n1 semana passou a apresentar edema difuso em 3° quirodáctilo direito. Nega alterações genitais,\nurinárias e intestinais. Ao exame: lesões eritematodescamativas em região extensora de cotovelos\ne em sulco interglúteo, depressões e sulcos transversais ungueais; dor e edema em punho direito,\n2° interfalangiana proximal esquerda e joelho esquerdo, e dor e calor em tornozelo direito. Traz os\nexames complementares: Hb 11,2 mg/dl (VR 12 mg/dl); PCR 1,65 mg/dl (VR < 0,6 mg/dl); TGO 35\ne TGP 25 (VR < 50 UI/L); ácido úrico: 5,5 mg/dl (VR 6,0 mg/dl); Cr 0,6 mg/dl (VR 1,0 mg/dl);\nsorologias para hepatites B e C, sífilis e HIV: negativas; radiografias de mãos, joelhos e\ntornozelos:\nsem alterações; FAN, fator reumatoide e anti-CCP negativos. LEGENDA: Hb: hemoglobina; VR:\nValor de Referência; PCR: Proteína C-Reativa; Cr: creatinina; FAN: Fator Antinúcleo; anti-CCP:\nanticorpos antipeptídeo citrulinado. Diante da hipótese diagnóstica mais provável, qual tratamento a\nser prescrito?","options":{"A":"Colchicina 0,5 mg/dia.","B":"Hidroxicloroquina mg/dia.","C":"Metotrexato 20 mg/semana.","D":"Sulfato de glucosamina 1.500 mg/dia."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-234035","number":"234035","sourceNumber":"234035","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 53 anos relata dor e edema em mãos e punhos há aproximadamente quatro\nmeses. Há ainda adinamia durante todo o período, além de rigidez matinal de uma hora\naproximadamente. Ao exame: sinovite do primeiro ao quinto metacarpofalangianas e\ninterfalangianas proximais de ambas as mãos bem como calor e rubor em joelhos. Trouxe exames\nrealizados previamente: fator reumatoide ELISA 120 UI/ml (VR: < 15 UI/ml). Sobre a doença em\nquestão, marque a alternativa que contempla a hipótese clínica mais provável e um exame mais\nespecífico para o quadro clínico, respectivamente.","options":{"A":"Artrite reumatoide e antipeptídeo citrulinado.","B":"Lúpus eritematoso sistêmico e fator antinúcleo.","C":"Hepatite por vírus do tipo C e proteína C-reativa.","D":"Crioglobulinemia mista tipo II e radiografia de mãos e punhos."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-234055","number":"234055","sourceNumber":"234055","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Criança de 2 anos, sexo feminino, com história de que há 6 semanas vem\napresentando dor e edema em articulações dos\njoelhos acompanhados de febre intermitente. Há\n15 dias mãe relata febre alta diária e piora do quadro articular em joelhos, quadril e tornozelos\nque\ndificulta a deambulação, principalmente, pela manhã. Refere exantema róseo e macular que se\nintensifica na vigência da febre. Ao exame físico, apresenta palidez cutânea, adenomegalia\ncervical, axilar e inguinal; esplenomegalia leve e presença de sinais flogísticos em joelhos e\ntornozelos. Ao hemograma, observa-se anemia normocrômica, leucocitose com neutrofilia e desvio\nà esquerda. Proteína C-reativa e velocidade de hemossedimentação aumentados, fator reumatoide\nnegativo. Mielograma hipercelular sem células blásticas. Qual o diagnóstico mais provável?","options":{"A":"Febre reumática.","B":"Leucemia aguda.","C":"Artrite idiopática juvenil.","D":"Mononucleose infecciosa."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-199788","number":"199788","sourceNumber":"199788","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 60 anos deu entrada no pronto atendimento com dor, edema e eritema em\njoelho esquerdo há 12 horas. Sem outros sinais e sintomas. Realizou artroplastia total de quadril\nesquerdo há 5 dias. É portador de diabetes mellitus e hipertensão arterial sistêmica, em uso de\nhidroclorotiazida, insulina e enalapril. Exames laboratoriais: proteína C-reativa = 6,0 mg/dl (VR <\n0,6\nmg/dl); creatinina = 1,3 mg/dl (VR = 0,6?1,2 mg/dl); ureia = 56 mg/dl (VR = 20?40 mg/dl); ácido\núrico = 5,8 mg/dl (VR = 2,5?7,0 mg/dl); hemograma normal. Análise do líquido sinovial de joelho\nesquerdo: turvo, amarelado, com presença de elementos alongados e agulhados, intracelulares, de\nbirrefringência negativa à luz polarizada, com 40.000/?L de leucócitos, predomínio de\npolimorfonucleares (60%) e coloração Gram-negativa. LEGENDA: VR = Valor de Referência. Qual\né o tratamento medicamentoso indicado?","options":{"A":"Colchicina.","B":"Alopurinol.","C":"Gentamicina + oxacilina.","D":"Rifampicina + isoniazida + pirazinamida + etambutol."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-199698","number":"199698","sourceNumber":"199698","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Rapaz de 13 anos tem alta hospitalar após seu último surto agudo de febre reumática\napresentando lesão valvar residual moderada. No 1º episódio, aos 8 anos, foi diagnosticada\nendocardite. Qual a recomendação em relação à duração da profilaxia secundária da febre\nreumática, nesse caso?","options":{"A":"Até 18 anos de idade ou 3 anos após último surto.","B":"Até 21 anos de idade ou 5 anos após último surto.","C":"Até 25 anos de idade ou 10 anos após último surto.","D":"Até 40 anos de idade ou por toda a vida."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-172995","number":"172995","sourceNumber":"172995","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente, sexo feminino, 46 anos, queixa de fadiga e dor em punhos há 3 meses, com\nrigidez matinal de 45 minutos. Nega outros sinais e sintomas associados. Nega viagens,\nmedicações e doenças prévias. Ao exame físico: dor, edema e limitação funcional em punhos, 2°\nMetacarpofalangiana (MCF) direita, 2° interfalangiana proximal esquerda e 4° MCF esquerda, sem\noutros achados. Exames: proteína C-reativa = 2,87 mg/dl (VR < 0,5 mg/dl); fator reumatoide = 9,4\nUI/ml (VR < 10,5 UI/ml); hemograma completo, creatinina, TSH, sumário de urina e radiografia de\ntórax: normais; sorologias para sífilis, hepatites, HIV e arboviroses: não reagentes. Que exame e\nalteração seriam úteis para confirmar a principal suspeita diagnóstica?","options":{"A":"Radiografias de mãos com osteófitos e esclerose subcondral.","B":"Anticorpos antipeptídeos citrulinados cíclicos positivos em baixos títulos.","C":"Eletroforese de proteínas séricas com hipergamaglobulinemia policlonal.","D":"Fator antinuclear positivo, título 1:80, padrão nuclear pontilhado fino denso."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-150803","number":"150803","sourceNumber":"150803","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 40 anos retorna ao ambulatório para reavaliação. Tem queixas de dor\narticular em mãos, cotovelos, tornozelos e\njoelhos, há cerca de 3 meses, com rigidez matinal que\ndura cerca de 20 minutos. Além disso, refere episódios de febre não mensurada e anorexia. Ela\ntrabalha como digitadora e tem história familiar de psoríase. Ao exame físico, você observa sinais\nde artrite em todas as interfalangianas proximais, segunda à quarta metacarpofalangianas\nbilateralmente, punhos, cotovelos e tornozelos. O hemograma revela leve anemia, VHS e PCR\nelevados, FAN = 1:80 (pontilhado fino), fator reumatoide negativo, sumário de urina, C3 e C4\nnormais. Baseado nesses dados, qual o diagnóstico mais adequado para essa paciente?","options":{"A":"Osteoartrite.","B":"Artrite psoriásica.","C":"Lúpus eritematoso.","D":"Artrite reumatoide."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-150830","number":"150830","sourceNumber":"150830","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma criança de 6 anos de idade chega ao pronto-socorro com queixas de febre alta há\ndois dias associadas com dor intensa e edema na articulação do joelho esquerdo. O resultado da\nbacterioscopia do material coletado na punção articular revelou cocos gram negativos. Qual a\nmelhor opção de tratamento antimicrobiano?","options":{"A":"Amicacina.","B":"Ceftriaxona.","C":"Oxacilina.","D":"Cefipime."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-127000","number":"127000","sourceNumber":"127000","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 45 anos é avaliada em ambulatório por poliartrite em ambas as mãos\n(interfalangianas proximais e\nmetacarpofalangianas) e joelhos, além de febre (até 38°C) e astenia.\nO quadro se iniciou há 2 meses e vem piorando. Exame físico confirma artrite em todas as\narticulações referidas, além de esplenomegalia (5 cm abaixo do rebordo costal esquerdo). Exames\nlaboratoriais ? hemograma: Hb = 12,5 g/dl; VCM = 93; leucócitos = 4.000 (segmentados = 30%;\neosinófilos = 1%; basófilos = 0,1%; linfócitos = 60%; monócitos = 8,9%); plaquetas = 150.000/mm³;\nC3 = 92 mg/dl (normal = 88?201); C4 = 20 mg/dl (normal = 12?45); creatinina = 0,8 mg/dl; VHS =\n105 mm/h; PCR = 6 mg/dl (normal até 0,3); sorologias para HIV, hepatites virais, sífilis, CMV, EBV e\nenterovírus negativas. FAN reagente 1:80 (padrão nuclear pontilhado fino); fator reumatoide = 130\nUI/ml (normal até 15); TSH = 2,5 mUI/L (normal = 0,5?5,4). Antes do resultado dos exames, foi\niniciada prednisona 10 mg por dia. No retorno, após 1 semana de tratamento, a paciente referida\nmelhora da dor e da disposição e negava novos episódios de febre; exame físico evidenciava\ndiscreta melhora. Com base nesses dados, qual conduta deve ser tomada nesse momento?","options":{"A":"Início de metotrexato.","B":"Dosagem de anti-CCP.","C":"Realização de mielograma.","D":"Aumentar dose de prednisona."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-102168","number":"102168","sourceNumber":"102168","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Eugênia, 56 anos de idade, procura seu Médico de Família por estar sofrendo dores em\nseus joelhos. Essa dor é mais frequente ao\nacordar e/ou quando fica algum tempo sentada e que\ngeralmente dura entre 20 e 25 minutos. Ao exame físico, ela mede 162 cm e pesa 80 kg. Os\njoelhos tem diminuição de mobilidade articular e sem sinais de flogose, mas você observa atrofia do\nquadríceps femoral. Ela traz um Raio-X realizado que o médico da UPA solicitou. Qual é a melhor\nopção para o tratamento farmacológico inicial dessa paciente? (VER IMAGEM).","options":{"A":"Anti-TNF via oral.","B":"Corticosteroides via oral.","C":"Salicilato em baixas doses.","D":"Acetaminofeno em altas doses."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-81297","number":"81297","sourceNumber":"81297","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Garota de 10 anos de idade é levada ao ambulatório com história de dor em membros\nhá dois meses e dificuldade para se\nmovimentar, principalmente pela manhã e após repouso.\n\nRefere ainda febre diária associada a exantema em tronco e membros. O exame físico revelou\nartrite em joelho e tornozelo direito.\nHemograma com anemia normocrômica e normocítica,\nleucocitose discreta sem desvio à esquerda e trombocitose. A dosagem de antiestreptolisina O está\nnormal, VHS e PCR aumentados. A radiografia do joelho apresenta erosão e diminuição da\ndensidade óssea em torno da articulação e diminuição do espaço articular. Considerando o quadro\nacima descrito, qual a hipótese diagnóstica mais provável?","options":{"A":"Artrite séptica.","B":"Febre reumática.","C":"Artrite idiopática juvenil.","D":"Lúpus eritematoso sistêmico."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-30862","number":"30862","sourceNumber":"30862","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Como é executado o teste de Tinel na investigação clínica da síndrome do túnel do\ncarpo?","options":{"A":"Digitopercussão sobre o nervo mediano ao nível do punho.","B":"Flexão do punho em 90 graus durante 1 minuto.","C":"Preensão firme dos dedos sobre polegar e flexão da mão.","D":"Levantamento de peso com punho reto por 3 minutos.","E":"Flexão-extensão repetitiva do punho por 1 minuto."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-36964","number":"36964","sourceNumber":"36964","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menina de 8 anos, há 7 semanas vem evoluindo com dor, edema, calor e diminuição da\nfunção acometendo 4 articulações (punhos e interfalangeanas). Na avaliação oftalmológica foi\nevidenciada uveíte. Que exame laboratorial tem maior chance de ser positivo?","options":{"A":"Fator reumatoide.","B":"Anticorpo anticardiolipina.","C":"Fator antinuclear.","D":"Anticorpo antifosfolípide."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-30888","number":"30888","sourceNumber":"30888","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente de 28 anos comparece com poliartrite acometendo metacarpofalangeanas,\ninterfalangeanas proximais, punhos e cotovelos,\nhá três meses. Refere ainda rigidez matinal\ndurando cerca de 50 min. Tem um hemograma normal, anticorpo Anti-CCP positivo e VHS de 70\nmm/h. Com base nos dados acima, qual o melhor tratamento inicial?","options":{"A":"Prednisona + infliximab.","B":"Celecoxibe + leflunomide.","C":"Prednisona + metotrexate.","D":"Celecoxibe + infliximab.","E":"Leflunomide + metotrexate."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-37404","number":"37404","sourceNumber":"37404","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Criança de 04 anos, apresentando febre há mais de duas semanas. Ao exame físico,\nobservam-se erupções morbiliformes no tronco, poliartrite, hepatoesplenomegalia e polisserosite. O\ndiagnóstico mais provável é:","options":{"A":"Sepse.","B":"Febre reumática.","C":"Artrite reumatoide juvenil.","D":"Artrite pós-viral.","E":"Nenhuma das alternativas anteriores."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-30940","number":"30940","sourceNumber":"30940","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher, 32 anos, comparece com dor nas mãos e pés há seis dias, que limita suas\natividades, e lesões de pele. O exame\nfísico mostra edema, dor e eritema no dorso das mãos e pés\ncom pequenas pústulas necróticas nas palmas das mãos. Sua última menstruação terminou há três\ndias. Qual o melhor diagnóstico?","options":{"A":"Artrite psoriática.","B":"Artrite gonocócica.","C":"Gota.","D":"Artrite relacionada ao HIV.","E":"Doença de Still."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-6951","number":"6951","sourceNumber":"6951","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre as manifestações extra-articulares da Artrite Reumatoide (AR), marque o correto:","options":{"A":"Pacientes com fator reumatoide positivo apresentam nódulos reumatoides em até 30%.","B":"A vasculite reumatoide renal é comum e se correlaciona com formas soronegativas.","C":"A hipertensão pulmonar grave é a manifestação pulmonar mais comum.","D":"A Síndrome de Felty é comum nos estágios iniciais e consiste em esplenomegalia e leucocitose\ncom neutrofilia.","E":"Raramente ocorre neuropatia periférica, sendo o acometimento neurológico preferencialmente\nno sistema nervoso central."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-13434","number":"13434","sourceNumber":"13434","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 28 anos, com artrite reumatoide, apresenta--se com piora da artrite. Ela toma\nNaproxen 500 mg 02 vezes ao dia e prednisona 05 mg/dia. Ao exame, sinovites em várias\npequenas articulações das mãos e pés. Tem relato de Hepatite C. Qual dos seguintes é o passo\nmais apropriado na terapêutica desta paciente?","options":{"A":"Adicionar metotrexato 10 mg VO 01 vez por semana.","B":"Trocar prednisona por dexametasona 75 mg/dia.","C":"Adicionar hidroxicloroquina 400 mg VO/dia.","D":"Trocar Naproxen por Celecoxib 200 mg 02 vezes ao dia.","E":"Adicionar Leflunomida 100 mg/dia por 03 dias, depois 20\nmg VO ao dia."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-349745","number":"349745","sourceNumber":"349745","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Assinale a alternativa que apresenta corretamente as principais manifestações\nextra-articulares da artrite psoriática.","options":{"A":"Pneumopatia intersticial padrão não específico; esclerodactilia; microstomia; fenômeno de\nRaynaud.","B":"Entesite; pneumopatia intersticial usual; hipertensão pulmonar; mãos de mecânico.","C":"Sinal do Coldre; heliótropo; dactilite; ganglionopatia.","D":"Doença inflamatória intestinal; pneumopatia intersticial usual; xeroftalmia; fenômeno de\nRaynaud.","E":"Doença inflamatória intestinal; uveite; dactilite; entesite."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-322157","number":"322157","sourceNumber":"322157","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um homem de 56 anos procura atendimento médico por crise de artrite gotosa,\napresentando sinais clássicos de podagra.\nSobre o tratamento para esse caso, é correto afirmar\nque","options":{"A":"a colchicina está contraindicada se o paciente for portador de doença renal crônica e estiver em\nuso contínuo de carvedilol.","B":"o uso de corticosteroides por via oral não é recomendado.","C":"o alopurinol está indicado durante a crise aguda.","D":"o uso de inibidores de interleucina-1 é considerado tratamento de primeira escolha.","E":"a prednísona está indicada na dose de 5mg por via oral em dias alternados."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-322159","number":"322159","sourceNumber":"322159","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em relação à febre reumática, é correto afirmar que","options":{"A":"a coreia de Sydenham é considerada um critério maior para o diagnóstico, sendo muito\nfrequente na apresentação inicial (80-90%).","B":"a dor articular (artralgia) é considerada um critério menor para o diagnóstico.","C":"a presença de febre baixa é essencial para o diagnóstico.","D":"a faixa etária mais acometida é de 40 ? 50 anos.","E":"o uso de corticoides está indicado na profilaxia de febre reumática"},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-322162","number":"322162","sourceNumber":"322162","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em relação à artrite reumatoíde, é correto afirmar que;","options":{"A":"os anti-inflamatórios não esteroidais (AINE) são considerados drogas modificadoras de doença.","B":"o diagnóstico deve ser confirmado pela dosagem do fator reumatoide.","C":"a presença de marcadores agudos de inflamação (proteína C reativa ou velocidade de\nhemossedimentação) adiciona 5 pontos aos critérios mais recentes de diagnóstico.","D":"o metotrexato é considerado droga de primeira escolha.","E":"o uso de corticosteroides intra-articulares está indicado na maioria dos casos."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-305304","number":"305304","sourceNumber":"305304","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre a artrite reumatoide, é CORRETO afirmar que:","options":{"A":"70 a 80% dos pacientes apresentam Fator Reumatoide (FR) positivo em algum momento da\nvida.","B":"Corticoide oral, como prednisona, é uma das drogas de primeira escolha.","C":"Envolve exclusivamente estruturas articulares e periarticulares.","D":"O acometimento da coluna lombar é comum.","E":"A presença de Velocidade de Hemossedimentação Aumentada (VHS) tem valor preditivo\npositivo alto para o diagnóstico."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-261215","number":"261215","sourceNumber":"261215","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um paciente de 45 anos de idade foi encaminhado para avaliação de disfagia há cerca\nde seis meses, com sensação de \"parada da\ndescida do alimento\" no meio do tórax. O paciente\nrelata histórico de dispneia com piora progressiva e passado de tratamento irregular para febre\nreumática. Ao exame, observaram-se ritmo cardíaco regular em dois tempos, com sopro diastólico\naudível em ápice; FC = 86 bpm; FR = 20 ipm; e SatO2 = 95%. O esofagograma atual mostra\ncompressão extrínseca do esôfago. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Antibioticoterapia adequada com quinolona é a escolha inicial\npara evitar a ocorrência dessas complicações.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-274367","number":"274367","sourceNumber":"274367","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre a artrite gotosa, é correto afirmar que","options":{"A":"é mais comum em mulheres, na faixa de 30-40 anos.","B":"a alimentação rica em leguminosas deve ser estimulada devido ao perfil de melhora da doença\ncom esse tipo de alimento.","C":"alimentos ricos em cadeias longas de carbono com ligação insaturada devem ser estimulados.","D":"a doença na fase inicial normalmente poupa articulações do eixo central.","E":"o tratamento crônico visa diminuir os episódios de crises álgicas, sem interferir na evolução\nnatural da doença."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-255713","number":"255713","sourceNumber":"255713","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente de 50 anos de idade com eritema marginatum, pancardite, nódulos\nsubcutâneos, febre e artralgia procurou o\nreumatologista para receber um diagnóstico. Além disso,\napresentava anúria e atrito pericárdico. Considerando esse caso clínico e os conhecimentos\nmédicos correlatos, julgue o item a seguir.\n\nPacientes que têm essa patologia podem apresentar isoladamente coreia de Sydenham, que\nmelhora os movimentos durante o sono.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-214492","number":"214492","sourceNumber":"214492","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Determinada paciente de 22 anos de idade chega ao posto de saúde da família com\nhistórico de ocorrências de dores musculares e episódios intermitentes de dores em punhos e em\nmãos bilateralmente e simetricamente no último mês. Relata os episódios de dor como\nindependentes da realização de esforços. Refere ter percebido, no último mês, o surgimento de\nregiões de hiperemia e lesões de pele escamosas em cotovelos, mãos e no couro cabeludo. Ao\nexame, apresenta-se em bom estado geral, corada, hidratada, eupneica em ar ambiente, com PA =\n110 mmHg x 70 mmHg; FC = 74 bpm; FR = 21 irpm e SatO? = 98%. Considerando esse caso\nclínico e os conhecimentos médicos correlatos, julgue o item a seguir:\n\na presença de uma poliartrite periférica simétrica fala mais a favor de quadros como artrite\nreumatoide e lúpus eritematoso sistêmico,\ndiminuindo a probabilidade diagnóstica de um quadro de\nartrite psoriática.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-214498","number":"214498","sourceNumber":"214498","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Determinada paciente de 22 anos de idade chega ao posto de saúde da família com\nhistórico de ocorrências de dores musculares e episódios intermitentes de dores em punhos e em\nmãos bilateralmente e simetricamente no último mês. Relata os episódios de dor como\nindependentes da realização de esforços. Refere ter percebido, no último mês, o surgimento de\nregiões de hiperemia e lesões de pele escamosas em cotovelos, mãos e no couro cabeludo. Ao\nexame, apresenta-se em bom estado geral, corada, hidratada, eupneica em ar ambiente, com PA =\n110 mmHg x 70 mmHg, FC = 74 bpm, FR = 21 irpm e SatO? = 98%.. Considerando esse caso\nclínico e os conhecimentos médicos correlatos, julgue o item a seguir. A presença de\nhemossedimentação aumentada e de um fator reumatoide positivo não tem utilidade na\ndiferenciação entre artrite psoriática e artrite reumatoide, pois ambas são artrites soropositivas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-177597","number":"177597","sourceNumber":"177597","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um menino de 5 anos de idade é levado por sua mãe a um serviço de pronto\natendimento pediátrico com queixas de odinofagia,\ntosse discreta e febre de até 39 °C, há 2 dias.\nAo exame físico, observam-se alguns linfonodos cervicais aumentados e dolorosos, ausculta\npulmonar normal, ausência de secreção nasal e orofaringe hiperemiada, com presença de placas\nesbranquiçadas na amígdala esquerda. Com base no hipotético caso citado e considerando os\nprincipais diagnósticos e as possíveis complicações, julgue o item a seguir. Caso a\nantibioticoterapia não seja iniciada e a criança venha a desenvolver a febre reumática, espera-se\num período de latência de 2 a 4 meses entre a infecção de orofaringe e o desenvolvimento da\ndoença cardíaca.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-177603","number":"177603","sourceNumber":"177603","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um menino de 5 anos de idade é levado por sua mãe a um serviço de pronto\natendimento pediátrico com queixas de odinofagia,\ntosse discreta e febre de até 39 °C, há 2 dias.\nAo exame físico, observam-se alguns linfonodos cervicais aumentados e dolorosos, ausculta\npulmonar normal, ausência de secreção nasal e orofaringe hiperemiada, com presença de placas\nesbranquiçadas na amígdala esquerda. Com base no hipotético caso citado e considerando os\nprincipais diagnósticos e as possíveis complicações, julgue o item a seguir. No quadro de febre\nreumática, a coreia de Sydenham costuma preceder as manifestações cardíacas da doença.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-177610","number":"177610","sourceNumber":"177610","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um menino de 5 anos de idade é levado por sua mãe a um serviço de pronto\natendimento pediátrico com queixas de odinofagia,\ntosse discreta e febre de até 39 °C, há 2 dias.\nAo exame físico, observam-se alguns linfonodos cervicais aumentados e dolorosos, ausculta\npulmonar normal, ausência de secreção nasal e orofaringe hiperemiada, com presença de placas\nesbranquiçadas na amígdala esquerda. Com base no hipotético caso citado e considerando os\nprincipais diagnósticos e as possíveis complicações, julgue o item a seguir. A artrite da febre\nreumática costuma ser poliarticular e assimétrica, além de acometer grandes articulações.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-152114","number":"152114","sourceNumber":"152114","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente, sexo masculino, 20 anos de idade, rash salmão em face, principalmente\nquando ocorre febre, relata que, após passar a\nfebre, desaparece. Também refere perda de peso e\ndificuldade em realizar agachamentos. Apresenta dor de garganta e linfonodomegalia. Ao exame\nfísico, apresenta-se com hepatoesplenomegalia, sinais de sacroileíte. Com base nesse caso clínico,\njulgue o item a seguir. Alelo X Gene HLA B27 pode estar envolvido neste caso .","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-131823","number":"131823","sourceNumber":"131823","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Acerca do tratamento da gota, assinale a alternativa CORRETA:","options":{"A":"O tratamento de pacientes que apresentam hiperuricemia assintomática é sempre indicado, uma\nvez que mais de 95% deles desenvolverá\ngota.","B":"A colchicina é indicada exclusivamente para pacientes com gota que apresentam insuficiência\nrenal.","C":"O uso do alopurinol aumenta a síntese do ácido úrico e sua excreção.","D":"O uso de Anti-Inflamatórios Não Esteroides (AINEs) é contraindicado no tratamento da gota e\nindicado no tratamento da pseudogota.","E":"Antes da utilização de glicocorticoides intra-articulares para analgesia da gota, deve-se\nexcluir a\nartrite séptica."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-135065","number":"135065","sourceNumber":"135065","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma paciente de quarenta anos de idade informou ao médico que, havia seis meses,\nvinha apresentando dor e edema nas articulações\ndas mãos e punhos. Passados dois meses do\ninício desses episódios, houve migração do processo para as articulações dos joelhos, o que tinha\nfeito a paciente sentir rigidez nas articulações todas as manhãs. O exame físico, por fim, mostrou\npresença de edema, calor, rubor e dor nas articulações citadas, de forma simétrica. Com relação a\nesse caso clínico, julgue o item subsequente. A ausência de manifestações extra-articulares na\npaciente é favorável a um bom prognóstico para a doença em questão.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-134962","number":"134962","sourceNumber":"134962","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma paciente de quarenta anos de idade informou ao médico que, havia seis meses,\nvinha apresentando dor e edema nas articulações\ndas mãos e punhos. Passados dois meses do\ninício desses episódios, houve migração do processo para as articulações dos joelhos, o que tinha\nfeito a paciente sentir rigidez nas articulações todas as manhãs. O exame físico, por fim, mostrou\npresença de edema, calor, rubor e dor nas articulações citadas, de forma simétrica. Com relação a\nesse caso clínico, julgue o item subsequente. A medida do fator reumatoide é um exame importante\npara a elucidação diagnóstica dessa paciente, embora esse fator possa estar presente em outras\ndoenças reumatológicas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-134979","number":"134979","sourceNumber":"134979","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Acerca de febre reumática, julgue o item que se segue. A coreia de Sydenham,\nmanifestação de febre reumática, é caracterizada tanto por habituais evidências de atividade\ninflamatória e estreptococcia, como também por deixar, frequentemente, sequelas tardias.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-108192","number":"108192","sourceNumber":"108192","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um paciente de trinta e cinco anos de idade compareceu a um ambulatório de clínica\nmédica apresentando quadro clínico constituído por episódios intermitentes de dor, rigidez, edema\ne calor nos joelhos e nos tornozelos. O paciente relatou, ainda, que esses sinais e sintomas\nocorriam pela manhã e duravam cerca de quatro horas. No exame físico, constatou-se que o\npaciente apresentava dor associada a sinais flogísticos na articulação do joelho direito. No\nprontuário do paciente, o resultado do hemograma indicava hemoglobina de 11 g/dL, hematócrito\nde 34%, hemácias de 4.000.000 mm³, leucócitos com número absoluto e diferencial normal para o\nsexo e faixa etária do paciente, plaquetas de 250.000 mm³ e VHS de 90 mm/h. Com base nesse\ncaso clínico, julque o item que se segue. A anemia normocística-normocrômica apresentada pelo\nreferido paciente é um achado frequente nessa forma de comprometimento articular.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-79643","number":"79643","sourceNumber":"79643","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Dos exames usados para avaliar processos inflamatórios, assinale a alternativa\nCORRETA:","options":{"A":"Ureia e creatinina.","B":"PCR e DHS.","C":"TGO e TGP.","D":"Troponina e PCR.","E":"Amilase e lipase."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-82078","number":"82078","sourceNumber":"82078","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma mulher de quarenta e cinco anos de idade foi atendida em ambulatório de clínica\nmédica com relato de que há oito anos apresentava dor na região plantar dos calcanhares e que,\napós ter sido submetida à avaliação médica, recebeu o diagnóstico de reumatismo e que lhe\nhaviam sido prescritos medicamentos cujos nomes não se recorda. Nesse intervalo de tempo,\npassou a apresentar dor e alterações nos punhos, que a impossibilitam de fechar as mãos, e\ntambém dor e vermelhidão nos joelhos e tornozelos. Ela relatou, ainda, rigidez matinal, com\nduração de três horas, por vários meses. Negou possuir outras doenças e informou que sua mãe\napresentava problema de reumatismo. Ao exame físico, observaram-se diminuição da flexão dos\npunhos (bilateralmente), dor nas articulações metacarpofalangianas (bilateralmente), presença de\ndiscreto derrame articular nos joelhos e dor à palpação das articulações metacarpofalangianas e\ndos calcanhares. Foram constatados três nódulos, com cerca de 2 cm de diâmetro cada um,\nindolores, firmes e móveis na região olecraniana direita. O restante do exame não apresentou\nalterações. Exames complementares realizados mostraram fator reumatoide (teste do látex)\npositivo, pesquisa de anticorpos contra peptídeos citrulinados cíclicos (CCP) positiva, níveis\nelevados de proteína C-reativa e aceleração da velocidade de hemossedimentação. Radiografias\ndas mãos e dos pés mostraram estreitamento dos espaços articulares e lesões ósseas erosivas.\nCom base nessas informações clinicolaboratoriais, julgue o item a seguir: o uso de metotrexato, útil\ncomo parte do tratamento farmacológico da paciente em tela, proporciona redução na progressão\ndas lesões radiográficas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-88655","number":"88655","sourceNumber":"88655","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"No que concerne à Artrite Reumatoide (AR), julgue o item subsequente. A AR pode\ngerar não só deformidade irreversível, mas\ntambém limitação funcional, além de menor sobrevida\nquando em estágio avançado.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-334884","number":"334884","sourceNumber":"334884","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A febre reumática (FR) é uma doença inflamatória, sistêmica, mais prevalente em\ncrianças na faixa etária de 5 a 15 anos de idade, deflagrada pelo Streptococcus ?-hemolítico do\ngrupo A de Lancefield e que acomete articulações, coração e pele. Considerando a patologia\ndescrita e os conhecimentos médicos atuais, assinale a alternativa correta","options":{"A":"O diagnóstico do primeiro surto de FR é realizado por dois critérios maiores, como poliartralgia\ne\nfebre.","B":"A artrite dá-se com o envolvimento de grandes e pequenas articulações, com caráter aditivo e\nprogressivo.","C":"Na FR recorrente, podem-se considerar três critérios menores, independentemente do grupo de\nrisco do paciente.","D":"O eritema marginado consiste em uma lesão macular com halo claro, que ocorre\nfrequentemente na face e que é muito pruriginosa.","E":"O ecodopplercardiograma deve ser solicitado apenas quando, na ausculta cardíaca, for\nencontrado sopro mitral."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-307097","number":"307097","sourceNumber":"307097","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma paciente de 46 anos de idade, de um dia para outro, começou a queixar-se de\ndores articulares em dedos das mãos e punhos.\nFoi ao ortopedista que passou anti-inflamatório\nnão hormonal, e ela melhorou por uma semana, mas, logo após, as dores pioraram. Começou a\nsentir dor, edema, calor e rubor, com impedimento para as atividades diárias, sendo a rigidez pior\nna primeira hora da manhã. Foi a um médico reumatologista que a vizinha indicou, e teve o\ndiagnóstico de artrite reumatoide (AR). Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, assinale a alternativa correta.","options":{"A":"O tratamento da paciente com AR não precisa ter, necessariamente, uma abordagem\nmultidisciplinar coordenada por um reumatologista,\ncom conhecimento em qualquer especialidade.","B":"O tratamento da paciente com AR deve incluir orientações quanto a hábitos de vida, controle\nrigoroso das comorbidades e atualização do cartão de vacinas.","C":"O tratamento da paciente com AR deve ser embasado em decisões tomadas pelo médico e\npassadas ao paciente, sem muitos esclarecimentos acerca de sua enfermidade, iniciando a\nterapêutica de forma a não perder tempo para a doença.","D":"Não há meta do tratamento da paciente com AR por ser um estado persistente e crônico, sem\nperspectivas de remissão clínica.","E":"No tratamento da AR, não se utilizam mais drogas como hidroxicloroquina e metotrexato por\nineficiência medicamentosa."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-301256","number":"301256","sourceNumber":"301256","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"O acometimento pleuropulmonar em pacientes com doenças autoimunes sistêmicas é\ncomum e pode levar ao aumento da morbidade e mortalidade. O diagnóstico precoce dessas\nmanifestações oferece a melhor chance de intervir e melhorar o prognóstico. A respeito desse\nassunto, julgue o item a seguir. A manifestação pleuropulmonar mais comum em pacientes com\nartrite reumatoide é o derrame pleural, que tem concentração elevada de complemento.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-307104","number":"307104","sourceNumber":"307104","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um paciente de 53 anos de idade, portador de diabetes, foi admitido em uma unidade\ncoronariana por angina instável. Previamente ao cateterismo, fez uso de tirofiban por 72 horas,\nseguindo a realização do exame que apresentou elevada carga trombótica e lesão em artéria\ndescendente anterior. Começou a sentir dor e apresentar edema articular de moderada intensidade\nem tornozelo e calcanhar esquerdo. Foi realizada dosagem de ácido úrico e determinado o\ndiagnóstico de hiperuricemia. O paciente refere ter gota e fazer medicação previamente à\ninternação. Em relação a esse caso clínico e à gota, assinale a alternativa correta. Alternativas:","options":{"A":"O paciente tem que suspender a angioplastia em razão da crise de gota em curso.","B":"É preciso melhorar a hidratação e corrigir a alimentação até 30 dias após o tratamento das\ncoronárias.","C":"Pode-se usar anti-inflamatório não hormonal por cinco dias a sete dias e iniciar colchicina.","D":"Por se tratar do acometimento de somente uma articulação, pode-se deixar para segundo plano\no tratamento, pois haverá resolução espontânea.","E":"A associação de um inibidor da xantina oxidase com a benzbromarona na gota não deve ser\nusada quando se sabe que o alvo sérico de ácido úrico não é alcançado."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-263351","number":"263351","sourceNumber":"263351","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um adolescente com 11 anos de idade é atendido no pronto-socorro com história de\ndor e inchaço em joelho esquerdo há 5\ndias. Ele conta que, há 2 dias, iniciou com febre, dificuldade\npara deambular e aumento da dor e do inchaço na região. A mãe relata recusa alimentar e palidez\ncutânea há 1 dia. O adolescente apresenta antecedente de trauma local durante partida de futebol\nhá 1 semana e refere o uso de anti-inflamatório não esteroidal desde então, sem melhora do\nquadro. Ao exame físico, apresenta-se em regular estado geral, com palidez cutânea, febril\n(temperatura axilar = 38,2°C), eupneico, anictérico, acianótico, com tempo de enchimento capilar de\n3 segundos e pressão arterial normal para a idade. Apresenta, ainda, edema, rubor, calor e dor no\njoelho esquerdo, com bloqueio à tentativa de mobilização. O resultado do hemograma mostra\nleucocitose com desvio à esquerda. Também foram observados proteína C reativa e VHS elevados.\nNesse caso, qual é o agente etiológico mais provável e a antibioticoterapia endovenosa indicada?","options":{"A":"Streptococcus pneumoniae; ampicilina.","B":"Staphylococcus aureus; oxacilina.","C":"H. influenzae tipo B; amoxicilina.","D":"Kingella kingae; ceftriaxona."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-268895","number":"268895","sourceNumber":"268895","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma paciente de 27 anos de idade compareceu ao atendimento ambulatorial com\nrelato de que, há dois meses, iniciou\naumento de volume e dor nos punhos e em algumas\ninterfalangeanas proximais; a dor foi aumentando com o passar dos dias e surgiu rigidez articular\nmatinal com duração de três horas. Negou febre e outros sintomas. Ao exame físico, apresentava\nartrite nos punhos e na segunda, terceira e quarta interfalangeanas proximais bilateral. Não foram\nidentificadas outras alterações ao exame físico. Verificaram-se FC = 80 bpm, FR = 18 irpm e SatO2\n\n= 97%. Quanto aos exames laboratoriais, contataram-se hemograma e EAS normais, FAN = 1/160\npadrão nuclear pontilhados fino denso, VHS = 45 mm/hora e PCR = 9,2 mg/dL, sendo o valor de\nreferência < 1 mg/dL. Nesse caso, os exames para confirmação da principal hipótese diagnóstica\nsão","options":{"A":"fator reumatoide, anticorpos anti-DNA nativo, anti-Sm e proteinúria de 24 horas.","B":"fator reumatoide e anticorpos anti-CCP.","C":"fator reumatoide, anticorpos anti-Ro/SSA, anti-La/SSB e radiografia das articulações\nacometidas.","D":"anticorpos anti-DNA nativo, anti-Sm, anti-Ro/SSA, anti-La/SSB e radiografia das articulações\nacometidas.","E":"anticorpos anti-DNA nativo, anti-Sm, dosagem dos fatores de complemento C3 e C4 e\nproteinúria de 24 horas."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-274610","number":"274610","sourceNumber":"274610","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A Artrite Idiopática Juvenil (AIJ) é o conjunto de doenças inflamatórias crônicas que\nacomete as articulações de crianças e adolescentes antes dos 16 anos. Quanto à AIJ, é\nINCORRETO afirmar:","options":{"A":"A AIJ é uma condição comum que afeta os nervos periféricos, responsáveis por encaminhar\ninformações do cérebro e da medula espinhal para o restante do corpo. A AIJ pode causar danos\npermanentes aos nervos, sendo muitas vezes um problema incapacitante e, até mesmo, fatal.","B":"Crianças tipicamente apresentam rigidez articular, edema, derrame, dores e sensibilidade, mas\nalgumas crianças não têm dor. As manifestações nas articulações podem ser simétricas ou\nassimétricas e envolver grandes ou pequenas articulações. Entesite normalmente provoca\nsensibilidade da crista ilíaca e coluna vertebral, grande trocânter do fêmur, patela, tuberosidade\nda\ntíbia ou inserções da fáscia plantar e do tendão calcâneo.","C":"Quando a artrite acomete até quatro articulações. É mais comum em meninas entre os 4 e 5\nanos. Atinge articulações grandes, como\njoelhos, tornozelos ou cotovelos. Também é comum afetar\numa articulação específica em um lado do corpo apenas e pode ser acompanhada de uveíte. Por\nisso, é importante a realização periódica de exames oftalmológicos.","D":"A AIJ é uma condição do sistema imunológico inato. Os mensageiros, chamados de\ninterleucinas, que promovem a resposta\ninflamatória, têm um papel-chave no desenvolvimento da\nAIJ. As outras formas de AIJ são as doenças autoimunes, o que significa que elas envolvem\nanticorpos do sistema imunológico adquirido."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-274612","number":"274612","sourceNumber":"274612","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A Artrite Idiopática Juvenil (AIJ), anteriormente conhecida como artrite reumatoide\njuvenil, é um conjunto de doenças\ninflamatórias crônicas que acomete as articulações de crianças e\nadolescentes antes dos 16 anos. A AIJ é uma doença:","options":{"A":"Bacteriana.","B":"Viral.","C":"Autoimune.","D":"Fúngica."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-291553","number":"291553","sourceNumber":"291553","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma menina de 3 anos de idade iniciou subitamente um quadro febril alto,\napresentando irritabilidade e queixa de dor\nimportante em perna direita, parando de andar. Ao\nexame, estava toxêmica. Foi identificada dor localizada na face anterior do quadril direito,\npermanecendo na posição de flexão-abdução e rotação externa. Havia relato de trauma na escola\npoucos dias antes, tendo caído do balanço, mas não houve repercussão no dia do acidente. Diante\ndo quadro clínico apresentado, assinale a alternativa que define o diagnóstico provável.","options":{"A":"Febre reumática.","B":"Sinovite transitória do quadril.","C":"Doença de Legg-Perthes.","D":"Artrite séptica do quadril."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-230541","number":"230541","sourceNumber":"230541","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Apesar de a etiopatogenia de AR (Artrite Reumatoide) ainda não ser inteiramente\nconhecida, muito se avançou no tema nos últimos anos. Podemos APENAS aceitar que:","options":{"A":"A Artrite Reumatoide (AR) é uma doença autoimune, inflamatória, sistêmica e crônica,\ncaracterizada por sinovite periférica e sem manifestações extra-articulares.","B":"No início, a observação do aumento da incidência de AR (Artrite Reumatoide) entre familiares,\nprincipalmente entre gêmeos monozigóticos, sugeria um componente ambiental em sua\netiopatogênese.","C":"Com o avanço dos estudos, foi identificado o antígeno leucocitário humano (human leukocyte\nantigen - HLA), considerado o principal fator genético no desenvolvimento dessa doença.","D":"Diversos alelos de HLA-DRB vêm sendo associados a AR (Artrite Reumatoide) em populações\nafricanas apenas."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-230547","number":"230547","sourceNumber":"230547","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Os principais fatores de risco para o desenvolvimento de Artrite Reumatoide (AR) foram\nà presença dos alelos HLA-DRB1 SE (shared\nepitope - epitopo compartilhado) e a detecção de\nanticorpos contra Peptídios Citrulinados Cíclicos (anti-CCP). Podemos assim ACEITAR que:","options":{"A":"Variações fenotípicas e de incidência não apontam para fatores ambientais além da\npredisposição genética.","B":"Variações fenotípicas e de incidência apontam para fatores ambientais que, além da\npredisposição genética, contribuem para o surgimento\nda doença, exceto tabagismo e infecções\nperiodontais.","C":"Variações fenotípicas e de incidência apontam para fatores ambientais que, além da\npredisposição genética, não contribuem para o surgimento da doença.","D":"Variações fenotípicas e de incidência apontam para fatores ambientais que, além da\npredisposição genética, contribuem para o\nsurgimento da doença, tais como tabagismo e infecções\nperiodontais."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-230549","number":"230549","sourceNumber":"230549","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Artrite Reumatoide sem tratamento adequado apresenta um curso de doença\nprogressivo, determinando deformidades decorrentes da\nlassidão ou ruptura dos tendões e das\nerosões articulares. Entre os achados tardios, podem-se identificar desvio e lesões diversas, qual\ndos itens está ERRADO?","options":{"A":"Desvio ulnar dos dedos ou ?dedos em ventania?.","B":"Deformidades em ?pescoço de cisne? ou hipoextensão das articulações IFP.","C":"Flexão das Interfalangianas Distais ? IFD.","D":"Deformidades em ?botoeira?, flexão das IFP e hiperextensão das IFD."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-230550","number":"230550","sourceNumber":"230550","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Quando na Artrite Reumatoide ocorre o acometimento da coluna cervical (C1-C2) com\nsubluxação atlantoaxial geralmente manifesta-se por dor irradiada para a região occipital, assim\npodemos CONCORDAR que:","options":{"A":"Quando sintomas neurológicos, como parestesias periféricas ou perda do controle esfincteriano,\nsurgem, a mortalidade é de 90% em 1 ano.","B":"Quando sintomas neurológicos, como perda do controle esfincteriano, não altera mortalidade.","C":"Quando sintomas neurológicos, como parestesias periféricas ou perda do controle esfincteriano,\nsurgem, a mortalidade em uma semana para\ntodos.","D":"Quando sintomas neurológicos, como parestesias periféricas ou perda do controle esfincteriano,\nsurgem, a mortalidade é de 50% em 1 ano."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-230551","number":"230551","sourceNumber":"230551","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Artrite Reumatoide (AR) tem em sua forma clínica mais comum a poliartrite simétrica de\npequenas e grandes articulações com\ncaráter crônico e destrutivo, podendo levar a relevante\nlimitação funcional, indique o item ERRADO:","options":{"A":"A AR é bastante variável quanto à apresentação clínica, à gravidade e ao prognóstico.","B":"Compromete a capacidade laboral e a qualidade de vida.","C":"Temos AR de longa evolução, que é chamada de Síndrome de Felty, quando ocorre associação\nde AR a neutropenia e hepatomegalia.","D":"Ocorre significativo impacto pessoal e social, com elevados custos indiretos."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-230554","number":"230554","sourceNumber":"230554","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"O acompanhamento por reumatologista para a Artrite Reumatoide é uma política\nassistencial custo-efetiva, devendo ser o preferencial. Somente NÃO podemos aceitar que:","options":{"A":"O abatacepte subcutâneo e o tofacitinibe são indicados para o tratamento da Artrite Reumatoide\nJuvenil (ARJ), pois seu uso foi aprovado\napenas para pacientes juvenis.","B":"Intervenções educacionais podem ser úteis na implementação de protocolos clínicos para essa\ndoença.","C":"A ciclosporina é preferencialmente recomendada na síndrome de ativação macrofágica, ou\nlinfo-histiocitose hemofagocítica.","D":"Na persistência de artrite, após 3 a 6 meses de tratamento, deve-se iniciar Medicamento\nModificador do Curso da Doença (MMCD) biológico, entre eles o adalimumabe, etanercepte,\ninfliximabe, abatacepte e tocilizumabe, sendo este último apenas para a forma sistêmica."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-230555","number":"230555","sourceNumber":"230555","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"As recomendações de tratamento medicamentoso dos pacientes com Artrite\nReumatoide (AR), o acompanhamento sistemático\ncom progressão de medicamentos em caso de\nfalha terapêutica é considerado estratégia custo-efetiva, sendo ADEQUADA a alternativa:","options":{"A":"Pois impede de os pacientes se manterem laboralmente ativos, melhorando a capacidade\nfuncional e a qualidade de vida a um custo aceitável para doenças crônicas.","B":"Pois mantém os pacientes laboralmente ativos, mesmo que piorando a capacidade funcional e a\nqualidade de vida a um custo aceitável para doenças crônicas.","C":"Pois mantém os pacientes laboralmente ativos, melhorando a capacidade funcional e a\nqualidade de vida a um custo aceitável para doenças crônicas.","D":"Pois mantém os pacientes laboralmente ativos, melhorando a capacidade funcional e a\nqualidade de vida a um custo inaceitável para doenças crônicas."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-212031","number":"212031","sourceNumber":"212031","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma mulher de 54 anos de idade, com diagnóstico de Artrite Reumatoide (AR),\napresenta um cisto sinovial poplíteo (cisto\nde Baker) no joelho direito. Considerando essa\nmanifestação articular da AR, julgue o item a seguir. Esse cisto pode dissecar e expandir-se para\nos tecidos da panturrilha ou sofrer ruptura com extravasamento para essa mesma região da perna.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-177227","number":"177227","sourceNumber":"177227","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente de 7 anos de idade, do sexo masculino, é levado a uma consulta por\napresentar quadro de edema, dor e aumento da\ntemperatura no joelho e no cotovelo esquerdos há\npelo menos 2 meses. Os responsáveis da criança negam qualquer episódio de febre. Na\ninvestigação com exames complementares, o paciente apresenta fator reumatoide e fator\nantinuclear negativos, além de anticorpos Aslo com valor normal. Considerando-se o caso clínico\napresentando e os conhecimentos médicos referentes a ele, é correto afirmar que o provável\ndiagnóstico é","options":{"A":"febre reumática.","B":"artrite séptica.","C":"dores do crescimento.","D":"lúpus eritematoso sistêmico.","E":"artrite idíopática juvenil."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-183945","number":"183945","sourceNumber":"183945","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"No que se refere a doenças cardiovasculares, isquêmicas e cerebrovasculares, julgue o\nitem a seguir. Insuficiência mitral é a lesão valvular mais comum resultante de febre reumática\naguda.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-159533","number":"159533","sourceNumber":"159533","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma professora do ensino fundamental, de vinte e oito anos de idade, procurou\natendimento médico por apresentar dispneia aos\nmédios esforços. O exame físico cardiovascular\nrevelou ictus cordis visível e palpável no 5º espaço intercostal na linha medioclavicular esquerda;\npresença de hiperfonese; e desdobramento fisiológico da segunda bulha em foco pulmonar. Na\nausculta do foco mitral, observaram-se hiperfonese da primeira bulha, estalido de abertura da mitral\ne sopro protomesodiastólico ? grau III de Levine ? associado a reforço pré-sistólico. No exame\nclínico, não foram observadas outras alterações significativas. Após avaliação clínica e\nlaboratorial,\no médico estabeleceu o diagnóstico de cardiopatia reumática crônica, tipo estenose mitral, de\nmoderada intensidade. Com referência a esse caso clínico, julgue o seguinte item: como a lesão\nvalvar definitiva está plenamente instalada, a profilaxia secundária para febre reumática não é\nrecomendada para a paciente em questão.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-111355","number":"111355","sourceNumber":"111355","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre a farmacologia dos Glicocorticoides (GC), assinale a afirmativa CORRETA:","options":{"A":"A dexametasona e a triancinolona apresentam boa atividade mineralocorticoide.","B":"A betametasona e a hidrocortisona são\nconsiderados GC de ação de curta duração.","C":"Os GC fluorados não atravessam a barreira\nplacentária.","D":"Pacientes tratados com GC, mesmo em doses fisiológicas e em regime de dias alternados,\ndevem ser considerados com supressão do eixo\nHHA.","E":"Aplicação tópica de GC pode induzir a supressão do eixo Hipotálamo-Hipófise-Adrenal (HAA)."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-97829","number":"97829","sourceNumber":"97829","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma adolescente, com 15 anos de idade, vem à consulta com queixa de dor precordial,\nfebre intermitente com um ou dois picos diários\nnoturnos de 39°C, acompanhados de dores\nmusculares generalizadas e manchas avermelhadas na pele do tronco e raiz de coxa. Relata\ntambém dificuldade de se movimentar pela manhã e dores nas articulações dos joelhos, punhos,\nmãos, pés e nuca. Ao exame físico, observa-se: temperatura = 38,5°C, lesões maculopapulares de\ncor rosa-salmão em tronco e áreas proximais de membros, nódulos subcutâneos em região de\ncotovelo, linfadenomegalia simétrica (cervicais, axilares e inguinais), esplenomegalia e artrite nas\nregiões referidas. Exames laboratoriais trazidos pelo paciente mostraram os seguintes resultados:\nhemograma com anemia, leucocitose e trombocitose; elevação de proteína C-reativa da velocidade\nde hemossedimentação e dos níveis de enzimas hepáticas (ALT e AST). A hipótese diagnóstica\nCORRETA é:","options":{"A":"Doença de Kawasaki.","B":"Artrite idiopática juvenil.","C":"Artrite reativa pós-estreptocócica.","D":"Lúpus eritematoso sistêmico juvenil."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-75470","number":"75470","sourceNumber":"75470","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem com 49 anos de idade apresenta, há um ano e meio, quadro recorrente de\nmonoartrite aguda, durando cada episódio cerca de três a cinco dias. Inicialmente foi acometido o\njoelho esquerdo, posteriormente o direito, em seguida o tornozelo direito e, há três semanas, houve\nrecorrência do quadro no joelho esquerdo. Refere alívio dos sintomas com o uso de diclofenaco,\nque toma por conta própria. Notou que o intervalo entre os episódios, que inicialmente era de até\nseis meses, é agora mais reduzido, sendo o intervalo entre os dois últimos episódios, de apenas\num mês. Apresenta-se na consulta após dois dias do início da última crise. O joelho esquerdo tem\nsinais flogísticos (calor, rubor, aumento de volume), limitação para flexão, o que causa dificuldade\nna deambulação. Relatou um episódio febril ontem (37,6°C). O paciente é hipertenso e diabético há\ndez anos, em uso de hidroclorotiazida 25 mg/dia e glibenclamida 10 mg/dia. Refere tabagismo (5\ncigarros/dia) e etilismo (cerveja, especialmente nos finais de semana). O diagnóstico do paciente e\na conduta inicial a ser adotada são, respectivamente:","options":{"A":"gota não tofácea; realizar artrocentese e iniciar o uso de alopurinol imediatamente.","B":"artrite séptica; realizar artrocentese e aguardar a\nanálise laboratorial do líquido sinovial.","C":"gota não tofácea; não realizar artrocentese e manter o uso de anti-inflamatório não hormonal.","D":"osteoartrite; solicitar radiografia dos joelhos e iniciar o uso de anti-inflamatório não\nhormonal.","E":"artrite séptica; não há necessidade de exames complementares e deve-se iniciar\nantibioticoterapia imediatamente."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-75550","number":"75550","sourceNumber":"75550","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menino com 12 anos de idade é trazido pelo pai ao ambulatório de pediatria. Na\nhistória, apresenta febre e dor intensa nas\narticulações do joelho há uma semana, a qual passou a\nacometer cotovelos e punhos. Há três semanas apresentou infecção de garganta (sic) tratada com\namoxicilina. Ao exame, apresenta temperatura axilar = 38.4°C; frequência cardíaca = 132 bpm;\nestado geral comprometido; dispneia leve que piora com o decúbito. A ausculta cardíaca mostra\nsopro holossistólico, de média intensidade, mais audível em ápice, irradiando-se para a axila; 3ª\nbulha audível. Diante do quadro de alta suspeita diagnóstica de febre reumática, qual a medicação\na ser prescrita nesse momento?","options":{"A":"Ibuprofeno.","B":"Diclofenaco.","C":"Naproxeno.","D":"Prednisona.","E":"Ácido Acetilsalicílico."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-137603","number":"137603","sourceNumber":"137603","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma mulher de 45 anos, com queixas de dores articulares há 5 meses, comparece ao\nambulatório para mostrar resultado de exames. Seu quadro começou com dores em mãos e pés,\npela manhã, com melhora durante o dia. Evoluiu há um mês com um surto de dor em articulações\ninterfalangeanas proximais, punhos, cotovelos e joelhos, com sinais de flogose, que melhorou com\no uso de indometacina por 10 dias. Ao exame, apresenta hipocromia de mucosas, edema e sinais\nde flogose discretos em mãos, com presença de nódulos justa-articulares e ausência de\ndeformidades. Traz exames complementares solicitados na consulta anterior: hemograma com Hb\n\n= 11,0 g /dL (valor de referência: 13,8 ± 2,5 g /dL), VHS = 56 mm na primeira hora (valor de\nreferência: ? 20 mm/h), prova do látex para\nfator reumatoide positiva, e radiografia das mãos que\nmostram redução da densidade óssea periarticular em articulações interfalangeanas proximais e\npunhos. A paciente, costureira, teme não poder trabalhar mais. Qual a medicação que poderia\nimpedir a progressão da doença?","options":{"A":"Aspirina.","B":"Colchicina.","C":"Metotrexate.","D":"Indometacina.","E":"Metilprednisona."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-138667","number":"138667","sourceNumber":"138667","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menina, com seis anos de idade, foi levada pela mãe à consulta em Unidade Básica de\nSáude por apresentar, há uma semana,\nintensa adinamia, quadro febril intermitente (temperatura =\n38º C) e dor articular, localizada inicialmente no joelho esquerdo, acompanhada de calor e rubor\ndiscreto e que, há dois dias, acomete o tornozelo direito. A mãe informa que, há cerca de seis\nsemanas, a criança apresentou quadro de infecção de vias aéreas superiores (faringite), que\nregrediu com o uso de amoxicilina durante cinco dias. Ao exame físico a criança encontrava-se\nafebril, eupneica, hidratada, com intensa adinamia, hipocorada (+/4), Frequência cardíaca=125\nbpm, Pressão arterial= 100 x 60 mmHg. A ausculta cardíaca e a ausculta pulmonar foram normais.\nFoi observada hiperemia, calor e dor no tornozelo direito, com limitação de movimentos e a\npresença de áreas eritematosas com centros esbranquiçados no tronco e na região proximal de\nmembros superiores e inferiores. Os exames laboratoriais revelaram: hemoglobina=10 g/dL,\nhematócrito=34%, leucócitos=14000/mm3, velocidade de hemossedimentação = 26mm/h, proteína\nC reativa= 2,0 ng/ml (valor de referência= <0,1 ng/mL); glicose, ureia e creatinina normais. O\neletrocardiograma mostra um prolongamento do intervalo P-R (0,20 s). Com base no quadro clínico\ndescrito e nos exames complementares realizados, qual o provável diagnóstico dessa criança?","options":{"A":"Artrite idopática juvenil.","B":"Lupus eritematoso sistêmico.","C":"Febre reumática.","D":"Síndrome de Reiter.","E":"Espondilartrose."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-352191","number":"352191","sourceNumber":"352191","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A fibromialgia é uma síndrome dolorosa crônica que acomete cerca de 5% da\npopulação geral. Marque a alternativa correta\nsobre os mecanismos e manifestações clínicas desta\ncondição clínica:","options":{"A":"Ocorre uma sensibilização central, ou seja, uma hiperexcitabilidade neuronal que causa resposta\ninadequada e amplificada aos estímulos periféricos.","B":"É uma doença relacionada a gatilhos ambientais, sem base genética associada.","C":"É uma doença que se caracteriza por disfunção, com estudos de imagem por Ressonância\nMagnética funcional (RMf) completamente normais.","D":"Manifestações como fadiga, disfunção de articulação temporomandibular (ATM), cefaleia são\nraros e quando presentes deve-se investigar outros diagnósticos diferencias."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-313278","number":"313278","sourceNumber":"313278","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A síndrome da fibromialgia pode ser definida como uma síndrome:","options":{"A":"Dolorosa aguda, não inflamatória, de etiologia autoimune.","B":"Dolorosa aguda, inflamatória, de etiologia ligada ao colágeno.","C":"Dolorosa aguda, não inflamatória, de etiologia desconhecida.","D":"Dolorosa crônica, inflamatória, de etiologia desconhecida.","E":"Dolorosa crônica, não inflamatória, de etiologia desconhecida."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-304845","number":"304845","sourceNumber":"304845","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A artrite reativa em indivíduos com gene HLA-B27 pode ser desencadeada pelo\nseguinte quadro infeccioso:","options":{"A":"Amidalite estreptocócica.","B":"Uretrite gonocócica.","C":"Candidíase.","D":"Shigelose."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-291940","number":"291940","sourceNumber":"291940","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A Artrite Idiopática Juvenil (AIJ) é a doença reumática crônica mais frequente na faixa\netária pediátrica. É um processo inflamatório crônico, autoimune e com manifestações\n\nextra-articulares que variam de acordo com o tipo de início. Sobre os tipos de início, assinale a\nalternativa CORRETA:","options":{"A":"Na artrite poliarticular com fator reumatoide positivo, a artrite se encontra em 4 ou mais\narticulações, sendo o fator reumatoide positivo\nem 2 dosagens com intervalos de 3 meses durante\nos 6 primeiros meses da doença.","B":"O início oligoarticular pode ser descrito em duas categorias distintas, sendo elas a\noligoarticular\npersistente, que não atinge mais de 4\narticulações no curso da doença e oligoarticular estendida,\nquando compromete mais de 4 articulações na evolução.","C":"Na artrite poliarticular com fator reumatoide negativo, encontramos características clínicas\nsemelhantes à artrite reumatoide do adulto, com maior risco de evolução para erosão óssea e\nincapacidade funcional.","D":"Independente da forma de início, o tratamento será o mesmo, visando a rápida remissão da\nartrite e de suas manifestações extra-articulares, prevenindo o aparecimento de deformidades\nsecundárias, atrofia muscular e a osteoporose."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-291941","number":"291941","sourceNumber":"291941","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A febre reumática é uma doença importante na prática clínica pediátrica. Sobre a febre\nreumática, é CORRETO afirmar que:","options":{"A":"Ela é uma doença inflamatória relacionada faringotonsilite causada pelo estreptococo\nbeta-hemolítico do grupo B.","B":"As manifestações clínicas da febre reumática surgem em média após um período de latência de\n2 a 3 meses, após a infecção\nestreptocócica.","C":"A identificação de pelo menos 1 dos critérios maiores de Jones é essencial para o diagnóstico\nda doença no primeiro episódio de febre\nreumática.","D":"Embora não seja a doença reumática mais comum na faixa etária pediátrica no Brasil, a febre\nreumática deve ser conduzida com cuidado, uma vez que suas complicações e sequelas impactam\ndiretamente na capacidade funcional da criança e do adolescente."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-266358","number":"266358","sourceNumber":"266358","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"As infecções osteoarticulares na criança são potencialmente graves, pois podem\nacarretar sequelas ao osso em crescimento. Nas\ninfecções osteoarticulares é correto afirmar:","options":{"A":"Na osteomielite hematogênica aguda a radiografia, por ter um baixo custo, é um bom meio de se\nfazer o diagnóstico precoce. As primeiras alterações radiográficas aparecem já no 1º dia.","B":"O Staphylococcus aureus é o agente etiológico mais comum na osteomielite e na pioartrite em\ncrianças e adolescentes.","C":"A artrite séptica compromete predominantemente as articulações dos membros superiores.","D":"Se o tratamento das infecções osteoarticulares for instituído precocemente pode ser feito via\noral, com antibiótico de largo espectro, por 15 dias."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-287862","number":"287862","sourceNumber":"287862","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre a Artrite Reumatoide (AR), assinalar a alternativa CORRETA:","options":{"A":"Trata-se de uma doença inflamatória sistêmica crônica, que acomete primariamente o tecido\nsinovial, com predomínio em articulações das mãos, punhos, temporomandibulares e porção\nsuperior da coluna lombar.","B":"Como manifestação clínica, pode ocorrer desvio radial dos dedos das mãos e as deformidades\nem \"\"pescoço de cisne\"\". A AR raramente acomete as\ninterfalangeanas distais.","C":"As manifestações extra-articulares da AR são mais comuns nos pacientes com fator reumatoide\nou anticorpos ACPA (anticorpos anti-peptídeos\ncitrulinados) positivos e podem ocorrer em pele,\ncoração, pulmão, olhos e sistema nervoso.","D":"A presença do fator reumatoide não é específica da AR, mas está presente em 80% dos\npacientes. A presença de fator reumatoide não tem relação com gravidade da doença articular.","E":"Os glicocorticoides têm um papel significativo no tratamento da AR, são úteis para a melhora\nsintomática e têm a capacidade de parar o processo da doença da sinóvia, modificando o potencial\nde deformidade; por esse motivo, são considerados medicamentos antirreumáticos modificadores\nde doença. Podem ser utilizados de forma isolada ou em associação ao metotrexato."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-234406","number":"234406","sourceNumber":"234406","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um homem de 21 anos vai ao pronto atendimento queixando-se de dor e edema no\njoelho direito há 3 dias. Nega comorbidades,\ndoenças prévias, trauma, uso regular de\nmedicamentos ou uso de quaisquer drogas. Ao exame físico, apresenta-se alerta e orientado. Os\ndados vitais são PA: 120 X 74mmHg, FC: 98bpm, FR: 19ipm, SpO? em ar ambiente 96%, Tax:\n38,4°C. O joelho direito está com o volume aumentado, apresenta calor e rubor local, além do sinal\nda tecla positivo. Exames de laboratório: Sangue: hemoglobina 13,1g/dL; leucócitos 17.210/mm³;\nneutrófilos segmentados 15.980/mm³; plaquetas 390.000/mm³; proteína C reativa 68mg/L. Líquido\nsinovial: citometria 70.450/mm³ (VR<2.000/mm³); neutrófilos 90%; pesquisa com coloração de\nGram: sem microrganismos coráveis. Considerando o caso descrito, assinale o PRINCIPAL agente\netiológico nessa condição.","options":{"A":"Cristais de pirofosfato de cálcio.","B":"Cristais de urato.","C":"Neisseria gonorrhoeae.","D":"Staphylococcus aureus."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-246356","number":"246356","sourceNumber":"246356","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente, 42 anos, feminino, previamente hígida, tabagista há 10 anos, 5 cigarros/dia.\nIniciou há 10 meses quadro de artralgia em\nmãos e punhos, associado a rigidez matinal de\narticulações das mãos e pés. Em sua primeira consulta com reumatologista, encaminhada da UBS,\no especialista evidencia ao exame físico que existe edema, calor e rubor em 2ª e 3ª\ninterfalangeanas proximais direitas, 3ª e 5ª metacarpofangeanas esquerdas, além de edema e calor\nde punho esquerdo. Paciente mostra alguns exames complementares já realizados na UBS: FAN\nnegativo, Fator reumatoide positivo, PCR 10 (VR menor que 5), AST 23 UI (VR: 40), ALT 34 UI (VR:\n45), Creatinina 1,1 mg/dl, HbsAg negativo, anti Hbs positivo, antiHCV negativo, antiHbc negativo,\nVDRL negativo, anti HIV negativo. Considerando o caso clínico acima, assinale a alternativa\ncorreta.","options":{"A":"Já se encontra bem estabelecida a relação entre o uso de tabaco e a maior suscetibilidade ao\ndesenvolvimento da artrite reumatoide em pacientes HLA-B27 positivos, pois o cigarro acelera as\nreações de citrulinização em proteínas pulmonares, o que dispara a produção de autoanticorpos.","B":"O reconhecimento dos complexos imunes por fagócitos promove liberação de diversas citocinas\npró-inflamatórias, principalmente a interleucina 12, o que exacerba ainda mais o processo\ninflamatório.","C":"O fator reumatoide representa um grupo de autoanticorpos caracterizados pela habilidade de\nreagir com determinados epítopos da porção fragmento cristalizável (Fc) da IgG e atua ativamente\nna patogênese da artrite reumatoide, sendo sua presença sugestiva de prognóstico desfavorável.","D":"O tratamento mais adequado para a paciente seria o início de metotrexato associado a\nmedicação biológica da classe anti TNF."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-227098","number":"227098","sourceNumber":"227098","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A febre reumática é uma complicação inflamatória aguda, não supurativa da infecção\nfaríngea por estreptococos do grupo A,\nusando combinações de artrites, cardites, nódulos\nsubcutâneos, eritema marginado e coreia. O diagnóstico baseia-se na aplicação dos critérios\nmodificados de Jones relacionados com dados de história, exame e testes laboratoriais. Assinale a\nalternativa que evidencia um critério MENOR para a febre reumática.","options":{"A":"Poliartrite.","B":"Poliartralgia.","C":"Eritema marginado.","D":"Nódulos subcutâneos."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-232143","number":"232143","sourceNumber":"232143","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A febre reumática é uma doença caracterizada por reação auto-imune cruzada, não\nsupurativa, por mimetismo molecular entre proteínas bacterianas e proteínas constituintes\norgânicas. Os achados clínicos e os sintomas da doença guardam correção com o tipo de resposta\nimune desenvolvida. Dessa forma, a seguinte manifestação clínica ocorre por resposta imune\npredominantemente celular:","options":{"A":"Coréia.","B":"Artralgia.","C":"Artrite.","D":"Cardite.","E":"Eritema marginado."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-255665","number":"255665","sourceNumber":"255665","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Os pacientes adultos com artrite reumatoide, em geral apresentam qual queixa, entre\nas abaixo, como sintoma inicial da doença?\nMARQUE A CORRETA:","options":{"A":"Dor ao longo do dia em repouso ou em movimento.","B":"Rigidez matinal que dura mais de 1 hora e que melhora com atividade física.","C":"Artralgia em grandes articulações e com envolvimento poliarticular (> 10 articulações).","D":"Limitação de movimentos pelo comprometimento de membros inferiores."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-220286","number":"220286","sourceNumber":"220286","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 55 anos se queixa de dor no joelho direito ao subir e descer as escadas da\nsua casa, principalmente no final do dia. O\nsintoma que ocorreu há 1 ano, tem se tornado mais\nintenso e frequente e a faz evitar escadarias. Relata dificuldade ao iniciar movimentos após\nperíodos de inatividade que melhora à medida que insiste no movimento. Nega calor, rubor ou\nedema nessa articulação ou outras quaisquer. Ao exame físico, há crepitações e limitação dos\nmovimentos ativos e passivos no joelho direito, além de derrame articular (sinal da tecla presente).\nEm relação a essa doença, assinale a alternativa CORRETA:","options":{"A":"Os joelhos, os cotovelos, os punhos, os ombros e os tornozelos são as articulações mais\nacometidas.","B":"A doença não cursa com rigidez matinal nas articulações acometidas.","C":"A instabilidade nos movimentos articulares por causa de atrofia muscular pode ocorrer.","D":"Os sintomas e os achados radiográficos guardam correlação clínico-radiológica."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-202765","number":"202765","sourceNumber":"202765","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em relação aos achados clínicos na febre reumática, é CORRETO afirmar:","options":{"A":"Apesar de infrequente, em indivíduos com sintomas agudos a poliartrite é migratória, dolorosa e\nde grandes articulações.","B":"Apesar de o exame clínico sugerir o diagnóstico da Coréia de Sydeham, o mesmo deve ser\nconfirmado por meio de exames de neuroimagem.","C":"Nódulos cutâneos são comuns e específicos para o diagnóstico de febre reumática.","D":"Na cardite reumática, a gravidade da disfunção do ventrículo esquerdo parece estar\ncorrelacionada à extensão da valvulite, e não à lesão miocárdica.","E":"O eritema marginado geralmente tem início tardio no curso da febre reumática aguda."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-199623","number":"199623","sourceNumber":"199623","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A Febre Reumática (FR) é a doença reumática mais comum no Brasil e pode afetar\npacientes geneticamente predispostos. Na febre reumática é CORRETO afirmar:","options":{"A":"O diagnóstico de febre reumática é feito com a presença da tríade: história de tonsilite, febre e\nmanifestações articulares.","B":"A cardite costuma ser diagnosticada nas três primeiras semanas da fase aguda e a principal\ncaracterística diagnóstica é a endocardite.","C":"Na febre reumática, a antiestreptolisina O começa a se elevar na primeira semana, após a\ninfecção estreptocócica, e normaliza com quatro semanas e seus títulos têm relação com a\ngravidade da FR.","D":"A poliartrite ocorre na maioria dos casos. Acomete grandes e pequenas articulações com\npredileção por joelho, punhos e articulações das mãos e pés."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-174358","number":"174358","sourceNumber":"174358","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Escolar de oito anos, do sexo feminino, apresenta quadro agudo de febre alta, dor e\nsinais inflamatórios em joelho direito e exantema serpiginoso evanescente e não pruriginoso em\ntronco, que piora com o calor. Exames complementares: Leucocitose e elevação da VHS. Neste\ncaso, a hipótese diagnóstica mais provável é:","options":{"A":"Artrite reumatoide.","B":"Febre reumática.","C":"Lúpus eritematoso.","D":"Artrite juvenil.","E":"Doença de Kawasaki."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-172510","number":"172510","sourceNumber":"172510","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Não é considerado um critério maior para o diagnóstico da febre reumática:","options":{"A":"Cardite.","B":"Artrite.","C":"Coréia.","D":"Nódulos subcutâneos.","E":"Eritema nodoso."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-162581","number":"162581","sourceNumber":"162581","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Considere as afirmativas abaixo em relação à artrite reumatoide. I ? A presença do fator\nreumatoide não estabelece o diagnóstico de artrite reumatoide; II ? Dentre os pacientes com artrite\nreumatoide, os que apresentam manifestações extra-articulares têm maior mortalidade; III ? A\nSíndrome de Felty consiste em artrite reumatoide crônica associada à esplenomegalia e\nneutropenia. Quais estão CORRETAS?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas II e III.","E":"I, II e III."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-162591","number":"162591","sourceNumber":"162591","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente feminina de 75 anos de idade encontra-se em avaliação por acometimento\nsistêmico da artrite reumatoide. Assinale a alternativa que NÃO apresenta manifestação\n\nextra-articular da artrite reumatoide:","options":{"A":"Ecocardiograma com derrame pericárdico.","B":"Eletroneuromiografia com mononeurite múltipla.","C":"Radiografia de tórax com infiltrado intersticial.","D":"Colonoscopia com nódulos colônicos.","E":"Lesões de pele compatíveis com pioderma gangrenoso."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-149117","number":"149117","sourceNumber":"149117","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em relação à febre reumática, analise a assertivas abaixo: I- A febre reumática pode\ncausar pancardite, o principal folheto atingido é\no pericárdio II- A coréia de Sydenham é uma\nmanifestação do envolvimento dos gânglios da base do sistema nervoso central III- O padrão do\nenvolvimento da artrite é do tipo migratório, assimétrico e muito doloroso, com curso totalmente\nresolutivo IV- O eritema marginado e os nódulos subcutâneos são manifestações clinicas raras e\nem geral, estão associados à presença de artrite. Marque as alternativas corretas:","options":{"A":"Apenas I e II.","B":"Apenas II e III.","C":"Apenas III e IV.","D":"Apenas I e IV.","E":"Apenas II,III e IV."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-131628","number":"131628","sourceNumber":"131628","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Na artrite reativa podem ocorrer manifestações extra-articulares. Todas as abaixo\npodem estar presentes, exceto:","options":{"A":"Erupções cutâneas palmo-plantares.","B":"Conjuntivite.","C":"Ulcerações orais.","D":"Nódulos subcutâneos.","E":"Disúria."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-131643","number":"131643","sourceNumber":"131643","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A manifestação ocular mais frequente em pacientes portadores de artrite reumatoide é:","options":{"A":"Paresia da musculatura ocular extrínseca.","B":"Descolamento de retina.","C":"Opacificação do cristalino.","D":"Ceratoconjuntivite sicca.","E":"Uveíte."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-126901","number":"126901","sourceNumber":"126901","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Os critérios de Jones modificados são utilizados para diagnóstico de primeiro surto\nagudo da Febre Reumática (FR). Em relação\nao diagnóstico da Febre Reumática (FR), assinale a\nalternativa INCORRETA:","options":{"A":"A presença de duas manifestações maiores ou de uma maior e duas menores acrescidas da\nevidência de estreptococcia recente, indica alta probabilidade de FR.","B":"A coreia de Sydenham como manifestação isolada deve ser sempre acompanhada da\ncomprovação da estreptococcia.","C":"Os nódulos subcutâneos, a cardite e a artrite são sinais maiores.","D":"A artralgia, a febre e o intervalo do PR prolongado são sinais menores."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-106426","number":"106426","sourceNumber":"106426","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Na Artrite Reumatoide (AR) estabelecida, qual das articulações abaixo é a mais\ncomprometida?","options":{"A":"Interfalangiana distal.","B":"Quadril.","C":"Joelho.","D":"Coluna.","E":"Punho."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-106441","number":"106441","sourceNumber":"106441","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Os critérios de Jones são utilizados para o diagnóstico da febre reumática. Essa\ndoença é diagnosticada numa criança quando ela\napresenta, além de evidencia de infecção\nrecente pelo Streptococcus beta hemolítico do grupo A:","options":{"A":"artralgia e intervalo P-R aumentado.","B":"cardite e febre.","C":"nódulos subcutâneos e proteína-C-reativa aumentada .","D":"eritema marginado e poliartrite migratória.","E":"coréia de Sydenham e aumento da velocidade de hemossedimentação"},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-88921","number":"88921","sourceNumber":"88921","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Caracteriza a presença de artrite:","options":{"A":"Dor à palpação articular.","B":"Derrame articular.","C":"Dor à movimentação ativa de uma articulação.","D":"Hiperemia da pele sobrejacente a uma articulação.","E":"Dor à movimentação passiva de uma articulação."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-77495","number":"77495","sourceNumber":"77495","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um paciente de cinco anos de idade, sem história recente de amigdalite sintomática,\napresenta há dois meses quadro de movimentos\ninvoluntários incoordenados e rápidos, que\ndesaparecem durante o sono, associados à disartria, e que se mantêm até a consulta atual. O\ninício foi insidioso e caracterizado por labilidade emocional com fraqueza muscular. O único quadro\nconhecido de amigdalite sintomática seguida de elevação de ASLO (Antiestreptolisina O) ocorreu\nhá quatro meses. Não houve nenhuma outra manifestação clínica associada ao quadro atual,\nincluindo febre, artralgia, artrite ou qualquer outra anormalidade do sistema cardiovascular. No\nmomento, a proteína C-reativa e outros reagentes de fase aguda, como a VHS (Velocidade de\nHemossedimentação), estão dentro dos valores da normalidade. Analisando a situação acima, é\nCORRETO afirmar que a hipótese de febre reumática:","options":{"A":"É improvável se não houver pelo menos um critério de Jones maior e dois menores.","B":"Não deve ser confirmada se não houver pelo menos dois critérios de Jones maiores.","C":"Deve ser descartada se não houver alteração sugestiva de cardite na ecocardiografia.","D":"É provável, uma vez que a coreia é um critério de Jones que, se presente, mesmo isoladamente,\npermite o diagnóstico da doença.","E":"Deve ser afastada, uma vez que a comprovação de infecção recente pelo Streptococcus\npyogenes ocorreu muito tempo antes do início dos\nsintomas."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-88883","number":"88883","sourceNumber":"88883","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A alteração radiográfica que, num caso suspeito de espondilite anquilosante,\nfortaleceria essa hipótese diagnóstica é:","options":{"A":"sacroilite","B":"osteomalácia","C":"espondilólise","D":"peritendinite","E":"osteoporose"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-43953","number":"43953","sourceNumber":"43953","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente masculino, 25 anos, com queixa de dor lombar que é pior ao acordar e\nmelhora ao longo do dia, acompanhada de\nrigidez matinal por mais do que 30 minutos e edema de\njoelho direito há 06 meses. Refere que 30 dias antes do início do quadro articular apresentou\ndiarreia aguda. Quanto ao caso acima, assinale a alternativa correta.","options":{"A":"Este paciente não apresenta nenhum sinal de alerta que justifique investigação radiológica da\ndor.","B":"O diagnóstico sindrômico do paciente é lombalgia mecânica crônica.","C":"É provável que o paciente não tenha sacroileíte, pois não apresenta dor alternante em nádega.","D":"Diante dos sintomas pode-se classificar esse quadro como uma espondiloartrite.","E":"Prováveis causadores desta diarreia são Salmonella typhimurium, Yersinia enterocolitica,\nShigella flexneri, Campylobacter jejuni, Chlamydia\ntracomatis."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-44017","number":"44017","sourceNumber":"44017","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Criança do sexo feminino, quatro anos de idade, é atendida devido à febre alta diária,\nhá mais de 03 semanas, geralmente um pico à\nnoite. Refere dores nas pernas durante a febre, bem\ncomo um exantema discreto em tronco e membros superiores, mas fica bem nos períodos afebris.\nRefere ainda dor, edema e calor em joelho direito, que iniciou há uma semana. Ao exame está\nbem, afebril no momento, mas com aumento de volume no joelho direito, calor e dor à palpação.\n\nPresença de adenomegalia cervical, auxiliar e inguinal bilateral e hepatoesplenomegalia discreta.\nSem outras alterações ao exame físico. Qual\ndos diagnósticos abaixo é o mais provável?","options":{"A":"Febre reumática.","B":"Artrite idiopática juvenil sistêmica.","C":"Lúpus eritematoso sistêmico.","D":"Tuberculose óssea.","E":"Artrite reacional a quadro infeccioso."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-32457","number":"32457","sourceNumber":"32457","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Marque a alternativa correta sobre a Artrite Reumatoide: I - A doença não diminui a\nsobrevida, mas afeta significativamente a qualidade de vida da maioria dos pacientes. II - O\nacometimento das mãos é caracteristicamente simétrico e predomina em metacarpofalangeanas e\ninterfalangeanas proximais. III - O tratamento da doença deve ser instituído o mais rapidamente\npossível com drogas modificadoras da doença como anti-inflamatórios. IV - Os nódulos\nreumatoides podem ocorrer nos pulmões, coração e olhos.","options":{"A":"Uma afirmativa é correta.","B":"Duas afirmativas são corretas.","C":"Três afirmativas são corretas.","D":"Quatro afirmativas são corretas.","E":"Nenhuma das alternativas é correta."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-9405","number":"9405","sourceNumber":"9405","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Com relação ao fator AR (Artrite Reumatoide), assinale a INCORRETA:","options":{"A":"O fator reumatoide é encontrado em 70 a 80% dos casos de AR.","B":"Os métodos mais utilizados para identificação de fator reumatoide são o látex e o Waaler-Rose.","C":"O fator reumatoide tem sido identificado no soro, líquido sinovial, líquido pleural e nos\ntecidos.","D":"No tipo infanto-juvenil, ou nas formas clínicas benignas, estes testes geralmente são negativos.","E":"O fator reumatoide é diagnóstico de artrite reumatoide e sua ausência determina a exclusão\ndiagnóstica."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-353844","number":"353844","sourceNumber":"353844","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre as manifestações clínicas articulares e extra-articulares da Artrite Reumatoide\n(AR): I. Caracteristicamente, a dor é de\nritmo inflamatório, piorando ao longo do dia e melhorando à\nnoite, além de piorar ao longo de exercícios físicos. II. Os nódulos subcutâneos são as\nmanifestações extra-articulares mais frequentes e localizam-se habitualmente sobre superfícies\nextensoras articulares, áreas submetidas à pressão e, mais raramente, em olhos, pulmões e cordas\nvocais. III. O derrame pleural da AR possui exsudato que apresenta, frequentemente, pH alto (>\n7,6), glicose aumentada (> 40 mg/dL), DHL diminuída (< 1000 UI/L) e dosagem do fator reumatoide\nnão reagente. Das proposições acima:","options":{"A":"Apenas II está correta.","B":"Apenas I está correta.","C":"Apenas I e II estão corretas.","D":"Todas estão incorretas."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-354840","number":"354840","sourceNumber":"354840","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Leia o relato do caso clínico a seguir. Paciente A.R., feminina, 35 anos de idade,\ncasada, cabeleireira, nega comorbidades, nega\nalergia a medicamentos, nega etilismo, nega\ntabagismo e nega consumo de outras drogas, sedentária; S1. Paciente refere dolorimento nos\núltimos sete dias em mandíbula direita, mandíbula esquerda, cervical, ombro direito, antebraço\ndireito, coluna torácica (dorsal), abdômen, coluna lombar e perna direita. Nega dor nos últimos 7\ndias em: ombro esquerdo, braços, tórax anterior, quadris, coxas e perna esquerda. Paciente refere\nainda, nos últimos 7 dias, fatigabilidade moderada, sono não reparador com cansaço intenso ao\ndespertar, sintomas cognitivos moderados (dificuldade de concentração e déficit em memória).\n\nEntre outros sintomas refere que há mais de 6 meses experimenta intenso incômodo por cefaleias,\nhumor deprimido e câimbras musculares no\nabdômen inferior. A anamnese acima, no modelo\nSOAP, foi muito bem redigida para a hipótese de fibromialgia por abordar o índice de dor difusa\n(IDD) e escala de severidade dos sintomas (Escala de Gravidade, ESS) de acordo com o bem\nestabelecido Critério do Colégio Americano de 2010/2011, revisado em 2016. De acordo com o\nrelato, o IDD e a ESS da paciente são, respectivamente,","options":{"A":"8 e 6.","B":"8 e 10.","C":"9 e 10.","D":"10 e 9."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-363975","number":"363975","sourceNumber":"363975","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente do sexo feminino, 41 anos, parda, arquiteta, apresenta diagnóstico de artrite\nreumatoide. Ela procura o ambulatório de reumatologia com poliartrite em mãos, cotovelos, joelhos\ne tornozelos, há cerca de 3 meses, após suspensão de todas as medicações de uso contínuo, ao\nreceber a confirmação de que estava grávida. No momento está utilizando apenas a prednisona, 10\nmg por dia, prescrita por médico da Estratégia de Saúde da Família. Considerando que a paciente\nse encontra na 18ª semana de gestação, o esquema terapêutico adequado para o manejo do\nquadro articular deve ser","options":{"A":"Hidroxicloroquina, associada ao Rituximabe.","B":"Sulfassalazina, associada ao Tocilizumabe.","C":"Hidroxicloroquina, associada ao Certolizumabe.","D":"Sulfassalazina, associada ao Abatacepte."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-363916","number":"363916","sourceNumber":"363916","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Qual é a doença reumática mais comum na faixa etária pediátrica?","options":{"A":"Febre reumática.","B":"Lúpus eritematoso sistêmico.","C":"Espondilite anquilosante.","D":"Artrite reumatoide."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-334780","number":"334780","sourceNumber":"334780","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente de 57 anos de idade, na terceira semana do tratamento de tuberculose\npulmonar em uso do esquema preferencial\nconforme Manual e Recomendações para Controle da\nTuberculose no Brasil (Ministério da Saúde), passou a apresentar náuseas, vômitos e dor em\nhipocôndrio direito. Procurou Unidade Básica de Saúde, onde não foram constatados sinais de\ngravidade clínica, porém exames laboratoriais demonstraram TGO 460 U/L e TGP 530 U/L.\nPaciente sem história de hepatopatias prévias. Em qual condição o uso de um uricosúrico (droga\nredutora do ácido úrico) é fortemente recomendado ao paciente?","options":{"A":"Logo após a primeira crise de gota aguda.","B":"Na segunda crise de gota aguda e com diabetes mellitus.","C":"Com duas ou mais crises agudas de gota por ano.","D":"Com hiperuricemia (maior que 7 mg/dL) assintomática."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-330076","number":"330076","sourceNumber":"330076","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente, 70 anos, sexo masculino, com dor articular acompanhada de alterações no\nexame físico na articulação, como edema,\ncalor, eritema, dor espontânea e derrame articular.\n\nDentre os diagnósticos abaixo, o mais apropriado é:","options":{"A":"Febre reumática.","B":"Artrite reativa.","C":"Lúpus eritematoso.","D":"Osteoartrite."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-321560","number":"321560","sourceNumber":"321560","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A artrite reumatoide é uma doença inflamatória autoimune, progressiva, que acomete\nprimariamente a membrana sinovial das articulações. De acordo com as Recomendações da\nSociedade Brasileira de Reumatologia, o primeiro esquema terapêutico a ser utilizado deve incluir\num DMARD (droga modificadora do curso da doença)","options":{"A":"biológico, preferencialmente anti-TNF.","B":"sintético alvo específico, preferencialmente tofacitinibe.","C":"bloqueador da coestimulação do linfócito T, preferencialmente abatacepte.","D":"sintético convencional, preferencialmente metotrexato."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-342650","number":"342650","sourceNumber":"342650","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma escolar de 8 anos apresenta quadro agudo de febre alta, dor e sinais inflamatórios\nno joelho direito e exantema serpiginoso\nevanescente e não pruriginoso no tronco, que piora com o\ncalor. Exames complementares: leucocitose e elevação da VHS. Nesse caso, a hipótese\ndiagnóstica mais provável é:","options":{"A":"artrite reumatoide","B":"febre reumática","C":"lúpus eritematoso","D":"artrite juvenil"},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-302834","number":"302834","sourceNumber":"302834","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um paciente de 60 anos, diabético e hipertenso procurou o médico para avaliação de\nhiperuricemia. Vinha em uso de losartan, hidrocolorotiazida e merformina. Referia consumo\nalcoólico cerca de quatro vezes por semana, e o IMC estava em 32 kg/m2. Os níveis de ácido úrico\noscilaram nos últimos anos, entre 8,0 e 9,0 mg/dl. Dentre as medidas abaixo, qual NÃO deve ser\nrecomendada nesse caso?","options":{"A":"A Substituição do esquema anti-hipertensivo.","B":"Redução do consumo alcoólico.","C":"Engajamento em tratamento para redução de peso, com dieta e exercícios.","D":"Dosagem da excreção urinária de ácido úrico nas 24 horas.","E":"Alopurinol na dose inicial de 100 mg/dia, com elevações graduais até 300 mg/dia."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-300800","number":"300800","sourceNumber":"300800","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente, sexo masculino, 68 anos, relata dor intensa e rigidez em ambos os\ntornozelos. No exame físico, mostra calor,\nedema e grande derrame articular também em ambos os\ntornozelos. A artrocentese do tornozelo direito mostra a presença de cristais fracamente\nbirrefringentes positivos no líquido sinovial. A coloração de Gram é negativa. O diagnóstico mais\nprovável é:","options":{"A":"Doença de depósito de oxalato de cálcio.","B":"Artrite séptica.","C":"Artrite reativa.","D":"Pseudogota."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-314110","number":"314110","sourceNumber":"314110","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A artrite reumatoide é uma doença autoimune sistêmica, cuja prevalência é de cerca de\n1% no mundo, que acomete ambos os sexos,\ncom predomínio no sexo feminino. Dentre as\ndeformidades dos dedos que podem ser encontradas na doença estabelecida estão os \"dedos em\npescoço de cisne\", que se caracterizam por","options":{"A":"flexão das articulações metacarpofalangeanas e hiperextensão das articulações\ninterfalangeanas dos polegares.","B":"flexão das articulações interfalangeanas proximais e hiperextensão das articulações\ninterfalangeanas distais.","C":"hiperextensão das articulações interfalangeanas proximais e flexão das articulações\ninterfalangeanas distais.","D":"tumefação das articulações interfalangeanas proximais."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-300820","number":"300820","sourceNumber":"300820","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A febre é um sinal comum a vários problemas de saúde de crianças. A definição exata\nda temperatura, a partir da qual se considera\nfebre, é dada por pontos de corte arbitrários que\nvariam na literatura e conforme a região de aferição no corpo, geralmente como temperatura ?\n\n38ºC. Considerando a febre em crianças, são causas comuns de febre de origem indeterminada:","options":{"A":"Infecções virais e bacterianas do trato respiratório superior: rinossinusite, amidalite,\nfaringite,\notite média aguda, diarreia aguda.","B":"Infecção do trato urinário, pneumonia, sinusite, bacteremia.","C":"Artrite idiopática juvenil, lúpus eritematoso sistêmico, febre reumática, Doença de Crohn, colite\nulcerativa, leucemia, Linfoma não Hodgkin.","D":"Artrite séptica, osteomielite, síndromes virais, doença da arranhadura do gato, mononucleose\ninfecciosa, citomegalovirose, malária, tuberculose, reação à vacina."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-316321","number":"316321","sourceNumber":"316321","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A positividade para o antígeno HLA B27 indica o seguinte diagnóstico:","options":{"A":"Tireoidite de Hashimoto","B":"Espondilite anquilosante","C":"Artrite reumatoide","D":"Granulomatose de Wegener"},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-311917","number":"311917","sourceNumber":"311917","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 52 anos comparece ao ambulatório central após internação hospitalar\nrecente para tratamento de um primeiro\nepisódio de monoartrite aguda por gota. Nega hipertensão\narterial ou diabetes, apresenta circunferência de cintura aumentada e obesidade (IMC = 31 kg/m²).\nNão há mais sintomas de artrite há 3 semanas. Em relação à prevenção de novas crises de gota, a\nmelhor abordagem é","options":{"A":"recomendar redução de peso, redução de ingesta de bebida alcoólica e discutir risco-benefício\ndo tratamento hipouricemiante.","B":"iniciar alopurinol, buscando nível sérico de ácido úrico < 7mg/dl.","C":"iniciar alopurinol e colchicina, buscando nível sérico de ácido úrico < 6mg/dl.","D":"iniciar colchicina apenas, reservando alupurinol apenas se ácido úrico ? 9mg/dl."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-313211","number":"313211","sourceNumber":"313211","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um homem de 42 anos está com queixa de dor no joelho direito associado a edema,\nrubor e calor local há 3 dias. Nega outras\nqueixas, e não há outros achados ao exame clínico.\n\nRealizada artrocentese que evidenciou: leucócitos 35.000/mm³, com predomínio de neutrófilos e\ncristais de monourato de sódio com birrefringência negativa. Nesse caso, o diagnóstico e a conduta\nadequada são:","options":{"A":"gota; receitar anti-inflamatório","B":"artrite séptica; prescrever corticoide","C":"pseudogota; receitar rasburicase","D":"artrite reumatoide; iniciar metotrexato"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-314128","number":"314128","sourceNumber":"314128","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"É critério maior de Jones para febre reumática:","options":{"A":"poliartralgia.","B":"intervalo PR aumentado no eletrocardiograma (ECG).","C":"febre maior que 38,5 ºC.","D":"coreia."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-316368","number":"316368","sourceNumber":"316368","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente com diagnóstico de fibromialgia procura atendimento médico na clínica da\nfamília e durante a consulta médica, relata que não melhorou completamente com a prescrição de\nmedidas não farmacológicas (exercícios, aeróbico, hidroginástica, acupuntura) como orientado e\nprescrito em consultas anteriores. Diante do caso, qual medicação de uso contínuo estaria mais\nindicada?","options":{"A":"Paracetamol 500 mg de 8/8h.","B":"Ibuprofeno 600 mg de 12/12h.","C":"Diazepam 10 mg 2 x ao dia.","D":"Amitriptilina 25 mg, antes de dormir."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-295425","number":"295425","sourceNumber":"295425","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Qual a lesão cardíaca mais frequente na fase aguda de febre reumática?","options":{"A":"Estenose mitral.","B":"Insuficiência aórtica.","C":"Estenose aórtica.","D":"Insuficiência mitral."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-281264","number":"281264","sourceNumber":"281264","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Assinale a alternativa incorreta com relação ao diagnóstico da Hiperferritinemia.","options":{"A":"A ferritina sérica pode ser um importante auxiliar no diagnóstico e no prognóstico de pacientes\ncríticos.","B":"Um valor de ferritina dentro da normalidade não exclui o diagnóstico de processo inflamatório.","C":"A ferritina sérica é um exame barato e de fácil execução.","D":"Hiperferritinemia e hemofagocitose são sinônimos."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-274758","number":"274758","sourceNumber":"274758","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente com 06 anos de idade, sexo feminino, com história de dor súbita em joelho\nesquerdo há 02 dias e piora progressiva. Apresentou pico febril não medido, com inapetência e\nmarcha impossibilitada pela dor. Sem história prévia conhecida de comorbidades. Deu entrada no\npronto socorro com piora importante da dor nas últimas horas. Ao exame físico, apresenta bloqueio\narticular, com aumento de volume e calor local. Foi submetida a punção articular e a análise do\nlíquido sinovial evidenciou aumento do número de células com predomínio de polimorfonucleares,\nelevação das proteínas e redução da glicose. A hipótese diagnóstica e a respectiva conduta devem\nser:","options":{"A":"artrite séptica. Deve-se iniciar antibioticoterapia oral associada a analgesia potente. Liberar\npaciente para retorno ambulatorial em 48 horas com exames laboratoriais.","B":"artrite reativa. Deve-se iniciar uso de anti-inflamatórios não esteroidais e corticoides orais.\n\nLiberar a paciente para retornar em 48 horas com exames laboratoriais.","C":"artrite séptica. Deve-se iniciar antibioticoterapia venosa, encaminhar imediatamente para\ndesbridamento cirúrgico de urgência da cavidade articular com coleta de material para cultura.","D":"artrite reativa. Deve-se iniciar pulsoterapia com internação para avaliação da resposta ao\ntratamento e seguimento da função renal."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-277412","number":"277412","sourceNumber":"277412","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma paciente de 25 anos apresenta astenia, febre baixa, oligoartrite assimétrica dos\nmembros inferiores, dactilite em mãos e pés,\ndisúria e hiperemia ocular há 1 semana. O diagnóstico\nmais provável para essa paciente é?","options":{"A":"lúpus eritematoso sistêmico","B":"doença de Behçet","C":"sarcoidose aguda","D":"artrite reativa"},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-273147","number":"273147","sourceNumber":"273147","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Considerando os tipos de Artrite Idiopática Juvenil (AIJ), a alternativa que se\nrelaciona à\nAIJ oligoarticular é:","options":{"A":"É o tipo mais frequente, que corresponde a cerca de metade dos casos de AIJ e se caracteriza\npela presença de artrite que atinge até quatro\narticulações, geralmente joelho e/ou tornozelo.","B":"Ocorre quando mais de cinco articulações são atingidas de maneira simétrica nos primeiros 6\nmeses da doença, como pés, tornozelos, joelhos, mãos, pescoço etc.","C":"Ocorre por transmissão hereditária, onde normalmente afeta mais meninas entre o 1º e o 4º ano\nde vida.","D":"É o tipo menos frequente e, além da artrite, tem como característica principal a presença de\nfebre muito alta (acima de 39° C) que vai e\nvolta por um tempo prolongado em 100% dos casos,\nfrequentemente acompanhada de manchas róseas na pele, que tendem a aparecer com a febre e\ndesaparecer quando a temperatura normaliza."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-257735","number":"257735","sourceNumber":"257735","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em pacientes com doenças autoimunes, a principal citocina responsável por elevação\nsérica das proteínas de fase aguda, leucocitose e anemia de doença crônica, e seu respectivo\nmedicamento imunobiológico, é:","options":{"A":"IL-6 - tocilizumabe.","B":"IL-1 - adalimumabe.","C":"BAFF - anti-Blys.","D":"TNF-alfa - abatacepete."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-258185","number":"258185","sourceNumber":"258185","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A febre reumática é uma doença inflamatória e autoimune que apresenta como\ncaracterística:","options":{"A":"A artrite é a manifestação clínica mais frequente da doença aguda, com dor de pequena\nintensidade e proporcional aos demais achados inflamatórios.","B":"As valvas cardíacas mais acometidas são a mitral e a tricúspide e, durante o surto agudo, a\nlesão predominante é a de estenose.","C":"Na eletrocardiografia, o alongamento do intervalo PR é a anormalidade mais importante, sendo\nconsiderado um critério menor para o diagnóstico de cardite.","D":"A profilaxia secundária pode ser feita com penicilina V oral, a qual proporciona menor risco de\nrecorrência da doença quando comparada com a penicilina benzatina intramuscular."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-257736","number":"257736","sourceNumber":"257736","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em 2011, o EULAR (European League Against Rheumatism) publicou novas\nrecomendações para a classificação dos\npacientes com doenças por deposição de cristais de\npirofosfato di-hidratado de cálcio, definindo quatro tipos de apresentação da doença. Nesse\ncontexto,","options":{"A":"a forma assintomática é a apresentação menos comum, e caracteriza-se pelo achado de\ncondrocalcinose em exame de imagem.","B":"a forma de artrite aguda caracteriza-se por poliartrite, com dor forte e edema, sendo bastante\nfrequente em indivíduos com menos de 60 anos de idade.","C":"na forma associada com osteoartrite , observa-se envolvimento de articulações muito usuais na\nosteoartrite primária, tais como os joelhos e a coluna vertebral.","D":"na forma de artrite inflamatória crônica, observa-se poliartrite de grandes e pequenas\narticulações, semelhante à artrite reumatoide."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-258243","number":"258243","sourceNumber":"258243","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Na Artrite Idiopática Juvenil (AIJ):","options":{"A":"O exantema típico, caracterizado por lesões maculares ou maculopapulares na cor\nrosado-salmão, é frequentemente pruriginoso.","B":"A febre de caráter intermitente, com um a dois picos diários, ocorre em 80% dos casos.","C":"A esplenomegalia é volumosa e é mais comum do que a hepatomegalia.","D":"O envolvimento cardíaco pode preceder as manifestações articulares da doença."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-241688","number":"241688","sourceNumber":"241688","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 61 anos, apresenta dor e limitação de movimento em articulações\ninterfalangeanas distais das mãos, de forma\nprogressiva, há cerca de quatro anos. Refere ainda,\nnodulações nos dedos, mais proeminentes no 3º dedo da mão, bilateralmente. História de artralgia\nno joelho esquerdo, sem sintomas sistêmicos, comorbidades ou traumas articulares. Considerando\na imagem, o diagnóstico mais provável é:","options":{"A":"artrite psoriásica.","B":"artrite reativa.","C":"artrite reumatoide.","D":"gota tofácea crônica.","E":"osteoartrite primária."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-246523","number":"246523","sourceNumber":"246523","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Considerando-se os critérios de Jones modificados, na evidência de infecção\nestreptocócica anterior, qual das associações de\nsinais e sintomas preenche critérios para febre\nreumática?","options":{"A":"Febre e artrite.","B":"Cardite e Febre.","C":"Nódulos subcutâneos e artralgia.","D":"Coreia de Sydenham e artrite.","E":"Eritema Marginatun e febre."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-254214","number":"254214","sourceNumber":"254214","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher, 35 anos, artralgia em joelho com sinal de tecla positivo. Submetida a\nartrocentese que revelou presença de cristais\nrombóides com birrefringência positiva. Pode-se\nafirmar que o provável diagnóstico é:","options":{"A":"Gota.","B":"Pseudogota.","C":"Artrite reumatoide.","D":"Nenhuma das anteriores."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-246524","number":"246524","sourceNumber":"246524","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Entre os agentes imunobiológicos utilizados no tratamento da artrite reumatoide, qual\nagente não atua através do bloqueio do TNF-alfa?","options":{"A":"Infliximabe.","B":"Etanercepte.","C":"Golimumabe.","D":"Adalimumabe.","E":"Tocilizumabe."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-241692","number":"241692","sourceNumber":"241692","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"É contraindicação para a realização de artrocentese na artrite séptica:","options":{"A":"hiperglicemia.","B":"imunossupressão.","C":"infecção sistêmica tratada.","D":"trombocitopenia.","E":"uso de antiplaquetários."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-229500","number":"229500","sourceNumber":"229500","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Artrite Reumatoide apresenta um curso de doença progressivo, determinando\ndeformidades decorrentes de ruptura dos tendões e das\nerosões articulares. Entre os achados\ntemos desvio e lesões diversas, qual dos itens está ERRADO pela descrição?","options":{"A":"?Mãos em dorso de camelo?, aumento de volume do punho e das articulações MCF com atrofia\ninteróssea dorsal.","B":"Joelhos valgos, desvio medial.","C":"Tornozelos valgos, eversão da articulação subtalar.","D":"Hálux valgo, desvio medial do hálux."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-229502","number":"229502","sourceNumber":"229502","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A doença reumatoide do pulmão e a vasculite reumatoide são manifestações\nextra-articulares geralmente graves, devendo ser tratadas\ncom imunossupressores. Podemos\nassim aceitar como CORRETA a alternativa:","options":{"A":"Apenas pulsoterapia com succinato de metilprednisolona intravenosa é opção terapêutica.","B":"Pulsoterapia com succinato de metilprednisolona intravenosa, prednisona por via oral,\nazatioprina por via oral, ciclosporina por via\noral intravenosa são opções terapêuticas e nunca a\nciclofosfamida.","C":"Pulsoterapia com succinato de metilprednisolona intravenosa, prednisona por via oral,\nazatioprina por via oral, ciclosporina por via oral e ciclofosfamida intravenosa são opções\nterapêuticas.","D":"Pulsoterapia com succinato de metilprednisolona intravenosa, e ciclofosfamida intravenosa são\nopções terapêuticas não sendo indicado prednisona\npor via oral, azatioprina por via orale\nciclosporina por via oral."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-229503","number":"229503","sourceNumber":"229503","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"O tratamento de Artrite Reumatoide (AR) deve ser iniciado o mais breve possível, uma\nvez que a terapia medicamentosa intensiva\ninstituída precocemente previne danos estruturais\n(erosões), melhorando a capacidade funcional. Podemos CONCORDAR que:","options":{"A":"O período inicial da doença, principalmente as dez primeiras semanas (AR inicial), configura\numa janela de oportunidade terapêutica, isto é,\num momento em que a intervenção farmacológica\nefetiva pode mudar o curso da doença.","B":"O período inicial da doença, principalmente os doze primeiros meses (AR inicial), configura uma\njanela de oportunidade terapêutica, isto é, um momento em que a intervenção farmacológica efetiva\npode mudar o curso da doença.","C":"O período inicial da doença, principalmente os doze primeiros meses (AR inicial), já não\nconfigura uma janela de oportunidade\nterapêutica, visto que a intervenção farmacológica não é\nefetiva pode mudar o curso da doença.","D":"O período tardio da doença, principalmente os dois primeiros anos (AR inicial), configura uma\njanela de oportunidade terapêutica, isto\né, um momento em que a intervenção farmacológica efetiva\npode mudar o curso da doença."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-246531","number":"246531","sourceNumber":"246531","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Considerando as características da artrite reumatoide, assinale a alternativa incorreta.","options":{"A":"Fator reumatoide positivo, além de compor os critérios prognósticos, é um fator prognóstico.","B":"Anti-peptídeos citrulinados cíclicos são marcadores com sensibilidade semelhante à do fator\nreumatoide, mas com especifidade superior, sobretudo na fase inicial da doença.","C":"As manifestações articulares tendem a ser simétricas, embora, quando se trate das IFP, das\nMCF e das metatarsofalangeanas (MTF), a\nsimetria não necessite se completa.","D":"A doença é predominante oligo-articular, acometendo predominantemente grandes articulações,\ncom acometimento menor de pequenas articulações.","E":"Alterações articulares como dedo em pescoço de cisne, dedo em botoeira e desvio ulnar são\nmanifestações tardias da doença, não sendo evidenciadas nas fases precoces da doença."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-246532","number":"246532","sourceNumber":"246532","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Assinale a alternativa incorreta sobre fibromialgia (FM).","options":{"A":"A presença de dor difusa é fundamental para o diagnóstico de pacientes com suspeita de FM.","B":"A polissonografia deve ser solicitada de rotina para os pacientes com FM.","C":"A termografia não deve ser utilizada como ferramenta diagnóstica nos pacientes com FM.","D":"Os pacientes com FM devem ser avaliados quanto a transtorno de humor.","E":"Os pontos dolorosos ainda podem ser úteis no diagnóstico de FM, quando associados a\nsintomas funcionais."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-229505","number":"229505","sourceNumber":"229505","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A falha secundária da Artrite Reumatoide aos Medicamentos Modificadores do Curso\nda Doença (MMCD), quando, após resposta\nsatisfatória inicial, pode ser explicada:","options":{"A":"Esta falha tem sido atribuída ao surgimento de anticorpos contra a molécula dos MMCD\nbiológicos, que apresentam menor imunogenecidade do que os MMCD sintéticos.","B":"Esta falha tem sido atribuída ao surgimento de anticorpos contra a molécula dos MMCD\nbiológicos, que apresentam maior imunogenecidade do que os MMCD sintéticos.","C":"Esta falha tem sido atribuída ao surgimento de anticorpos contra a molécula dos MMCD\nsintéticos, que apresentam maior imunogenecidade do que os MMCDbiológico.","D":"Esta falha não tem sido atribuída ao surgimento de anticorpos contra a molécula dos MMCD\nbiológicos, que apresentam maior imunogenecidade do que os MMCD sintéticos."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-246533","number":"246533","sourceNumber":"246533","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente masculino, 58 anos, obeso, com história de episódios de artrite recorrente em\nprimeira articulação metatarso-falangiana (MTF) direita. Procura atendimento na unidade de saúde\ncom presença de edema, hiperemia e rubor em primeira articulação MTF direita e joelhos, piorando\nao deambular - sintomas iniciados há 18 horas. O ácido úrico sérico apresenta-se 9,4 mg/dl (VR.\naté 6.0 mg/dl). Qual o melhor tratamento indicado para o caso?","options":{"A":"Colchicina + alupurinol.","B":"Prednisona + alopurinol.","C":"Ibuprofeno + alopurinol.","D":"Alopurinol.","E":"Colchicina e, após resolução da artrite, iniciar alopurionol."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-241701","number":"241701","sourceNumber":"241701","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 44 anos com sintomas crônicos de dores musculares generalizadas, fadiga,\ninsônia e déficit de memória recente. Exame físico com achado de artralgia em quadril\nbilateralmente e em joelho direito, leve limitação articular, sem sinais inflamatórios. Sobre o\nprovável diagnóstico, pode-se afirmar que:","options":{"A":"anormalidades na rotina laboratorial são comuns.","B":"antidepressivos tricíclicos e relaxantes musculares podem ser benéficos.","C":"doença reumatológica pré-existente associa-se a menor risco da doença.","D":"higiene do sono e atividade física são indicadas conforme a gravidade.","E":"anticonvulsivantes apresentam benefício questionável."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-229508","number":"229508","sourceNumber":"229508","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Artrite Reumatoide tem seu diagnóstico estabelecido com base em achados clínicos e\nexames complementares. Podemos APENAS aceitar que:","options":{"A":"O exame histopatológico, estabelece o diagnóstico isoladamente.","B":"Somente exame laboratorial isoladamente estabelece o diagnóstico.","C":"Nenhum exame isoladamente, seja laboratorial, de imagem ou histopatológico, estabelece o\ndiagnóstico.","D":"Nenhum exame de imagem ou histopatológico, estabelece o diagnóstico mesmo em conjunto."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-229509","number":"229509","sourceNumber":"229509","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Além da perda de capacidade funcional na Artrite Reumatoide, pode haver aumento\ntambém da mortalidade, o que demonstra a gravidade da doença, sendo CORRETO que:","options":{"A":"As manifestações articulares como nódulos reumatoides, vasculite, derrame pleural, episclerite e\nescleromalacia perfurante correlacionam-se com pior prognóstico.","B":"As manifestações extra-articulares (nódulos reumatoides, vasculite, derrame pleural, episclerite\ne\nescleromalacia perfurante, entre outras) não correlacionam-se com pior prognóstico.","C":"As manifestações extra-articulares (nódulos reumatoides, vasculite, derrame pleural, episclerite\ne escleromalacia perfurante, entre outras)\ncorrelacionam-se com melhor prognóstico.","D":"As manifestações extra-articulares (nódulos reumatoides, vasculite, derrame pleural, episclerite\ne escleromalacia perfurante, entre outras)\ncorrelacionam-se com pior prognóstico."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-249857","number":"249857","sourceNumber":"249857","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 48 anos apresenta dor, de intensidade 7/10, aumento de volume e limitação\naos movimentos do joelho esquerdo, de início há\numa semana. Nega episódios semelhantes\nanteriormente. Nega trauma local. Foi submetido a uma punção articular e a análise do líquido\nsinovial revelou: volume = 20 ml; cor = amarelo; viscosidade = baixa; leucócitos = 5.000/mm³;\npolimorfonucleares = 55%; cultura = negativa. De acordo com as características descritas, o líquido\nsinovial deste paciente pode ser classificado como:","options":{"A":"normal.","B":"não inflamatório.","C":"inflamatório.","D":"séptico."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-229513","number":"229513","sourceNumber":"229513","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Entre os Medicamentos Modificadores do Curso da Doença (MMCD) sintéticos para o\ntratamento de AR, o metotrexato é o medicamento padrão, devendo ser iniciado tão logo o\ndiagnóstico seja definido. Podemos ACEITAR que:","options":{"A":"Metotrexato não foi seguro, apesar de eficaz na redução de sintomas, na incapacidade\nfuncional.","B":"Metotrexato foi seguro e eficaz na redução de sintomas, na incapacidade funcional, mas não no\ndano estrutural.","C":"Metotrexato foi seguro e eficaz na redução de sintomas, na incapacidade funcional e no dano\nestrutural, sendo semelhante a leflunomida e superior a outros MMCD sintéticos.","D":"Metotrexato foi inseguro e ineficaz na redução de sintomas, na incapacidade funcional."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-252755","number":"252755","sourceNumber":"252755","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente de 35 anos, do sexo feminino, procura atendimento referindo rigidez matinal\nnas articulações, com duração de mais de 1 hora,\nprincipalmente nas articulações das mão e pés,\nfadiga, febre, mal-estar e aparecimento de nódulos subcutâneos. Ao exame, há artrite e\ndeformidade em articulações metacarpofalangenas e interfalangenas proximais. Algumas\narticulações apresentam deformidades em pescoço de cisne. Exames mostraram derrame pleural\nna radiografia de tórax, anemia normocítica normocrômica no hemograma, proteína C reativa e\nvelocidade de hemossedimentação aumentadas. Radiografia das articulações mostra edema de\ntecidos moles, perda simétrica do espaço articular, e erosões subcondrais, nas articulações das\nmãos. Anticorpo antipeptídeo citrulinado positivo. O diagnóstico mais provável é:","options":{"A":"Síndrome de Sjogren.","B":"Artrite enteropática.","C":"Granulomatose de Wegener.","D":"Artrite reumatoide."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-252756","number":"252756","sourceNumber":"252756","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A síndrome de Felty se caracteriza por:","options":{"A":"Artrite reumatoide, esplenomegalia e neutropenia.","B":"Lúpus eritematoso sistêmico, leucocitose e hepatomegalia.","C":"Esclerose sistêmica, plaquetopenia e cardiomegalia.","D":"Vasculite crioglobulinêmica, linfocitose e hepatomegalia."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-234340","number":"234340","sourceNumber":"234340","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Nos processos articulares inflamatórios, as possibilidades diagnósticas são definidas de\nacordo com o número de articulações envolvidas. Em um paciente com monoartrite aguda, a\nartrocentese contribui para auxílio na investigação diagnóstica e, na suspeita de uma causa\ninflamatória, o líquido sinovial apresenta como características:","options":{"A":"Claridade transparente e cor vermelha.","B":"Viscosidade baixa e contagem de neutrófilos maior que 50%.","C":"Contagem de leucócitos menor que 200 células/mm³ e claridade opaca.","D":"Cor amarela e viscosidade alta."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-232241","number":"232241","sourceNumber":"232241","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A artrite reativa é uma enfermidade sistêmica, caracterizada por sintomas gerais e\nmanifestações articulares. Tem um pico de incidência dos 20 aos 40 anos e é incomum em\nindivíduos menores de 15 anos e em idosos. Vários fatores de risco podem influenciar o\nprognóstico dos pacientes em relação à cronificação da doença. Dentre estes fatores, cita-se:","options":{"A":"Presença de manifestações viscerais.","B":"Sexo feminino.","C":"Etiologia intestinal, associada à Shigella flexneri.","D":"Presença do HLA-DR4."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-234341","number":"234341","sourceNumber":"234341","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 72 anos queixa-se de dor de forte intensidade (9/10) e edema do joelho\nesquerdo, de início há um dia. A radiografia\nsimples mostra calcificação linear do menisco medial. A\nanálise do líquido sinovial mostra, à microscopia de luz polarizada, a presença de cristais\nromboides com birrefringência positiva fraca. A principal hipótese diagnóstica para este paciente\né:","options":{"A":"Gota.","B":"Artrite reativa.","C":"Condrocalcinose.","D":"Artrite séptica."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-249876","number":"249876","sourceNumber":"249876","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Quais os critérios maiores utilizados para se fazer diagnóstico de febre reumática?","options":{"A":"Artrite, cardite, coreia, nódulos subcutâneos e eritema marginado.","B":"Febre, artralgia, alteração no eletrocardiograma (ECG), aumento de VHS (velocidade de\nhemossedimentação) e aumento de PCR (proteína C reativa).","C":"Faringotonsilite, gânglios cervicais, febre, taquicardia.","D":"Alteração de ASLO (antiestreptolisina O), polidipsia, irritabilidade, pletora clínica."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-229874","number":"229874","sourceNumber":"229874","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Doenças reumatológicas têm, de forma geral, uma predileção pelo sexo feminino, à\nEXCEÇÃO de:","options":{"A":"LES.","B":"espondiloartropatias soronegativas.","C":"Fibromialgia.","D":"artrite reumatoide."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-234401","number":"234401","sourceNumber":"234401","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente do sexo feminino, de seis anos, apresenta artrite há três meses de punho\nesquerdo e nos joelhos (com contratura em\nflexão e diminuição do espaço articular à radiologia),\nsem outras manifestações clínicas. O resultado do FAN é 1:320, com padrão nuclear pontilhado.\nQual é a melhor interpretação deste achado laboratorial?","options":{"A":"Pior prognóstico do envolvimento articular.","B":"Risco relativo maior para desenvolver espondiloartropatia.","C":"Risco relativo maior para desenvolver lúpus (LES)","D":"Maior chance de desenvolver manifestação extra-articular."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-201929","number":"201929","sourceNumber":"201929","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma mulher de 25 anos, casada e com 2 filhos, chega ao posto de saúde para consulta\neletiva relatando dor em todo o corpo há 3 meses, de início após mudança de emprego, fadiga\nconstante, cefaléia, sensação de edema nos dedos das mãos, parestesias e sono não reparador.\n\nAssinale a alternativa correta, que apresenta a conduta inicial mais adequada, considerando o caso\nclínico:","options":{"A":"solicitar hemograma e TSH e iniciar analgésico comum e relaxante muscular","B":"iniciar paracetamol e codeína","C":"iniciar anti-inflamatório não hormonal e orientar consulta com psicólogo","D":"solicitar radiografia de mãos e punhos e iniciar anti-inflamatório hormonal","E":"iniciar antidepressivo e orientar exercícios físicos"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-217017","number":"217017","sourceNumber":"217017","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre a fisiopatologia da artrite gotosa, assinale a alternativa correta.","options":{"A":"A maioria dos pacientes com gota produz quantidade elevada de ácido úrico.","B":"Há precipitação de cristais de monourato de cálcio no espaço sinovial.","C":"A doença é rara em homens abaixo de 30 anos e em mulheres antes da menopausa.","D":"Cerca de 75% dos indivíduos com hiperuricemia são afetados pela gota.","E":"Obesidade, dislipidemia e aterosclerose não se associam ao risco da doença."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-210556","number":"210556","sourceNumber":"210556","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A respeito do tratamento da artrite sépica não complicada com hemocultura positiva,\nassinale a afirmativa correta.","options":{"A":"Na presença de cocos gram-positivos, a primeira escolha é vancomicina.","B":"O achado de diplococos gram-negativos contrapõe a suspeita de artrite gonocócica.","C":"Se precedida por mordedura de cão ou gato, é indicada ampicilina-sulbactam.","D":"A artrite pós-procedimento pode ser tratada em monoterapia com cefepime.","E":"No caso de bacilos gram-negativos, ceftazidime é uma opção ineficaz."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-210557","number":"210557","sourceNumber":"210557","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre os fatores desencadeantes da crise aguda de gota, julgue os itens\nsubsequentes. l. Ingesta excessiva de\nálcool; ll. Deficiência dietética de purinas; lll. Exercício físico\nextenuante; lV. Radioterapia. Pode-se afirmar que:","options":{"A":"Apenas os itens l, ll e lll estão certos.","B":"Apenas os itens l e lll estão certos.","C":"Apenas os itens l, lll e lV estão certos.","D":"Apenas os itens ll e lV estão certos.","E":"Apenas os itens lll e lV estão certos."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-201948","number":"201948","sourceNumber":"201948","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Considere uma mulher de 40 anos, com quadro de mialgia generalizada, inchaço\narticular, cansaço, insônia, formigamento e\ndormência em MMSS. Ao exame físico: avaliação\nneurológica e articular dentro da normalidade. Exames laboratoriais, como PCR, VHS, TSH, T4 livre\ne fator antinúcleo normais. Qual é o diagnóstico mais provável?","options":{"A":"fibromialgia","B":"gota","C":"polimialgia reumática","D":"polimiosite","E":"artrite reumatoide"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-214170","number":"214170","sourceNumber":"214170","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Segunda a Sociedade Brasileita de Pediatria e a Sociedade Brasileira de Reumatologia,\na artrite idiopática juvenil (AIJ) é\nutilizada para definir um grupo de doenças de etiologia\ndesconhecida, caracterizadas pela presença de artrite crônica de ínicio antes dos 16 anos de idade.\nEsta patologia provoca aumento do volume articular pela presença de dor associada à limitação do\nmovimento articular, presente por pelo menos seis semanas. Na avaliação laboratorial em casos de\nArtrite Idiopática Juvenil afirma-se que","options":{"A":"o fator reumatoide é positivo na maioria dos casos.","B":"a forma poliarticular deve ser acompanhada de fator reumatoide postivo.","C":"a presença de valores normais de marcadores inflamatórios (como proteína C reativa e\nvelocidade de hemossedimentação) exclui o diagnóstico.","D":"a presença de AAN (anticorpo anti-nucleo) positivo está relacionada a maior risco de uveite\nanterior."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-201699","number":"201699","sourceNumber":"201699","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A fibromialgia é uma afecção crônica, caracterizada pela presença de dor difusa e\ngeneralizada, cujo tratamento medicamentoso deve incluir:","options":{"A":"Analgésicos comuns, como o paracetamol, e anti-inflamatórios não hormonais, efetivos no\ntratamento de sensibilização central.","B":"Antidepressivos tricíclicos, como a amitriptilina, em doses superiores a 50 mg/dia, efetiva no\ntratamento da dor, da fadiga, além de melhorar o sono.","C":"Anticonvulsivantes, como a pregabalina e a gabapentina, benéficos na redução da dor e na\nmelhora do padrão do sono.","D":"Hipnóticos não diazepínicos, como o zolpidem, que bloqueia o reflexo nociceptivo espinal,\ndevendo ser mantido por tempo prolongado."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-202707","number":"202707","sourceNumber":"202707","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Ao exame físico do aparelho osteoarticular compõe-se da realização de vários testes e\nmanobras específicas, com o objetivo de auxiliar o diagnóstico clínico. Nesse contexto, o teste de\nPatrick-Fabere é utilizado para a avaliação de:","options":{"A":"Doença da sacroilíaca contralateral.","B":"Contratura do músculo reto femoral.","C":"Deformidade em flexão do quadril.","D":"Fraqueza do músculo glúteo médio."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-202716","number":"202716","sourceNumber":"202716","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A gota é uma doença hereditária crônica do metabolismo das purinas, que acomete,\nprincipalmente, o sexo masculino, entre a terceira e a quarta décadas de vida. Várias condições\npodem se associar à gota e/ou hiperuricemia, dentre as quais se inclui:","options":{"A":"amiloidose.","B":"hipertireoidismo.","C":"pneumopatia intersticial.","D":"pré-eclâmpsia."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-202708","number":"202708","sourceNumber":"202708","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Os critérios de Jones existem para facilitar o diagnóstico de um surto agudo de febre\nreumática. Existem os critérios maiores e os menores. É um critério maior:","options":{"A":"Febre.","B":"Artralgia.","C":"Aumento do intervalo PR no Eletrocardiograma (ECG).","D":"Nódulos subcutâneos."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-215433","number":"215433","sourceNumber":"215433","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"No Brasil, estudo epidemiológico constatou que a Artrite Psoríaca AP é a segunda\nespondiloartropatia mais frequente, com prevalência de 13,7% em relação às espondiloartrites.\nEstá inadequado apenas o item:","options":{"A":"Ocorre predominância de ocorrência no sexo masculino (59% versus 41%) e a manifestação\nperiférica da doença.","B":"Em relação à patogênese, a AP é uma doença autoimune poligênica, de etiologia definida.","C":"As citocinas relacionadas a linfócito T desempenham papel central.","D":"Fatores ambientais (microtrauma e agentes infecciosos) têm sido relacionados."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-173539","number":"173539","sourceNumber":"173539","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 40 anos apresenta artrite nos pés, tornozelos, joelhos, mãos e punhos, de\ninício há cinco anos, em uso apenas de corticoide injetável durante este período. Sem outras\nqueixas. Ao exame físico, encontra-se em regular estado geral, corada, afebril, com artrite nos\njoelhos, punhos e metacarpofalangianas, squeeze test positivo nos pés e deformidades \"em\nbotoneira\" no 3º e 4º quirodáctilos direitos. Considerando-se a principal hipótese diagnóstica para\nessa paciente, a deformidade descrita nos quirodáctilos caracteriza-se por:","options":{"A":"Hiperextensão da articulação interfalangiana proximal e flexão da articulação interfalangiana\ndistal.","B":"Flexão da articulação interfalangiana proximal e hiperextensão da articulação interfalangiana\ndistal.","C":"Subluxação da articulação interfalangiana proximal e reabsorção da articulação interfalangiana\ndistal.","D":"Reabsorção da articulação interfalangiana proximal e subluxação da articulação interfalangiana\ndistal."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-182451","number":"182451","sourceNumber":"182451","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um homem de 35 anos, branco, apresenta lombossacralgia inflamatória há 1 ano. Há 1\nmês, teve episódio de uveíte anterior e artrite transitória do joelho direito e do tornozelo\nesquerdo. A\nradiografia de sacroilíacas revela sacroileíte bilateral e simétrica. O ecocardiograma demonstra\ninsuficiência aórtica moderada. O provável diagnóstico é:","options":{"A":"síndrome de Reiter","B":"febre reumática aguda","C":"espondilite anquilosante","D":"lúpus eritematoso sistêmico"},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-182453","number":"182453","sourceNumber":"182453","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Com relação aos achados laboratoriais da artrite reumatoide, assinale a afirmativa\ncorreta:","options":{"A":"o fator reumatoide é um autoanticorpo dirigido contra a porção Fab de uma imunoglobulina M","B":"o anti-CCP é um anticorpo altamente sensível, porém pouco específico","C":"pacientes com síndrome de Felty têm leucocitose com eosinofilia","D":"o anti-CCP está associado a doença grave e erosiva"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-186519","number":"186519","sourceNumber":"186519","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 35 anos com artrite rematoide há 6 meses, com doses estáveis de\nprednisona 10mg/dia, metotrexato 25 mg/semana,\nácido fólico 10mg/semana, apresenta rigidez\nmatinal de 30 minutos e DAS 28 de 3,6. Qual das afirmativas está correta?","options":{"A":"Paciente com boa resposta articular, com doses terapêuticas adequadas, rigidez matinal mínima;\ndeverá retornar em 3 meses para reavaliação.","B":"Paciente com atividade moderada de doença, em uso de prednisona acima de 7,5mg/dia por\nmais de 3 meses; considerar resistência a DMARD inicial.","C":"Paciente com atividade moderada de doença; deverá aumentar prednisona para 15mg/dia,\nmanter a mesma dose do DMARD e retornar em 3\nmeses.","D":"Paciente com atividade leve de doença, com tratamento adequado; considerar infiltração\nintra-articular e anti-inflamatório não esteroide."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-186505","number":"186505","sourceNumber":"186505","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Escolar do sexo feminino iniciou com dores articulares em punhos, tornozelos e joelhos\nhá 15 dias, tendo procurado a emergência\nonde prescreveram ácido acetil-salicílico e solicitaram\nexames complementares. Mãe relata que as dores sumiram, mas há 02 dias surgiram diversos\ncaroços no corpo da menina. Exame físico: bom estado geral, afebril e corada. ACV: RR 2T BNF,\nsem sopros, FC: 90bpm; presença de nódulos indolores em topografia de proeminências ósseas e\ntendões. Exames laboratoriais: Hb: 12,2g/dl, leucócitos: 11.000/mm3 sem desvio para a esquerda,\nVHS: 60 mm/1ª hora e ASLO: 1.5350U Todd. Com base no quadro clínico descrito, o exame\ncomplementar que deve ser solicitado com urgência é:","options":{"A":"Ecocardiografia.","B":"Eletrocardiograma.","C":"Ultrassonografia dos nódulos.","D":"Fator antinuclear (FAN)."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-158472","number":"158472","sourceNumber":"158472","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A gota é uma doença caracterizada pela deposição intra-articular de cristais. Nessa\ndoença:","options":{"A":"A colchicina é utilizada no tratamento para inibir a xantina-oxidase, bloqueando assim a síntese\nde ácido úrico.","B":"A fase crônica cursa com lesões líticas ósseas Peri articulares, visualizadas por métodos de\nimagem como saca bocado.","C":"Os cristais de ácido úrico, quando visualizados por microscópio de luz polarizada, apresentam\nbirrefringência fortemente positiva.","D":"Os agentes hipouricemiantes, tais como o alopurinol e o febuxostat, inibem a reabsorção de\nácido úrico nos túbulos renais proximais"},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-157318","number":"157318","sourceNumber":"157318","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"De acordo com os critérios de Jones para febre reumática, é considerado critério\nmenor:","options":{"A":"Cardite.","B":"Eritema nodoso.","C":"Coreia.","D":"Nódulos subcutâneos.","E":"Artralgia."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-160467","number":"160467","sourceNumber":"160467","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Artrite reumatoide caracterizada por sinovite hipertrófica, destruição articular, ruptura\ntendinosa, compressão de nervos adjacentes e outros, é uma das doenças reumáticas crônicas\nmais dolorosas. Quando acomete a mão, apresenta como característica clínica ser:","options":{"A":"Bilateral.","B":"Assimétrica.","C":"Precoce nas articulações interfalângicas.","D":"Tardia nas articulações metacarpofalângicas."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-156982","number":"156982","sourceNumber":"156982","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 60 anos, com quadro de poliartrite simétrica de mãos, pés e joelhos de\nrigidez pós-repouso maior que 1 hora e aumento do\nvolume das articulações das mãos há 2 meses.\nNo momento, a paciente apresenta tosse seca e dispneia. Sua radiografia de tórax revela nódulos\nmúltiplos pulmonares bilaterais e periféricos. Sobre o caso, qual achado é o mais provável para o\ndiagnóstico?","options":{"A":"Fator antinuclear positivo com padrão homogêneo.","B":"Anticorpo anticitoplasma de neutrófilos positivos.","C":"Fator reumatoide positivo em altos níveis.","D":"Teste tuberculínico fortemente positivo."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-156989","number":"156989","sourceNumber":"156989","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Na artrite reumatoide juvenil:","options":{"A":"Os achados laboratoriais confirmam o diagnóstico.","B":"Para o diagnóstico, é necessário que o paciente apresente febre com duração de no mínimo 6\nsemanas.","C":"O acometimento articular (poli ou oligoarticular) é concomitante às manifestações sistêmicas.","D":"Dentre as manifestações sistêmicas, pode-se citar a hepatomegalia ou esplenomegalia, a\nserosite e o exantema evanescente."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-156993","number":"156993","sourceNumber":"156993","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Na espondilite anquilosante, a manifestação extra-articular mais comum é:","options":{"A":"Uveíte anterior.","B":"Fibrose pulmonar.","C":"Amiloidose.","D":"Estenose aórtica."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-150272","number":"150272","sourceNumber":"150272","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 57 anos, diagnosticada recentemente com artrite reumatoide (DAS 28 = 5,2),\niniciará tratamento com prednisona e metotrexato. Com o objetivo de reduzir os efeitos colaterais\ndo metotrexato, particularmente aftas orais, anemia e intolerância gástrica, deve-se orientar a essa\npaciente a administração simultânea de:","options":{"A":"Omeprazol, 20 mg/dia.","B":"Sulfametoxazol-trimetoprim, 80/400 mg, três vezes ao dia.","C":"Ácido fólico, 10 mg por semana.","D":"Vitamina D, 800 UI/dia."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-150764","number":"150764","sourceNumber":"150764","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Criança diagnosticada com febre reumática aos cinco anos por lesão na válvula mitral e\naórtica, apresenta hoje ecocardiograma sem alterações. Recebe benzetacil há cinco anos. Nesse\ncaso, até quando essa criança deverá continuar com a profilaxia secundária?","options":{"A":"Até os 18 anos.","B":"Até os 21 anos.","C":"Até os 25 anos.","D":"Por toda a vida."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-150241","number":"150241","sourceNumber":"150241","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Pré-escolar de três anos apresenta, há seis meses, artrite envolvendo ambos os\njoelhos e tornozelo esquerdo, acompanhada\nde dificuldade para deambular especialmente pela\nmanhã. Ao exame, apresentava discreta flexão nos joelhos e grande aumento de volume dos\njoelhos e tornozelo esquerdo, sem outras alterações sistêmicas aparentes. De acordo com a\nhipótese diagnóstica, esta paciente poderá ter, também, lesão:","options":{"A":"Cardíaca.","B":"Ocular.","C":"Cerebral.","D":"Renal."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-150761","number":"150761","sourceNumber":"150761","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Na artrite idiopática juvenil, subtipo AIJ relacionada à entesite, é necessária a\npresença\nde artrite e entesite. Na ausência de uma\ndelas, a presença de quais critérios permite o\ndiagnóstico?","options":{"A":"HLA-B27 e idade maior que oito anos.","B":"HLA-B27 e dactilite.","C":"Idade maior que oito anos e história de espondilite\nanquilosante em parente de primeiro grau.","D":"Dor à compressão de sacroilíaca e história de espondilite anquilosante em parente de primeiro\ngrau."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-150278","number":"150278","sourceNumber":"150278","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"O antígeno HLA com o alelo B27 tem risco relativo entre 90 a 100% na enfermidade:","options":{"A":"Hepatite ativa crônica.","B":"Espondilite anquilosante.","C":"Artrite reumatoide.","D":"Diabetes do tipo 1."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-127102","number":"127102","sourceNumber":"127102","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um menino branco, de 9 anos, começou a apresentar dor e aumento de volume do\njoelho direito há 2 meses. Recebeu\nanti-inflamatório não hormonal por 7 dias, sem melhora. A\nclaudicação e as dores são piores pela manhã. Nega antecedentes de infecção ou outros sintomas\nassociados. Na história familiar, refere que o pai tem espondilite anquilosante. Ao exame físico,\napresenta claudicação intensa. O joelho direito revela aumento de volume e é mantido em\nsemiflexão, e o joelho esquerdo, dor no bordo patelar (posição de 2 a 10 horas) e dor à\ndigitopressão da tuberosidade anterior da tíbia. Constata-se ainda, leve aumento de volume e dor\nà digitopressão da inserção do tendão do calcâneo à esquerda. E mais: hemoglobina = 12g/dL,\n12.800 leucócitos/mm³ (60 neutrófilos e 29 linfócitos), 500.000 plaquetas/mm³, VHS = 70mm/1ª\nhora , proteína C reativa = 5,4mg/dL (referência = 0.5mg/dL) e fator reumatoide negativo. A\nultrassonografia mostra moderada quantidade de liquido distendendo a bursa suprapatelar do\njoelho direito, associada a espessamento da sinóvia. Com PPD negativo e HLA-B27 positivo, a\nbiopsia sinovial revela infiltrado inflamatório mononuclear, compatível com\n\nsinovite crônica inespecífica. O tipo de manifestação ocular que pode ocorrer em pacientes como\nesse é:","options":{"A":"Catarata subcapsular.","B":"Síndrome de Sjögren.","C":"Doença de Eales.","D":"Doença ocular isquêmica.","E":"Uveíte anterior aguda."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-127105","number":"127105","sourceNumber":"127105","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma pré-escolar de 2 anos vem ao ambulatório com história de 9 semanas de aumento\nde volume em joelhos, punho direito e\ntornozelo esquerdo. Ao exame físico, apresenta artrite nas\narticulações referidas. O hemograma, bioquímica e urina l foram normais, com exceção da VHS\n(50), ASLO (400U Todd) e FAN (1/160 com padrão homogêneo). Qual é o diagnóstico?","options":{"A":"Lúpus eritematoso sistêmico.","B":"Artrite reumatoide juvenil forma poliarticular.","C":"Febre reumática.","D":"Artrite reumatoide juvenil forma pauciarticular.","E":"Artrite reacional."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-127973","number":"127973","sourceNumber":"127973","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Com relação ao tratamento da Artrite Reumatóide (AR), conforme as recomendações\ndo Consenso 2012 da Sociedade Brasileira de\nReumatologia, Assinale a alternativa correta:","options":{"A":"O metotrexato é a medicação padrão no tratamento da AR porque reduz sinais, sintomas e\nprogressão das lesões radiográficas.","B":"Os antimaláricos têm, como principal efeito colateral, o risco de glaucoma e tem ação na\nprogressão radiológica da doença.","C":"Corticoesteróides são indicados na AR para controle da inflamação e da dor, em doses\nsuperiores a 15 mg ao dia de prednisona.","D":"Nas gestantes, todas as drogas modificadoras do curso da doença devem ser suspensas, pois\nnenhuma delas pode ser usadas nessas ocasiões."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-127975","number":"127975","sourceNumber":"127975","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A manifestação extra-articular mais comum de espondilite anquilosante é a:","options":{"A":"Fibrose pulmonar.","B":"Uveíte anterior.","C":"Amiloidose.","D":"Conjuntivite."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-127979","number":"127979","sourceNumber":"127979","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A síndrome de Reiter tem como característica mais comum, exceto:","options":{"A":"Presença de úlceras orais e uretrite.","B":"Marcante melhora depois de 24 a 48 horas da administração de antibióticos.","C":"Em geral, se segue-se a disenteria por Shiguella ou outras bactérias.","D":"A artrite com frequência envolve as grandes articulações de carga (joelho e tornozelo,\nprincipalmente)."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-138253","number":"138253","sourceNumber":"138253","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Considerando o Consenso Brasileiro para tratamento da artrite reumatoide,","options":{"A":"o uso de anti-TNFs está limitado à presença de falha de drogas modificadoras do curso de\ndoença (DMARDs) imunobiológicas.","B":"o uso de ICAD (indicadores clínicos de atividade de doença) está restrito ao ambiente de\npesquisa clínica.","C":"os pacientes com artrite reumatoide têm risco aumentado para TB (tuberculose) ativa e,\nportanto, devem receber quimioprofilaxia para esta doença.","D":"o rastreamento de tuberculose é recomendado para o uso de agentes imunobiológicos e,\nquando indicado, tratamento de TBIL (tuberculose infecção latente)."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-138258","number":"138258","sourceNumber":"138258","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"J.B.S., de 45 anos, do sexo feminino, foi atendida em ambulatório de clínica médica\ncom relato de que, há oito anos, apresenta\ndor na região plantar dos calcanhares e que, após ter\nsido submetida à avaliação médica, recebeu o diagnóstico de reumatismo e que lhe haviam sido\nprescritos medicamentos cujos nomes não se recorda. Nesse intervalo de tempo, passou a\napresentar dor e alterações nos punhos, que a impossibilitam de fechar as mãos e também dor e\nvermelhidão nos joelhos e tornozelos. Apresentou, também, rigidez matinal, com duração de três\nhoras, por vários meses. Negou possuir outras doenças e informou que sua mãe apresentava\nproblema de reumatismo. Ao exame físico, observaram-se diminiução da flexão dos punhos\n(bilateralmente), dor nas articulações metacarpofalangianas (bilateralmente), presença de discreto\nderrame articular nos joelhos e dor à palpação das articulações metacarpofalangianas e dos\ncalcanhares. O restante do exame não apresentou alterações. Exames complementares realizados\nmostraram fator reumatoide (teste do látex) positivo, níveis elevados de proteína C reativa e\naceleração da velocidade de hemossedimentação. Radiografias das mãos e dos pés mostraram\nestreitamento dos espaços articulares e lesões ósseas erosivas. Com base nestas informações\nclínico-laboratoriais, o principal diagnóstico para a paciente é:","options":{"A":"lúpus eritematoso sistêmico.","B":"artrite reumatoide.","C":"espondilite anquilosante.","D":"doença de Behçet."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-109200","number":"109200","sourceNumber":"109200","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menino de três anos apresenta há dois meses história de febre alta vespertina e\nexantema macular em tronco, artrite de joelhos\ne punho direito. Ao exame, além de artrite,\nencontra-se com linfonodomegalia generalizada e hepatoesplenomegalia. Os exames\ncomplementares mostram hemoglobina: 9,0 g/dl; hematócrito: 27% e 20.000 leuc/mm³; VHS = 95\nmm na primeira hora. A radiografia de tórax revela aumento da área cardíaca. O diagnóstico mais\nprovável é:","options":{"A":"Febre reumática.","B":"Doença de Kawasaki.","C":"Artrite idiopática juvenil.","D":"Leucemia linfoblástica aguda."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-101170","number":"101170","sourceNumber":"101170","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A condrocalcinose está relacionada a condições clínicas como hipotireoidismo,\nhipomagnesemia, hipofosfatemia e\nhiperparatireoidismo, e manifesta-se como uma monoartrite\nsemelhante à gota. Que substância forma depósitos na articulação de um paciente com\ncondrocalcinose?","options":{"A":"Cristais de urato.","B":"Cristais de fosfato de cálcio.","C":"Cristais de pirofosfato de cálcio.","D":"Cristais de carbonato de cálcio."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-101238","number":"101238","sourceNumber":"101238","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 49 anos procura assistência médica com queixas de dor e edema nas mãos\ne nos punhos, de início há seis meses, que\npiora com o repouso e está associada à rigidez matinal\nde duas horas. Nega outras queixas. Ao exame físico, apresenta artrite nos punhos e em todas as\ninterfalangianas proximais de ambas as mãos. Os exames complementares revelam: VHS = 54\nmm; PCR = 56 mg/dl; hemograma = normal; FAN = negativo; fator reumatoide = negativo;\nsorologias para hepatites virais e HIV = negativas; radiografia das mãos = normal. Nesse caso, a\nconduta é:","options":{"A":"Iniciar, imediatamente, sulfassalazina 2 g/dia.","B":"Solicitar anti-CCP ou ressonância nuclear magnética das mãos.","C":"Iniciar, imediatamente, colchicina 1 mg/dia.","D":"Solicitar HLA-B27 e radiografia das sacroilíacas."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-109160","number":"109160","sourceNumber":"109160","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher, de 24 anos, vem apresentando constantemente parestesias no segundo e\nterceiro quirodáctilos esquerdos que se exarcebam\ncom a flexão do punho. O quadro é compatível\ncom:","options":{"A":"Distrofia muscular e radbomiólise.","B":"Mielodisplasias e cirrose biliar primária.","C":"Fibromialgia e climatério.","D":"Mixedema e gravidez."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-79576","number":"79576","sourceNumber":"79576","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma menina de 5 anos sofre de edema no joelho direito há 3 meses. Exame físico:\naumento de volume, discreta dor à\nmovimentação do mesmo joelho e atrofia da musculatura\nadjacente da coxa direita. O restante do exame é normal. Diante disso, é CORRETO afirmar que:","options":{"A":"A hipótese diagnóstica mais provável é febre reumática.","B":"A imobilização do joelho direito está indicada.","C":"A criança deve ser encaminhada ao oftalmologista.","D":"A criança tem risco aumentado para desenvolver lesões de válvulas cardíacas."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-84375","number":"84375","sourceNumber":"84375","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"O uso prolongado de corticoide pode ocasionar:","options":{"A":"Linfocitose.","B":"Neutropenia.","C":"Neutrofilia.","D":"Trombocitopenia.","E":"Anemia megaloblástica."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-64575","number":"64575","sourceNumber":"64575","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A dose equivalente, para 5 mg de prednisona é de: HC: hidrocortisona; TC:\ntriancinolona; DX: dexametasona; BM: betametasona; MP: metilprednisolona.","options":{"A":"20 mg de HC; 4 mg de TC; 0,75 mg de DX;","B":"20 mg de HC; 10 mg de MP; 0,9 mg de DX;","C":"100 mg de MP; 1 mg de DX; 20 mg de BM;","D":"10 mg de HC; 4 mg de DX; 5 mg de BM;","E":"50 mg de HC; 4 mg de TC; 5 mg de BM."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-63427","number":"63427","sourceNumber":"63427","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre a artrite reumatoide, podemos afirmar que são critérios de diagnóstico do Colégio\nAmericano de Reumatologia, exceto:","options":{"A":"Rigidez matinal: rigidez articular durando pelo menos uma hora.","B":"Artrite de três ou mais áreas: pelo menos três áreas articulares com edema de partes moles ou\nderrame articular, observado pelo médico.","C":"Artrite assimétrica de articulações das mãos (punho, interfalangianas proximais e\nmetacarpofalangianas).","D":"Nódulo reumatoide.","E":"Alterações radiográficas: erosões ou descalcificações localizadas em radiografias de mãos e\npunhos."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-61781","number":"61781","sourceNumber":"61781","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A espondilite anquilosante é uma espondiloartropatia que pode ter acometimento\noftalmológico. A uveíte na espondilite anquilosante tem as seguintes características:","options":{"A":"Intermediária, aguda, bilateral.","B":"Anterior, crônica, bilateral.","C":"Posterior, aguda, unilateral.","D":"Anterior, aguda, unilateral.","E":"Posterior, crônica, unilateral."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-48309","number":"48309","sourceNumber":"48309","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Humberto, 35 anos, apresenta um episódio autolimitado de diarreia, surgindo algumas\nsemanas depois um quadro de poliartrite assimétrica de membros inferiores, dactilite nos\npododáctilos, tendinite do aquileu, lesões superficiais, eritematosas e indolores no pênis.\n\nConstata-se que apresenta também uma sacroileíte assintomática e conjuntivite bilateral. Um\nexame de sangue mostra HLA-B27. O diagnóstico\nprovável deste caso é:","options":{"A":"Doença de Behçet","B":"Síndrome de Reiter","C":"Doença de Whipple","D":"Espondilite anquilosante","E":"Reumatismo palindrômico"},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-49009","number":"49009","sourceNumber":"49009","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A artrite reumatoide é uma doença inflamatória crônica e acomete cerca de 0,5 a 1% da\npopulação mundial. A associação entre esta doença, esplenomegalia e neutropenia é denominada\nde:","options":{"A":"Síndrome de Sjögren.","B":"Doença de Still.","C":"Síndrome de Felty.","D":"Doença de Behçet.","E":"Síndrome de Kaplan."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-48297","number":"48297","sourceNumber":"48297","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Constitui um importante efeito colateral ao uso de corticosteroides por via aerossol:","options":{"A":"Necrose asséptica;","B":"Diplopia;","C":"Convulsões;","D":"Disfonia;","E":"Tremor."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-53614","number":"53614","sourceNumber":"53614","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Breno, 3 anos, apresenta episódios febris vespertinos há 30 dias. Mãe nota que,\ndurante os picos febris, a criança tem dores\nnos tornozelos e punhos, manchas avermelhadas no\ntronco e apatia. Ao exame, está afebril, hipocorado e com hepatoesplenomegalia; sinais flogísticos\nsão notados em tornozelos e punhos. Hemoglobina: 7 g/dl; leve leucocitose com predomínio de\nneutrófilos; trombocitose; VSG e proteína C-reativa fortemente elevados. Radiogramas das\narticulações afetadas evidenciam aumento de partes moles sem erosões. Ecocardiografia normal.\nQual é a hipótese diagnóstica mais provável?","options":{"A":"Febre reumática aguda.","B":"Artrite estafilocócica.","C":"Artrite idiopática da infância, forma sistêmica.","D":"Artrite reativa a estreptococo.","E":"Leucemia linfocítica aguda."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-34001","number":"34001","sourceNumber":"34001","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente com 45 anos, tabagista, usuário crônico de anti-inflamatórios não esteroidais\n(AINE) para artrite reumatoide, iniciou há 24\nhoras quadro de melena e epigastralgia intensa. Foi\nsubmetido a endoscopia digestiva alta, que evidenciou uma úlcera duodenal de 1,5 cm, profunda, e\nem seu fundo mínimo sangramento ?em babação?. A hemostasia endoscópica da lesão foi\nrealizada com sucesso. Nesse caso, qual a melhor conduta a seguir?","options":{"A":"Suspender o AINE, pesquisar o Helicobacter pylori e, se positivo, iniciar de imediato o\ntratamento\npara a sua erradicação.","B":"Manter o AINE, iniciar com inibidor de bomba por via oral, e pesquisar o Helicobacter pylori.","C":"Suspender o AINE, iniciar com inibidor de bomba por via oral, e pesquisar o Helicobacter pylori.","D":"Suspender o AINE, iniciar com inibidor de bomba endovenoso e pesquisar o Helicobacter pylori."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-23032","number":"23032","sourceNumber":"23032","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um paciente do sexo masculino, 25 anos, comparece ao ambulatório com queixa de\ndor lombar, bilateral, com irradiação para raiz das coxas, de início há quatro meses. Refere que\nacorda durante a noite pela dor e, quando caminha, a dor melhora. Qual a principal hipótese\ndiagnóstica para esse caso?","options":{"A":"Osteoma osteoide.","B":"Hérnia discal.","C":"Doença degenerativa discal.","D":"Espondilite anquilosante."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-10662","number":"10662","sourceNumber":"10662","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um homem de 35 anos apresenta episódio autolimitado de diarreia, surgindo, algumas\nsemanas depois, um quadro de poliartrite assimétrica de membros inferiores, dáctil e nos\npododáctilos, tendinite do aquileu, lesões superficiais, eritematosas e indolores no pênis.\n\nConstata-se que apresenta também uma sacroileíte assintomática e conjuntivite bilateral. Um\nexame de sangue mostra HLA-B27. O diagnóstico\nprovável deste caso é:","options":{"A":"Doença de Behçet.","B":"Reumatismo palindrômico.","C":"Doença de Whipple.","D":"Espondilite anquilosante.","E":"Síndrome de Reiter."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-11075","number":"11075","sourceNumber":"11075","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"São sinais radiológicos precoces da artrite reumatoide, exceto:","options":{"A":"Edema de tecidos moles Periarticulares","B":"Osteopenia periarticular","C":"Erosões marginais","D":"Fusão de ossos do carpo","E":"Erosões do processo estiloide ulnar"},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-11089","number":"11089","sourceNumber":"11089","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Qual das manobras propedêuticas abaixo, quando positiva, melhor representa o\nacometimento inflamatório das articulações sacroilíacas?","options":{"A":"Lasêgue.","B":"Finkelstein.","C":"Phalen.","D":"Volkmann.","E":"N.d.a."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-273984","number":"273984","sourceNumber":"273984","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"São contraindicações ao uso dos inibidores do Fator de Necrose Tumoral (TNF) em\nportadores de artrite reumatoide:","options":{"A":"Hepatite B, infecções ativas e insuficiência cardíaca classe III.","B":"Tuberculose sem tratamento, bronquite crônica e nefropatia.","C":"Infecção por HIV, idoso, tireoidopatia.","D":"Idoso, infecções ativas e nefropatia."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-176261","number":"176261","sourceNumber":"176261","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Poliartrite simétrica e cumulativa é mais provável com qual das moléstias abaixo?","options":{"A":"Artrite psoriásica.","B":"Gota.","C":"Febre reumática.","D":"Artrite reumatoide juvenil.","E":"Síndrome de Reiter."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-176274","number":"176274","sourceNumber":"176274","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A febre reumática é uma complicação não supurativa de uma infecção das vias aéreas\nsuperiores pelo estreptococo beta?hemolítico do grupo A (EBHA) de Lancefield. Sobre essa\ndoença reumática, assinale a alternativa CORRETA.","options":{"A":"Caracteriza-se por um processo inflamatório transitório que acomete as articulações, o coração,\na pele e os rins.","B":"No Brasil, a febre reumática é a terceira principal causa de cardiopatia crônica adquirida nos\nindivíduos menores de 20 anos de idade.","C":"Sua ocorrência é mais frequente antes dos 5 anos de idade.","D":"A artrite tem caráter migratório, fugaz e autolimitado, poliarticular, geralmente acomete grandes\narticulações (como joelhos, tornozelos, pulsos e cotovelos).","E":"A coreia é a manifestação mais frequente e ocorre de forma isolada mais em meninas."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-155295","number":"155295","sourceNumber":"155295","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"O achado de luxação atlantoaxial em paciente sem histórico de trauma sugere a\nhipótese de:","options":{"A":"Espondilite anquilosante.","B":"Lúpus eritematoso sistêmico.","C":"Artrite reumatoide.","D":"Síndrome de Marfan.","E":"Tuberculose de coluna vertebral."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-155311","number":"155311","sourceNumber":"155311","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menor do sexo masculino, 6 anos de idade, iniciou quadro de febre há 2 dias, com dor\nem terço distal da coxa esquerda, com\nmal-estar e claudicação. Após a avaliação no setor da\nurgência, identificou-se o local doloroso na coxa esquerda. Solicitado hemograma, que evidenciou\nleucocitose e neutrofilia. Resolvido puncionar a região da metáfise do fêmur no local da dor, com\ncoleta e drenagem de secreção purulenta, enviada para exames, inclusive cultura do material. Qual\né o antimicrobiano MAIS ADEQUADO para esse caso?","options":{"A":"Ceftriaxona.","B":"Oxacilina.","C":"Vancomicina.","D":"Amicacina.","E":"Ciprofloxacina."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-105671","number":"105671","sourceNumber":"105671","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A febre reumática é uma complicação não supurativa da faringoamigdalite causada\npelo estreptococo beta-hemolítico do grupo A e\ndecorre de resposta imune tardia a esta infecção\nem populações geneticamente predispostas. Identifique critério maior de Jones (1992) usado para\no diagnóstico dessa patologia.","options":{"A":"Eritema marginado.","B":"Artralgia.","C":"Febre.","D":"Elevação de ASO e VHS.","E":"Aumento do espaço PR."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-62662","number":"62662","sourceNumber":"62662","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em relação à Artrite Reumatoide, é correto afirmar, EXCETO:","options":{"A":"Pacientes com atividade moderada de doença apresentam entre 6 e 20 articulações\ncomprometidas e provas de atividade inflamatórias aumentadas.","B":"Metotrexato é comumente selecionado como terapia para pacientes com atividade moderada de\ndoença.","C":"Os agentes anti-TNF são contraindicados em pacientes com risco de reativação de tuberculose,\na menos que sejam previamente tratados.","D":"Altos títulos de fator reumatoide, nódulos reumatoides e comprometimento extra-articular não\nestão relacionados a mau prognóstico.","E":"Corticoide intra-articular pode ser usado para controle de sinovite."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-35734","number":"35734","sourceNumber":"35734","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A dose equivalente para 5 mg de prednisona é:","options":{"A":"0,6 de betametasona; 4 mg de triancinolona; 0,75 mg de dexametasona.","B":"100 mg de hidrocortisona; 10 mg de metilprednisolona; 0,9 mg de dexametasona.","C":"50 mg de hidrocortisona; 4 mg de dexametasona; 5 mg de betametasona.","D":"100 mg de metilprednisolona; 1 mg de dexametasona; 20 mg de betametasona.","E":"20 mg de hidrocortisona; 4 mg de dexametasona; 5 mg de betametasona."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-28263","number":"28263","sourceNumber":"28263","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Escolar de 8 anos, do sexo feminino, apresenta quadro agudo de febre alta, dor e sinais\ninflamatórios em joelho direito e exantema serpiginoso evanescente e não pruriginoso em tronco,\nque piora com o calor. Exames complementares: leucocitose e VHS elevado. Neste caso, a\nhipótese diagnóstica mais provável é:","options":{"A":"Doença de Kawasaki.","B":"Artrite reativa.","C":"Febre reumática.","D":"Lúpus eritematoso.","E":"Artrite reumatoide."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-308638","number":"308638","sourceNumber":"308638","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Assinale a opção em que se encontra a associação CORRETA que compõe a síndrome\nde Caplan.","options":{"A":"Artrite reumatoide, esplenomegalia e neutropenia.","B":"Artrite reumatoide, nódulos pulmonares e pneumoconiose.","C":"Artralgia, xerostomia e tireoidopatia.","D":"Artrite, pericardite e pleurite.","E":"Artrite, mononeurite e mielopatia."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-302085","number":"302085","sourceNumber":"302085","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Síndrome da Fadiga Crônica (SFC) é uma condição de diagnóstico clínico cujo principal\nsintoma é a presença de fadiga (cansaço) intensa que pode piorar com a atividade física ou mental,\nmas não melhora com o repouso\n\n(https://www.reumatologia.org.br/orientacoes-ao-paciente/sindrome-da-fadiga-cronica/). Qual das\nseguintes opções é um tratamento benéfico para a síndrome ora em tela?","options":{"A":"bupropiona","B":"terapia cognitivo comportamental","C":"doxiciclina","D":"fluoxetina","E":"olanzapina"},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-281498","number":"281498","sourceNumber":"281498","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem jovem procura serviço de emergência por dor de forte intensidade com\nlimitação funcional e sinais flogísticos no\njoelho direito. Febril (38 graus). Sem trauma. Nega\nepisódios anteriores. Restante do exame físico sem alterações. Considerando a principal hipótese\ndiagnóstica, qual a melhor conduta:","options":{"A":"Dosagem de ácido úrico e início de alopurinol","B":"Raio x joelho e início de anti-inflamatórios.","C":"Artrocentese e infiltração articular com corticoide.","D":"Artrocentese e início de antibióticos.","E":"Ressonância magnética de joelho e encaminhamento para ortopedista."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-278930","number":"278930","sourceNumber":"278930","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 42 anos com quadro de artrite aguda em 1ª articulação\nmetatarsofalangiana. A melhor opção terapêutica\nque pode ser utilizada na crise aguda e como\nprevenção de novas crises é:","options":{"A":"Probenecida.","B":"Alopurinol.","C":"Prednisona.","D":"Colchicina.","E":"Alopurinol associado à prednisona."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-244669","number":"244669","sourceNumber":"244669","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em relação à fibromialgia, é INCORRETO afirmar:","options":{"A":"Distúrbios do sono são pouco frequentes.","B":"Cursa com fadiga mental e/ou física ao despertar.","C":"A prevalência é maior em mulheres e a idade média é de 49 anos.","D":"Acomete com mais frequência familiares, parente consanguíneos, podendo afetar crianças.","E":"A síndrome miofascial é importante manifestação satélite."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-218019","number":"218019","sourceNumber":"218019","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"No diagnóstico de febre reumática, utilizamos como critérios maiores de Jones exceto:","options":{"A":"Cardite.","B":"Artrite.","C":"Coreia.","D":"Nódulos subcutâneos.","E":"Elevação de VHS (? 60 mm na 1ª hora) e/ou PCR ? 3 mg/dl (ou > que valor de referência\nindicado)."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-203614","number":"203614","sourceNumber":"203614","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"No tratamento da febre reumática, o antibiótico de primeira linha para a erradicação do\nestreptococo beta-hemolítico (grupo A) da orofaringe é:","options":{"A":"Cefalexina.","B":"Amoxicilina + clavulanato.","C":"Eritromicina.","D":"Azitromicina.","E":"Penicilina benzatina."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-203264","number":"203264","sourceNumber":"203264","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre o tratamento de Artrite Séptica em pediatria, selecione o antimicrobiano de\nprimeira escolha recomendado para o tratamento de um lactente de oito meses de idade, com\ndiagnóstico de Artrite Séptica.","options":{"A":"Vancomicina","B":"Oxacilina","C":"Amicacina","D":"Ceftriaxona","E":"Ciprofloxacina"},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-177505","number":"177505","sourceNumber":"177505","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Criança de 9 meses de idade foi diagnosticada com artrite séptica, sendo realizada\ndrenagem e coleta do material para\ncultura. Qual esquema empírico deve ser iniciado, baseado na\netiologia mais comum nesta faixa etária?","options":{"A":"Ampicilina e Gentamicina","B":"Ceftriaxona","C":"Oxacilina","D":"Ampicilina e Amicacina","E":"Vancomicina"},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-132755","number":"132755","sourceNumber":"132755","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 41 anos, comparece a Unidade Básica de Saúde (UBS) para consulta\nmédica com história de cinco meses de\nmal-estar e rigidez de mãos matinal que melhora ao longo\ndo dia. Refere ainda que as duas mãos estão comprometidas na altura dos pulsos. Os testes\nlaboratoriais iniciais mostram VHS elevado e anti-CCP altamente positivo. Qual dos seguintes\ntratamentos tem maior probabilidade de levar ao melhor resultado em longo prazo para essa\npaciente?","options":{"A":"Ceftriaxona intravenosa.","B":"Metotrexato.","C":"Naproxeno.","D":"Alopurinol.","E":"Ibuprofeno."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-132765","number":"132765","sourceNumber":"132765","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente feminino, 31 anos, refere que há cerca de quarenta dias iniciou quadro de dor\nde garganta e dificuldade para deglutir que\nfoi tratado com azitromicina, sem melhora. Uma semana\napós, iniciou quadro de febre diária no final da tarde, geralmente em torno de 40°C, acompanhada\nde sudorese e calafrios e que cedia, mesmo sem uso de analgésicos. Refere ainda mialgia e a\npresença de um rash evanescente, cor de salmão, não pruriginoso, em tórax e abdome, que\naparece apenas durante os episódios febris. Ao exame físico, apresenta adenomegalia difusa e\nhepatoesplenomegalia. Laboratório mostrou neutrofilia importante (em torno de 30.000/mm³), FR e\nFAN negativos, elevação discreta de enzimas hepáticas, elevação muito acentuada da ferritina. O\ndiagnóstico mais provável é de:","options":{"A":"Linfoma não Hodgkin.","B":"Leucemia mieloide.","C":"Doença de Still.","D":"Mononucleose Infecciosa.","E":"Citomegalovirose."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-108040","number":"108040","sourceNumber":"108040","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Pelos novos critérios de classificação para artrite reumatoide (ACR/EULAR, 2010), é\nmenos importante para o diagnóstico:","options":{"A":"Artrite de pequenas articulações.","B":"Artrite de grandes articulações.","C":"Alterações radiográficas compatíveis.","D":"Anticorpo antiproteína citrulinada em baixo título.","E":"Anticorpo antiproteína citrulinada em alto título."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-87522","number":"87522","sourceNumber":"87522","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem, 27 anos, com lombalgia, pior pela manhã, atenuada progressivamente com o\ndecorrer do dia, presente há 5 semanas. Sem outras queixas. Nega artrite ou artralgia periférica.\nTeste de Schober mostrou expansão da distância marcada em 3 cm à flexão anterior do tronco. Ao\nfazer inspiração máxima, o paciente aumenta em 7 cm o diâmetro torácico. É CORRETO afirmar:","options":{"A":"Se ele tiver uma radiografia ou RNM de articulações sacroilíacas confirmando sacroileíte grau 2\nou maior bilateralmente estará confirmado o\ndiagnóstico de espondilite anquilosante;","B":"Pode-se dar o diagnóstico de espondilite anquilosante, já neste momento, apenas com base em\ncritérios clínicos;","C":"É necessária a positividade do HLA-B27 para o diagnóstico de espondilite anquilosante.","D":"O diagnóstico de espondilite anquilosante não pode ser confirmado sem que o paciente tenha\npelo menos 3 meses de dor.","E":"Está excluída a hipótese de espondilite anquilosante para esse paciente."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-346618","number":"346618","sourceNumber":"346618","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Marque a opção abaixo que é MAIS COMPATÍVEL com a tríade composta por:\ntenossinovite, lesões de pele vesiculopustulares e poliartralgia sem artrite purulenta:","options":{"A":"Doença de Lyme","B":"Infecção gonocócica disseminada","C":"Infecção por Mycobacterium tuberculosis","D":"Infecção por Staphylococcus aureus"},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-330840","number":"330840","sourceNumber":"330840","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre artrite reumatoide, assinale a afirmativa INCORRETA.","options":{"A":"Pode ocorrer acometimento pulmonar (pneumopatia intersticial).","B":"A rigidez matinal geralmente melhora com a atividade.","C":"Provas inflamatórias (PCR, VHS) frequentemente estão elevadas.","D":"Tem acometimento frequente das articulações interfalangianas distais."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-348470","number":"348470","sourceNumber":"348470","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher, 45 anos, chegou ao pronto-socorro trazida pelo SAMU em parada\ncardiorrespiratória. Realizado RCP sem sucesso,\nsendo constatado o óbito. Foi encaminhada à\nnecropsia para investigação da causa do óbito. O exame macroscópico do coração evidenciou\nestenose de valva mitral com fusão das comissuras e dilatação de átrio esquerdo. À microscopia do\nmiocárdio, foram visualizados nódulos de Aschoff nas fibras musculares cardíacas. Qual achado\nsemiológico poderia ser encontrado nessa paciente antes do seu óbito?","options":{"A":"Murmúrio de Carey-Coombs","B":"Sopro de Austin-Flint","C":"Fenômeno de Gallavardin","D":"Sopro circular de Miguel Couto"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-327335","number":"327335","sourceNumber":"327335","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher, 60 anos, em acompanhamento há 15 anos de artrite reumatoide, apresentando\ndeformidades em mãos, retorna ao ambulatório com raio X de mãos e punhos com as seguintes\nalterações radiológicas: hiperextensão das articulações interfalangeanas proximais e flexão das\narticulações interfalangeanas distais. Esses achados correspondem à deformidade em","options":{"A":"dedos em fuso.","B":"dedos em botoeira.","C":"pescoço de cisne.","D":"dedos em martelo."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-313409","number":"313409","sourceNumber":"313409","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem, 28 anos, caminhoneiro, vem para consulta com queixa de dor lombar crônica\ncom piora progressiva no último semestre. A\ndor é pior ao acordar acompanhada de rigidez lombar,\nmas melhora com atividade física. Ao exame físico, o teste de Schober encontra-se alterado. Qual é\no exame mais importante para auxiliar no diagnóstico?","options":{"A":"Anti-CCP.","B":"HLA-B27.","C":"Anti-DNAds.","D":"Cromogranina A."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-267291","number":"267291","sourceNumber":"267291","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em relação aos perfis clínicos de doenças reumáticas, assinale a afirmativa\nINCORRETA.","options":{"A":"Na osteoartrite, a dor é de início gradativo, a rigidez após o repouso é de curta duração, o\nenvolvimento articular é assimétrico e não há queixa sistêmica.","B":"Na artrite reumatoide, o início pode ser agudo, mas usualmente é insidioso, a rigidez matinal é\nprolongada, o envolvimento articular é aditivo e simétrico, o pico de incidência é na quinta década\ne\no envolvimento sistêmico e visceral é frequente.","C":"Nas artrites microcristalinas, o início é agudo, a rigidez é de curta duração, o envolvimento\nusualmente é monoarticular, principalmente em\nmembros inferiores e pode haver febre e adinamia.","D":"Nas artrites infecciosas bacterianas, o início é agudo, há impotência funcional articular,\nusualmente monoarticular."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-267292","number":"267292","sourceNumber":"267292","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre os exames laboratoriais em reumatologia, assinale a afirmativa INCORRETA.","options":{"A":"A ferritina não é usada rotineiramente como reagente de fase aguda. Sua dosagem tem\ninteresse especial na artrite idiopática juvenil do subtipo sistêmico e na síndrome de ativação\nmacrofágica, situações nas quais os níveis costumam ser > 1.000 ng/ml.","B":"A Velocidade de Hemossedimentação (VHS), uma das medidas de inflamação mais usadas na\nprática clínica, apresenta alta sensibilidade e baixa especificidade para o processo inflamatório.\nEla\npode ser alterada por vários fatores, como: idade, microcitose, esferocitose, policitemia, anemia,\nentre outros.","C":"A Proteína C-Reativa (PCR) é o melhor teste de fase aguda na maioria das doenças, pois seus\nníveis refletem o grau de inflamação e caem rapidamente com a melhora da reação. É sintetizada\npelos hepatócitos, em resposta às citocinas pró-inflamatórias.","D":"O Fator Reumatoide (FR) está positivo em cerca de 70-80% dos pacientes com Artrite\nReumatoide (AR), sendo de utilidade apenas no diagnóstico e não no prognóstico da AR."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-267293","number":"267293","sourceNumber":"267293","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre a gota, marque a assertiva CORRETA.","options":{"A":"A homeostase sérica do ácido úrico depende basicamente dos rins. Por ser uma molécula\npequena, ele é totalmente filtrado, sendo 90% reabsorvido no túbulo proximal por meio de\ntransportadores ácidos orgânicos. O mais importante deles é o urati, que pode ser inibido por\nmedicamentos como a losartana potássica e a probenecida.","B":"Apresenta prevalência em torno de 8% e predomínio masculino na proporção de 5:1.","C":"A gota é uma artropatia microcristalina com inexorável evolução para insuficiência renal crônica,\nse não tratada adequadamente. É a forma de\ndoença articular inflamatória mais comum.","D":"Evidências clínicas indicam que indivíduos com a condição denominada hiperuricemia\nassintomática, mesmo que persistente e sem\ndesenvolver gota, não apresentam maior risco para\nhipertensão arterial e doença arterial coronariana."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-283986","number":"283986","sourceNumber":"283986","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem, 28 anos, caminhoneiro, vem para consulta com queixa de dor lombar crônica\ncom piora progressiva no último semestre. A\ndor é pior ao acordar acompanhada de rigidez lombar\nmas melhora com atividade física. Ao exame físico o teste de Schober encontra-se alterado. Qual\nexame mais importante para auxiliar no diagnóstico?","options":{"A":"Anti-CCP","B":"HLA-B27","C":"Anti-DNAds","D":"Cromogranina A"},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-288170","number":"288170","sourceNumber":"288170","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente de 5 anos e sete meses, sexo feminino, branca, natural e procedente de\nVárzea Grande (MT), foi encaminhada para o\nambulatório de reumatologia pediátrica com história\nde artralgia e edema articular no joelho e tornozelo direitos com limitação de movimentos há 6\nmeses. Nega febre. Antecedentes familiares apenas diabetes e hipertensão arterial. Ao exame:\nREG, corada, hidratada, eupneica, acianótica, anictérica, afebril, consciente. AR: MV fisiológico,\nsimétrico, sem RA. ACV: RCR, 2T, sem sopros. Abdômen sem visceromegalias. Osteoarticular:\npresença de edema articular e artralgia nas articulações de joelho e tornozelo direitos. Pele sem\nlesões. Foi solicitada a avaliação oftalmológica e constatada uveíte crônica. Também solicitados e\nrealizados os exames seguintes: hemograma, bioquímica e eletrólitos foram normais. Fator\nReumatoide (FR) não reagente; Velocidade de Hemossedimentação (VHS) de 45 mm/h; Proteína\nC-Reativa (PCR) de 25 mg/dl, Fator Antinuclear (FAN) reagente com padrão homogêneo e\nanticorpos anti-DNA de cadeia dupla (dsDNA), anti-Sm, anti-Ro, anti-La, e anti-RNP, não\nreagentes. Após afastar outras causas, foi estabelecida a hipótese diagnóstica de Artrite Idiopática\nJuvenil (AIJ). Qual o tipo de AIJ segundo a ILAR (International League of Associations for\nRheumatology)?","options":{"A":"Poliarticular fator reumatoide negativo.","B":"Oligoarticular.","C":"Sistêmica.","D":"Artrite psoriásica."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-267338","number":"267338","sourceNumber":"267338","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Adolescente, sexo feminino, há 10 dias apresentou artrite em joelho direito com\nduração de 3 dias e, após, em joelho\nesquerdo com duração de 5 dias. No momento da consulta,\napresentava artrite no tornozelo direito há 2 dias. Relata ainda febre não aferida no início do\nquadro. História de dor de garganta há 1 mês, sem uso de medicações. Nega trauma e viagem\nrecentes. Ao exame físico, bom estado geral, corada, afebril, eupneica. Ausculta cardiovascular:\nsopro holossistólico, mais audível em foco mitral. Frequência cardíaca: 72 bpm. Artrite em tornozelo\ndireito, com dificuldade de deambulação. Sem lesões de pele. Exames laboratoriais: hemograma\nsem alterações, VHS 90 mm/h (até 10 mm/h), proteína C reativa: 10 mg/dL (inferior a 0,3 mg/dL) e\nantiestreptolisina O 800 UI/mL (inferior a 200 UI/mL). A hipótese diagnóstica para o caso e a\nprincipal complicação são:","options":{"A":"Artrite Idiopática Juvenil; Uveíte.","B":"Artrite séptica; Osteomielite.","C":"Síndrome de Marfan; Dissecção de aorta.","D":"Febre Reumática; Cardite Reumática."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-254171","number":"254171","sourceNumber":"254171","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"São achados característicos da Osteoartrite, EXCETO:","options":{"A":"Fator Reumatoide positivo","B":"Esclerose subcondral","C":"Rigidez matinal","D":"Nódulos de Heberden"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-247714","number":"247714","sourceNumber":"247714","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menina de 9 anos de idade apresentando, há 10 dias, artrite do tipo migratória em\ngrandes articulações. Há relato de febre\nepisódica e de amigdalite purulenta duas semanas antes\ndo início do quadro articular. A criança foi avaliada pelo pediatra que, durante o exame clínico,\nconstatou a presença de um sopro holossistólico em foco mitral, irradiando para a axila. Foram\nsolicitados alguns exames: ecocardiograma (relato verbal) ? problema importante em valva mitral;\ncultura de orofaringe positiva para Estreptococo beta-hemolítico do grupo A (EBHGA); níveis de\nanticorpos antiestreptolisina O (ASLO) aumentados. Com base no exposto e nos critérios de Jones\nmodificados para o diagnóstico de febre reumática, é CORRETO afirmar:","options":{"A":"O caso descrito é de alta probabilidade diagnóstica de febre reumática, pois apresenta um sinal\nmaior e dois sinais menores, além da comprovação de infecção prévia por EBHGA.","B":"O caso descrito é de alta probabilidade diagnóstica de febre reumática, pois apresenta dois\nsinais maiores além da comprovação de infecção prévia por EBHGA.","C":"O caso descrito é de baixa probabilidade diagnóstica de febre reumática, pois não apresenta o\nmais importante sinal: coreia independente da comprovação de infecção prévia por EBHGA.","D":"O caso descrito é de baixa probabilidade diagnóstica de febre reumática, pois apresenta apenas\num sinal maior e um sinal menor independente\nda comprovação de infecção prévia por EBHGA."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-214592","number":"214592","sourceNumber":"214592","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente com diagnóstico de artrite reumatoide, com poliartrite envolvendo mãos,\ncarpos, cotovelos, joelhos e tarsos, PCR elevado,\nfator reumatoide em altos títulos, nódulos\nsubcutâneos e queixas sistêmicas (adinamia, hiporexia e febre baixa). Sobre o caso, assinale a\nafirmativa CORRETA.","options":{"A":"O tratamento inicial deve ser feito com a escolha de uma droga modificadora da evolução da\ndoença (DMARD), a exemplo da leflunomida,\nassociada a Anti-Inflamatórios Não Esteroidais (AINE)\ne prednisona em doses baixas.","B":"O tratamento deve ser prontamente iniciado com Anti-Inflamatórios Não Esteroidais (AINE)\nassociados à pulsoterapia com metilprednisolona.","C":"Os dados apresentados indicam se tratar de uma artrite reumatoide agressiva, com prognóstico\nruim. Deve ser prontamente iniciado, portanto,\ntratamento com imunobiológicos.","D":"O tratamento inicial deve ser feito com a escolha de uma droga modificadora da evolução da\ndoença (DMARD), a exemplo do metotrexato nas\ndoses de 25 a 50 mg/semana, associada a\nAnti-Inflamatórios Não Esteroidais (AINE) e prednisona em doses baixas."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-208577","number":"208577","sourceNumber":"208577","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menina, 3 anos de idade, apresenta artrite em joelho direito há 5 meses e em tornozelo\nesquerdo há 3 meses. Os exames laboratoriais mostram alteração das provas de atividade\ninflamatória (velocidade de hemossedimentação, proteína C reativa) e fator antinúcleo positivo.\n\nQual o comprometimento oftalmológico esperado?","options":{"A":"retinite aguda","B":"episclerite crônica","C":"conjuntivite aguda","D":"atrofia nervo óptico","E":"uveíte anterior crônica"},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-177278","number":"177278","sourceNumber":"177278","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma paciente de 24 anos procurou auxílio médico apresentando quadro, iniciado há\numa semana antes, de astenia, febre baixa,\noligoartrite assimétrica nos membros inferiores, dactilite\nem mãos e pés, disúria e hiperemia ocular. O diagnóstico mais provável para essa paciente é:","options":{"A":"lúpus eritematoso sistêmico","B":"doença de Behçet","C":"sarcoidose aguda","D":"artrite reativa","E":"artrite reumatoide"},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-185238","number":"185238","sourceNumber":"185238","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher, 50 anos, diabética, queixa de dor nos joelhos há 3 anos. Inicialmente a dor era\ninsidiosa e aliviava com o repouso, agora persistente e refratária aos analgésicos, com rigidez\nmatinal de 20 minutos e rigidez articular fugaz após curtos períodos de repouso. Instabilidade do\njoelho especialmente ao descer escadas. No exame com crepitação nos joelhos e sinais de\nderrame articular. Radiografia mostra proliferação das margens ósseas, diminuição do espaço\narticular e esclerose óssea subcondral. Sobre o caso, assinale a alternativa CORRETA em relação\nao diagnóstico e tratamento, respectivamente:","options":{"A":"Osteoartrite, exercícios aeróbicos e contra resistência.","B":"Osteoartrite, corticoides sistêmicos.","C":"Artrite reumatoide, imunomoduladores.","D":"Artrite reumatoide, anti-inflamatórios não esteroides.","E":"Gota, alopurinol e colchicina."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-185220","number":"185220","sourceNumber":"185220","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente com 40 anos, procura atendimento na UBS referindo que há quatro meses,\nvem apresentando artrite simétrica de articulações\ndo punho, interfalangeanas proximais e\nmetacarpofalangeanas, além de rigidez articular matinal com duração de pelo menos uma hora.\nAvaliação laboratorial revelou fator reumatoide positivo. Qual dos tratamentos a seguir não modifica\no curso desta doença?","options":{"A":"Prednisona","B":"Sulfassalazina","C":"Metotrexato","D":"Ciclosporina","E":"Nenhuma das alternativas anteriores está correta"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-181592","number":"181592","sourceNumber":"181592","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Na consulta de um portador de Gota, sem crise atual, os exames a serem solicitados na\nprimeira avaliação têm as seguintes finalidades: confirmar diagnóstico, classificação, avaliação da\nseveridade da doença, pesquisa de morbidades associadas e definição do plano terapêutico.\n\nNesse sentido, marque a alternativa que melhor representa a propedêutica inicial para a situação\nacima descrita.","options":{"A":"Hemograma, ácido úrico, glicemia de jejum, ureia, creatinina, TGO, TGP, perfil lipídico,\nUltrassom dos rins e vias urinárias, uricosúria de 24 horas e Rx articular (das afetadas).","B":"Hemograma, ácido úrico, glicemia de jejum, hemoglobina glicada, clearance de creatinina, TGO,\nTGP, fosfatase alcalina, perfil lipídico, Ultrassom de abdome total e Rx articular (das afetadas).","C":"Hemograma, ácido úrico, glicemia de jejum, ureia, creatinina, TGO, TGP, perfil lipídico,\nUltrassom dos rins e vias urinárias, proteinúria e uricosúria de 24 horas, Fator Reumatoide e\nRessonância Magnética articular (das afetadas).","D":"Hemograma, ácido úrico, glicemia de jejum, ureia, creatinina, TGO, TGP, perfil lipídico, Rx de\nabdome e Raio X articular (das afetadas)."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-181607","number":"181607","sourceNumber":"181607","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em relação à febre reumática, assinale a afirmativa INCORRETA.","options":{"A":"É uma doença inflamatória do tecido conectivo que se desenvolve após o contato do hospedeiro\ncom o estreptococo beta-hemolítico do grupo\nA.","B":"Títulos normais de ASLO excluem o diagnóstico de febre reumática e coreia de Sydenham.","C":"Cardite, poliartrite, coreia de Sydenham, eritema marginado e nódulos subcutâneos são sinais\nmaiores da doença.","D":"A regurgitação mitral é a manifestação mais frequente da cardite aguda, sendo a estenose mitral\nsugestiva de doença crônica."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-181562","number":"181562","sourceNumber":"181562","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Quais alterações clínicas NÃO fazem parte do quadro clínico de crianças com artrite\nreumatoide juvenil?","options":{"A":"Artrite cumulativa; febre; anemia.","B":"Pericardite; uveíte; linfonodomegalias.","C":"Alopecia; eritema malar; monoartrite infecciosa.","D":"Exantema maculopapular que acompanha os picos febris; hepatoesplenomegalia."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-167796","number":"167796","sourceNumber":"167796","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 30 anos, queixando-se de ardência uretal, olhos vermelhos com ardência e\nlacrimejamento e sinais de poliartrite. Qual o diagnóstico clínico?","options":{"A":"Síndrome de Sjogreen","B":"Espondilite anquilosante","C":"Síndrome de Reiter","D":"Gonococcia"},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-158084","number":"158084","sourceNumber":"158084","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre gota, assinale a afirmativa INCORRETA:","options":{"A":"Estudos recentes implicam a hiperuricemia como fator de risco para doença coronariana,\ndevendo ser devidamente corrigida em pacientes\nde risco.","B":"Nos pacientes hipertensos, losartana potássico pode ser uma boa opção e o uso de diuréticos\ndeve ser evitado.","C":"Na avaliação inicial, são importantes os seguintes exames: hemograma, uricemia, uricosúria de\n24 horas, TGO, TGP, creatinina e\nultrassonografia dos rins e vias urinárias.","D":"O alopurinol, que atua aumentando a excreção urinária de ácido úrico, ocupa lugar de destaque\nno tratamento da gota."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-158101","number":"158101","sourceNumber":"158101","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente do sexo feminino, 42 anos, referindo que há cerca de 9 meses vem\napresentando dor e edema em articulações das\nmãos, punhos, joelhos, tornozelos e pés, com piora\nprogressiva. Apresenta ainda discreta adinamia e sensação de febre. Ao exame clínico, os dados\nrelevantes são: artrite de metacarpo nas falangeanas, interfalangeanas proximais, joelhos e\ntornozelos. Os exames laboratoriais mostraram FAN não reagente, fator reumatoide reagente =\n512, VHS = 50 e PCR = 24. Sobre o caso, assinale a afirmativa CORRETA:","options":{"A":"O diagnóstico é de AR definida, a doença está ativa e apenas com os dados informados não é\npossível calcular o DAS 28 (Disease Activity Score).","B":"Estão presentes critérios diagnósticos suficientes para concluir o diagnóstico de artrite\nreumatoide (AR) e o tratamento inicial deve incluir o uso de um imunobiológico.","C":"Não estão presentes critérios diagnósticos suficientes para concluir o diagnóstico de artrite\nreumatoide (AR), e o tratamento inicial deve incluir o uso de um imunobiológico.","D":"O diagnóstico é de AR provável, a doença está ativa e o tratamento deve excluir, por enquanto,\no uso de metotrexato."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-156429","number":"156429","sourceNumber":"156429","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Com relação à artrite crônica juvenil, marque a alternativa que apresenta a\nmanifestação extra-articular mais frequente:","options":{"A":"Febre intermitente.","B":"Pleurite.","C":"Linfoadenomegalias.","D":"Uveíte anterior."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-156447","number":"156447","sourceNumber":"156447","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menina de 6 anos de idade com diagnóstico de artrite reumatóide juvenil, evolui com\niridociclite de difícil controle e cegueira. Dentre as formas clínicas da doença, marque a mais\nrelacionada com a evolução descrita:","options":{"A":"Poliartrite com FAN positivo e Fator Reumatoide negativo.","B":"Oligoartrite tipo I.","C":"Oligoartrite tipo II.","D":"Poliartrite com FAN negativo e fator reumatoide positivo."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-156487","number":"156487","sourceNumber":"156487","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menino de 8 anos procura seu consultório com quadro de febre alta intermitente que\nvem ocorrendo há meses, mas não passam\ngeralmente de 72 horas. Quando a febre melhora, a\ncriança age normalmente sem qualquer sintoma. Segundo a mãe, de origem turca como o pai, tudo\ncomeça com uma dor abdominal intensa que foi sugerida a hipótese de apendicite mas descartada\npelo cirurgião pediátrico. Já realizou diversos exames de imagens e laboratoriais, todos normais.\n\nApenas um FAN positivo, mas muito baixo e inespecífico. Qual a possível hipótese diagnóstica?","options":{"A":"Artrite crônica juvenil ainda sem manifestações articulares.","B":"Síndrome de Reiter.","C":"Lúpus sistêmico.","D":"Febre Familiar do Mediterrâneo."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-156490","number":"156490","sourceNumber":"156490","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menino de 8 anos procura seu consultório com quadro de febre alta intermitente que\nvem ocorrendo há meses, mas não passam de\ngeralmente de 72 horas. Quando a febre melhora, a\ncriança age normalmente sem qualquer sintoma. Segundo a mãe, de origem turca como o pai, tudo\ncomeça com uma dor abdominal intensa que foi sugerida a hipótese de apendicite mas descartada\npelo cirurgião pediátrico. Já realizou diversos exames de imagens e laboratoriais, todos normais.\n\nApenas um FAN positivo, mas muito baixo e inespecífico. Fechando o diagnóstico da questão\nanterior, qual o melhor tratamento?","options":{"A":"Prednisona.","B":"AAS.","C":"Colchicina.","D":"Ciclofosfamida."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-156500","number":"156500","sourceNumber":"156500","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 50 anos acorda com dor intensa em região do hálux direito, acompanhada\nde calor local, vermelhidão e edema. Chega ao\npronto-socorro sem conseguir deambular. Refere\nuso anterior de AINEs (anti-inflamatórios não-esteróides) e de analgésicos em virtude de crises\nsemelhantes, incluindo outras articulações. O ácido úrico era de 11mg%, o hemograma estava\nnormal e a creatinina era de 0,9mg/dL. Nesse caso, a primeira hipótese clínica e a abordagem\nterapêutica adequada são, respectivamente:","options":{"A":"Crise aguda de gota ? iniciar AINE e colchicina","B":"Gota com infecção secundária ? iniciar antibiótico, AINE e colchicina","C":"Crise aguda de gota ? iniciar AINE e alopurinol","D":"Gota com infecção secundária ? iniciar antibiótico, alopurinol e AINE"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-137018","number":"137018","sourceNumber":"137018","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente do sexo feminino, 32 anos, procurou ambulatório referindo que há cerca de 1\nano vem apresentando dor e edema nas\narticulações das mãos, punhos, tornozelos e pés, com\npiora progressiva. Apresenta discreto envolvimento sistêmico e rigidez matinal de duas horas. Ao\nexame clínico, os dados relevantes são: Poliartrite simétrica, nódulo subcutâneo em superfície\nextensora de antebraços e vermelhidão ocular. Os exames laboratoriais mostram FAN (+)\n1/640 Padrão Nuclear Pontilhado Fino, Fator Reumatoide (+) = 512, Antipeptídeo Citrulinado\nCíclico (Anti-CCP) reagente, VHS = 50 e PCR = 24. Sobre o caso, assinale a assertiva\nINCORRETA.","options":{"A":"Diagnóstico é AR e a vermelhidão ocular, por si só, não define a presença de Síndrome de\nSjogren.","B":"Diagnóstico é AR provável, associada à provável LES, pois o FAN se encontra reagente.","C":"Diagnóstico é AR definida, a doença está ativa e o tratamento deve incluir Metotrexato na dose\nde 15 a 25 mg/semana, por período mínimo de\ntrês meses.","D":"Diagnóstico é AR definida, a doença está ativa e apresenta indicadores de pior prognóstico."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-136742","number":"136742","sourceNumber":"136742","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A artrite reumatóide é uma doença crônica inflamatória sistêmica cuja maior\nmanifestação é a sinovite de múltiplas\narticulações. Acomete mais comumente as mulhetes em\numa freqüência de 3:1 em relação aos homens. Correlacione a coluna da esquerda com os seus\nrespectivos sinais e sintomas da coluna da direita: Coluna da esquerda: (1) nódulos subcutâneos;\n\n(2) síndrome de Sjögren; (3) síndrome de Felty (4) doença articular ativa. Coluna da direita: (a)\nesplenomegalia e neutropenia; (b) bainha tendinosa; (c) eritema palmar; (d) boca e olhos secos.","options":{"A":"1b, 2d, 3a, 4c","B":"1c, 2a, 3d, 4b","C":"1b, 2a, 3d, 4c","D":"1a, 2c, 3d, 4b"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-75386","number":"75386","sourceNumber":"75386","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A sacroileíte e o envolvimento da coluna vertebral, com soldadura dos corpos vertebrais\ne presença de sindesmófitos, produzindo um\naspecto de ?coluna em bambu? e ?postura de\nesquiador?, são sugestivos de:","options":{"A":"Espondilite anquilosante.","B":"Síndrome de Reiter.","C":"Artrite Psoriática.","D":"Artrite reumatoide juvenil."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-243771","number":"243771","sourceNumber":"243771","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"No que diz respeito às cardites por febre reumática, é correto afirmar que:","options":{"A":"o acometimento isolado da válvula aórtica é o achado mais comum","B":"apesar de ser a complicação mais grave, raramente acomete indivíduos com febre reumática","C":"normalmente manifesta-se como uma pancardite, acometendo pericárdio, miocárdio e\nendocárdio","D":"pelos critérios de Jones, a cardite é considerada uma manifestação menor para fins diagnósticos"},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-220231","number":"220231","sourceNumber":"220231","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem, 25 anos, queixa-se de dor articular em joelho direito, além de articulação\nmetatarsofalangena do hállux esquerdo, sem história de trauma, de início há 5 semanas. Afirma ser\npreviamente hígido e relata apenas um quadro de disúria com melhora espontânea há algumas\nsemanas. Ao exame, discreta hiperemia ocular, sinais inflamatórios nas articulações acometidas,\nsem presença de deformidades. A principal hipótese diagnóstica e exame a ser solicitado para esse\ncaso seria:","options":{"A":"artrite reumatoide, fator reumatóide.","B":"artrite reacional, análise do líquido sinovial.","C":"artrite séptica, punção articular.","D":"osteoartrose, radiografia."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-220241","number":"220241","sourceNumber":"220241","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem, 72 anos, obesidade grau 2, com queixa de dor lombar há 3 anos, progressiva,\nsem história de trauma. Dor com piora após\nmovimentação e certo alívio ao repouso. Piora do\nquadro nos últimos 2 meses, com persistência da dor ao repouso e sem melhora com uso diário de\nanalgésicos e anti-inflamatórios não esteroidais. Ao exame: dor a palpação lombar baixa,\nmobilidade lombo-sacra preservada, encurtamento dos músculos isquiotibiais, limitação importante\nda rotação interna e abdução do quadril esquerdo, manobra de Thomas (+), manobra de Yeoman\n\n(-), manobra de Laségue (-). A suspeita diagnóstica e exame adequado são:","options":{"A":"hérnia de disco, ressonância nuclear magnética.","B":"hérnia de disco, radiografia de coluna lombar.","C":"osteoartrose de quadril, ressonância nuclear magnética.","D":"osteoartrose de quadril, radiografia da bacia."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-216844","number":"216844","sourceNumber":"216844","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente do sexo feminino, 44 anos, refere quadro de rigidez matinal de 1 hora em\nmãos, associada à artralgia, edema e hiperemia em\narticulações interfalangianas proximais,\nmetacarpofalangianas e punho, bilateralmente, nas últimas 8 semanas. Passou por avaliação\nmédica, sendo realizada a hipótese diagnóstica de artrite reumatoide. Quanto ao diagnóstico dessa\ndoença, assinale a alternativa CORRETA:","options":{"A":"Para o diagnóstico, a duração dos sintomas deve ser superior a 12 semanas.","B":"A presença do fator reumatoide positivo é necessária e suficiente para o diagnóstico.","C":"O anticorpo anti-CCP (antipeptídeos citrulinados cíclicos) pode ser usado como indicador de\nprogressão e prognóstico da doença.","D":"A presença de VHS e PCR positivos são critérios menores, enquanto a presença de nódulos\nsubcutâneos e eritema marginado são critérios maiores para o diagnóstico."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-216893","number":"216893","sourceNumber":"216893","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A febre reumática é:","options":{"A":"Uma doença que ocorre em crianças com predisposição genética após uma infecção de\npele causada pelo estreptococo e não tratada adequadamente.","B":"Diagnosticada através do preenchimento dos critérios de Jones, que incluem poliartrite\nmigratória, cardite, crise convulsiva e eritema marginado.","C":"Caracterizada laboratorialmente pela presença de aumento de provas inflamatórias e níveis\nelevados de ASLO (anticorpo antiestreptolisina).","D":"Tratada com profilaxia secundária com penicilina benzatina a cada 21 dias quando ocorre artrite\ne a cada 15 dias se ocorrer cardite."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-151643","number":"151643","sourceNumber":"151643","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em relação à osteoartrose de joelhos, assinale a alternativa CORRETA:","options":{"A":"Fortalecimento muscular associado a alongamento são medidas que devem ser implantadas\ndesde o início do diagnóstico.","B":"Nos períodos de piora de dor articular devemos orientar repouso total da articulação acometida.","C":"O uso de anti-inflamatórios não esteroidais em altas doses em curtos períodos de tempo podem\nlevar à melhora prolongada destes pacientes.","D":"O uso de antiartrósicos como a diacereína associado a analgésicos simples como paracetamol\nnão costuma trazer benefícios em relação à dor\ndestes pacientes."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-151077","number":"151077","sourceNumber":"151077","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em relação à Artrite Idiopática Juvenil, assinale a INCORRETA:","options":{"A":"Caracteriza-se pela presença de artrite persistente em uma ou mais articulações por um tempo\nmínimo de seis semanas.","B":"No tipo oligoarticular há ocorrência de artrite em uma a quatro articulações, sendo os joelhos e\nos tornozelos as mais comprometidas.","C":"No tipo sistêmico há febre intermitente, geralmente vespertina, com duração mínima de 15 dias.","D":"Os exames laboratoriais estão sempre alterados, sendo que o fator reumatóide está presente\nem mais de 40% dos pacientes com subtipo\npoliarticular."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-151041","number":"151041","sourceNumber":"151041","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A osteoartose é a causa de dor crônica mais comum no idoso. Predomina no sexo\nfeminino e pode afetar praticamente todas as articulações do corpo. Quais as articulações mais\nafetadas por esta doença?","options":{"A":"Joelhos, mãos e vértebras.","B":"Joelho, ombro e cotovelo.","C":"Ombro, mãos e vértebras.","D":"Artelhos, mãos e vértebras."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-130105","number":"130105","sourceNumber":"130105","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma paciente procurou seu clínico geral com queixas de artralgias há dois meses. Ela\nestá preocupada, pois seu pai é portador de um quadro grave de psoríase e ela teme estar\ndesenvolvendo um quadro de artrite psoriásica. Após exame dermatológico cuidadoso, o médico\nnão identificou qualquer lesão em pele característica de psoríase. Os achados abaixo podem ser\nsugestivos de artrite psoriásica, mesmo na ausência de lesões dermatológicas, EXCETO:","options":{"A":"Oligoartrite assimétrica com envolvimento das interfalangianas distais.","B":"Dactilite e espondilite.","C":"Fator reumatoide e anti-CCP positivos.","D":"Presença de lesões ungueais com pitting, onicólise, manchas salmão, hemorragias e\nhiperqueratose subungueal."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-132224","number":"132224","sourceNumber":"132224","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menina de 5 anos, apresenta edema em joelho direito e tornozelo esquerdo há 12\nmeses, queixa-se de dor esporádica e leve, afebril, com bom ganho de peso. Não há outras\nmanifestações sistêmicas. Fator reumatoide negativo, anticorpo antiestreptolisina O negativo e\nanticorpos antinucleares negativos. Agora, nota-se assimetria no tamanho das pernas, que não\nhavia antes da artrite. Previamente hígida, nega faringoamidalites. Familiares de primeiro e\nsegundo grau negam doenças. Sobre este caso, assinale a alternativa correta:","options":{"A":"Preenche critérios de Jones para diagnóstico de febre reumática.","B":"A história clínica é característica do lúpus eritematoso discoide.","C":"É compatível com artrite idiopática juvenil, forma oligoarticular.","D":"Preenche critérios de Roma para suspeita de espondiloartropatia."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-107541","number":"107541","sourceNumber":"107541","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente com artrite reumatoide com DAS 28 = 5,33, apesar do uso de terapêutica\notimizada com DMARDs sintéticos. Você opta por\niniciar terapêutica biológica com anti-TNF para\ncontrole da doença. Quais exames são mais importantes solicitar antes de iniciar a medicação?","options":{"A":"Fator reumatoide, RX de mãos, urina I e enzimas canaliculares.","B":"Transaminases, hemograma, sorologia para citomegalovírus e toxoplasmose.","C":"Hemograma, transaminases, RX de tórax e PPD.","D":"Parasitológico de fezes, creatinina, transaminases e hemograma.","E":"Anti-CCP, fator reumatoide e Waaler-Rose."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-107549","number":"107549","sourceNumber":"107549","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente com artrite reumatoide em uso de metotrexato 25 miligramas/semana,\nprednisona 10 miligramas/dia, leflunomida 20\nmiligramas/dia, hidroxicloroquina 400 miligramas/dia\ne nimesulida 100 mg 12/12h apresentando quadro de sinovite em punhos, cotovelos e joelhos,\nalém de PCR 12 e VHS 58. Qual a melhor opção terapêutica para controle da doença?","options":{"A":"Aumentar a dose da prednisona.","B":"Aumentar a dose de metotrexato.","C":"Associar sulfassalazina.","D":"Iniciar anti-TNF.","E":"Iniciar anti-CD20."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-111799","number":"111799","sourceNumber":"111799","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 32 anos apresenta-se em consulta ambulatorial com artrite simétrica das\ninterfalagianas proximais, rigidez articular matinal maior que uma hora e positividade para o\nanticorpo anti- CCP. Na consulta ela pergunta sobre o possível acometimento da coluna vertebral, o\nqual, nessa doença, costuma ser mais frequente na coluna:","options":{"A":"Sacra.","B":"Dorsal.","C":"Lombar.","D":"Cervical.","E":"Lombar e dorsal."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-107573","number":"107573","sourceNumber":"107573","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente, 72 anos, com queixa de dor em IFP e IFD das mãos, tendo sido encaminhada\npela unidade básica de saúde para avaliação no\nambulatório de reumatologia. Trouxe exames\nsolicitados anteriormente, entre os quais: (VER IMAGEM) Tendo essas informações, qual a\nprincipal hipótese diagnóstica?","options":{"A":"Febre reumática, visto ASLO aumentado.","B":"Lúpus eritematoso sistêmico, visto FAN 1/80 nuclear pontilhado fino.","C":"Artrite reumatoide, visto dor em mãos e fator reumatoide positivo.","D":"Osteoartrite de mãos, visto quadro clínico e perfil epidemiológico da paciente.","E":"Sobreposição de lúpus eritematoso sistêmico e artrite reumatoide."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-111808","number":"111808","sourceNumber":"111808","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A prova tuberculínica deve ser sempre realizada em pacientes com Artrite Reumatoide\nque vão iniciar terapia com:","options":{"A":"Cloroquina;","B":"Corticosteróides;","C":"Metotrexate;","D":"Antagonistas do TNF-alfa;","E":"Ciclosporina."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-107595","number":"107595","sourceNumber":"107595","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente, 19 anos, com quadro de poliartralgia e polimialgia há 2 anos, refere sono não\nrestaurador associado ao quadro clínico. Nega sinais de artrite. Nega febre. Ao exame físico, não\napresenta sinais de artrite e o exame físico sistêmico está inalterado. Com base nessas\ninformações, escolha a alternativa CORRETA:","options":{"A":"O diagnóstico é fibromialgia, não é necessário realização de exames complementares e deve-se\niniciar o tratamento com antidepressivos, sendo a sertralina a primeira escolha.","B":"A principal hipótese diagnóstica é fibromialgia e deve-se solicitar hemograma, TSH, provas de\natividade inflamatória para avaliação inicial do caso e exclusão de diagnósticos diferenciais.","C":"O exame de FAN é fundamental para análise diagnóstica e sua positividade confirma o\ndiagnóstico de LES.","D":"O encontro de resultado de TSH alterado não tem relação causal com o quadro clínico.","E":"Deve-se solicitar avaliação da ortopedia, visto a queixa de dor articular."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-83450","number":"83450","sourceNumber":"83450","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente, 65 anos, masculino, com quadro de lombalgia há 2 meses, com piora à\nmovimentação. Refere que há 45 dias iniciou paraparesia e há 2 dias está com incapacidade de\nmovimentação de membros inferiores. Você está de plantão no pronto-socorro e faz o primeiro\natendimento do paciente. Escolha a conduta CORRETA:","options":{"A":"Trata-se de lombalgia crônica com sinais de gravidade. Deve-se internar o paciente e solicitar o\nTC de coluna lombar e torácica para\navaliação de compressão\n\nmedular.","B":"Deve-se solicitar TC de coluna lombar e, se normal, iniciar tratamento domiciliar com analgesia.","C":"Trata-se de lombociatalgia e deve-se realizar tratamento com AINE e fisioterapia.","D":"Deve-se considerar a hipótese diagnóstica de espondilite anquilosante, visto tratar-se de\nhomem com lombalgia crônica.","E":"Não é necessário realização de exames complementares, visto tratar-se de lombalgia aguda\ncuja principal etiologia é de origem mecânica."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-62390","number":"62390","sourceNumber":"62390","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"São parâmetros de mau prognóstico na Artrite Reumatoide, exceto:","options":{"A":"Comprometimento extra-articular como vasculite e episclerite/esclerite.","B":"Início da doença em idade mais precoce.","C":"Altos títulos de Fator Reumatoide.","D":"Presença de erosões após os 3 primeiros anos da doença (raio X de mãos e pés).","E":"VHS e/ou proteína C reativa elevada persistentemente."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-64957","number":"64957","sourceNumber":"64957","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente feminino, 35 anos, com queixa de dor e edema em articulações\ninterfalangeanas proximais e metacarpofalangeanas\ndas mãos bilateralmente há oito meses\nassociado à rigidez matinal de duas horas. Apresenta aos exames fator reumatoide positivo em\naltos títulos, VHS de 50 mm da primeira hora e RX de mãos com cistos e erosões em articulações\nde metacarpofalangeanas. Qual é a principal hipótese diagnóstica e o principal medicamento a ser\nprescrito para controle clínico da doença, respectivamente?","options":{"A":"Artrite Reumatoide e metotrexate.","B":"Artrite Reumatoide e AINE (Anti-Inflamatório Não Esteroidal).","C":"Lúpus Eritematoso Sistêmico e hidroxicloroquina.","D":"Artrite Reumatoide e prednisona em altas doses (1 mg/kg/dia).","E":"Lúpus Eritematoso Sistêmico e prednisona em doses anti-inflamatória (0,5 mg/kg/dia)."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-31881","number":"31881","sourceNumber":"31881","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Assinale a alternativa correta.","options":{"A":"A dactilite ou \"dedo em salsicha\" é uma manifestação clínica observada na artrite psoriásica e na\nartrite reativa.","B":"A nefropatia por IGA e a insuficiência aórtica são exemplos de manifestações extra-articulares\nda espondilite anquilosante.","C":"Artrite reativa refere-se a uma atrite inflamatória secundária a uma infecção, na qual não se\nconsegue cultivar o microrganismo causal a\npartir do líquido sinovial.","D":"No tratamento da espondilite anquilosante, os anti-inflamatórios não hormonais (AINES) devem\nser evitados, e, quando utilizados, não devem\nser administrados de forma contínua, pelo risco de\nlesão gástrica e/ou renal.","E":"Devido ao risco de ulceração e sangramento intestinal deve-se evitar o uso de AINES em\npacientes portadores de enteroartropatia, sendo os corticosteroides a droga de escolha."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-34547","number":"34547","sourceNumber":"34547","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"As seguintes patologias frequentemente cursam com quadro de poliartrite, EXCETO:","options":{"A":"Lúpus eritematoso sistêmico.","B":"Artrite reumatoide","C":"Febre reumática.","D":"Artrite reativa.","E":"Síndrome de Sjögren."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-31908","number":"31908","sourceNumber":"31908","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"É característico das espondiloartrites, EXCETO:","options":{"A":"Entesites.","B":"Artrite periférica assimétrica.","C":"Osteófitos.","D":"Uveíte.","E":"Dor lombar inflamatória."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-31904","number":"31904","sourceNumber":"31904","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Pré-escolar do sexo feminino, de 2 anos de idade, vem ao ambulatório com história de\n9 semanas de aumento de volume em joelhos,\npunho direito e tornozelo esquerdo. Ao exame\nfísico, apresenta artrite nas articulações referidas. O hemograma, bioquímica e urina I foram\nnormais, com exceção da VHS (50), ASLO (400 U Todd) e FAN (1/160 com padrão homogêneo).\nQual o diagnóstico?","options":{"A":"Lúpus eritematoso sistêmico.","B":"Artrite reumatoide juvenil forma poliarticular.","C":"Febre reumática.","D":"Artrite reumatoide juvenil forma pauciarticular.","E":"Artrite reacional."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-330488","number":"330488","sourceNumber":"330488","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A fibromialgia é um diagnóstico frequente na atenção primária. A dor\nmusculoesquelética difusa e crônica é a principal\nqueixa relacionada. Sobre esta condição é\nERRADO afirmar:","options":{"A":"Além da dor, pode-se citar fadiga, alteração do sono, rigidez matinal, parestesias, sensação\nsubjetiva de edema e distúrbios cognitivos como sintomas relacionados","B":"Amitriptilina e ciclobenzaprina reduzem a dor, embora não sejam capazes de melhorar a\ncapacidade funcional dos pacientes","C":"Está comumente associada a outras comorbidades, dentre elas depressão e ansiedade,\nsíndrome da fadiga crônica e síndrome do cólon irritável","D":"Os pacientes devem ser incentivados a realizarem exercícios físicos pelo menos duas vezes por\nsemana"},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-301217","number":"301217","sourceNumber":"301217","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 47 anos queixa-se de dores no dorso, membros superiores e inferiores, baixa\nenergia e insônia há um ano. Nega febre, emagrecimento ou sudorese noturna. Descreve episódios\nparoxísticos de mudança de cor nas pontas dos dedos das mãos por alguns minutos, que se\ntornam pálidos e, em seguida, azulados, quando expostos ao frio. É portadora de transtorno\ndepressivo e faz uso de fluoxetina. O exame físico não apresenta anormalidades. Exames de\nlaboratório: Hb 13,4g/dL; Leucócitos totais: 7.840/mm³; Plaquetas 198.000/mm³; Proteína C reativa\n3mg/dL; TSH 1,4UI/mL; cálcio iônico 1,23mmol/L; anti-HIV Não Reagente; HBsAg Não Reagente,\nanti-HCV Não Reagente; FAN reagente até titulo 1:320 com padrão nuclear pontilhado fino denso.\nConsiderando a hipótese diagnóstica mais provável para essa paciente, assinale a alternativa que\napresenta uma opção terapêutica MAIS ADEQUADA.","options":{"A":"Amitriptilina","B":"Azatioprina","C":"Codeína","D":"Prednisona"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-255909","number":"255909","sourceNumber":"255909","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 53 anos queixa-se de dispneia ao andar um quarteirão no plano há cerca de\n1 ano. Não percebeu piora recente e nega\ndor torácica, tosse ou ortopneia. Relata dor e edema nas\narticulações das mãos, punhos e joelhos há 3 meses, associada à dificuldade de movimentação\ndessas articulações por 4 horas após despertar pela manhã e que melhora com a persistência das\natividades usuais. Não possui doenças conhecidas e não faz uso regular de medicamentos. O\nexame físico apresenta PA 130/66 mmHg, FC 65 bpm, FR 16 ipm, SpO2 em ar ambiente 93%. O\nexame respiratório não apresenta anormalidades. O exame cardiovascular revela movimento da\nregião paraesternal inferior esquerda; ritmo cardíaco regular, desdobramento contínuo e variável da\nsegunda bulha, hiperfonese de P2 e sopro holossistólico na borda paraesternal inferior esquerda,\nmais intenso à inspiração. Apresenta dor à palpação, redução da amplitude de movimento e\naumento de volume das articulações metacarpofalangeanas, interfalangeanas proximais, punhos e\njoelhos. Sem outras anormalidades. Exames de laboratório: Hb 10,1 g/dl; LG 5.540/mm³; Plq\n532.000/mm³; PCR 27 mg/L; FR 2 UI/ml; anti-CCP 34 UI/ml; Creat 1,0 mg/dl. Assinale a alternativa\nque apresenta o tratamento relacionado à redução da progressão da doença articular e controle\ndos sintomas articulares nessa paciente.","options":{"A":"Anti-inflamatório não esteroidal.","B":"Colchicina.","C":"Metotrexato.","D":"Prednisona."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-255917","number":"255917","sourceNumber":"255917","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 53 anos queixa-se de piora da dispneia basal, de forma progressiva nos\núltimos cinco dias, presente até ao tomar\nbanho e se vestir. Relata diversos despertares noturnos\npor dispneia, que é mais intensa em decúbito, e episódios paroxísticos e recorrentes de palpitação.\nÉ portador de insuficiência cardíaca, doença de Chagas, diabetes melito e gota. Faz uso regular de\nlosartana, espironolactona, furosemida, carvedilol e insulina NPH. Em consulta realizada há 8 dias,\nfoi prescrito o aumento da dose de carvedilol de 6,25 mg para 12,5 mg de 12/12h. Ao exame físico,\napresenta PA = 120/70 mmHg; FC = 68 bpm; FR = 23 ipm; SpO2 em ar ambiente de 93%; TAx =\n36,4°C. O paciente encontra-se alerta e orientado. As extremidades estão aquecidas e o\nenchimento capilar é imediato. O exame respiratório revela crepitações teleinspiratórias nas\nmetades basais do hemitórax. O exame cardiovascular revela pulso venoso na veia jugular interna\ndireita no nível do ângulo da mandíbula e refluxo hepatojugular presente; o ritmo cardíaco é\nregular,\no ictus está desviado inferiormente e para a esquerda, e é amplo. O fígado é palpado 5 cm abaixo\ndo rebordo costal direito e apresenta-se levemente doloroso à palpação. Não há edemas nos\nmembros inferiores. O paciente queixa-se de dor na 1ª articulação metatarsofalangeana direita. O\nexame físico revela edema, calor e eritema nessa articulação, com limitação da amplitude do\nmovimento, que é muito doloroso. O restante do exame do aparelho locomotor não apresenta\nanormalidades. Assinale a alternativa, dentre as seguintes, que apresenta o tratamento MAIS\nADEQUADO para a fase aguda da artrite apresentada por esse paciente.","options":{"A":"Alopurinol.","B":"Colchicina.","C":"Naproxeno.","D":"Prednisona."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-203252","number":"203252","sourceNumber":"203252","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um homem de 42 anos comparece ao pronto-socorro queixando-se de dor intensa no\njoelho esquerdo e febre há 12 horas. Ele é portador de doença renal crônica (clearance de\ncreatinina de 17 ml/kg/1,73 m²) e diabetes melito mal controlado. Ao exame clínico, está alerta,\norientado, corado e hidratado. PA = 130 x 70 mmHg; FR = 17 irpm; FC = 106 bpm; SpO? = 98%;\nTAx = 38,2°C. Há dor e limitação da amplitude do movimento do joelho esquerdo, além de derrame\narticular, calor e vermelhidão. Exames laboratoriais: hemoglobina = 13,5 g/dl; leucócitos =\n15.100/mm³; neutrófilos = 11.600/mm³; proteína C-reativa = 140 mg/L. Análise do líquido sinovial:\nleucócitos = 13.400/mm³; neutrófilos = 95%; presença de cristais de monourato de sódio, ausência\nde bactérias coráveis ao Gram e cultura para bactérias negativa. Assinale a alternativa CORRETA\nsobre esse caso.","options":{"A":"A colchicina pode ser utilizada no tratamento da dor e dos sinais flogísticos.","B":"A prescrição inicial deve incluir anti-inflamatório não esteroidal e alopurinol como agente\nredutor\nde ácido úrico.","C":"O paciente apresenta artrite séptica e deve ser iniciado o tratamento com ceftriaxona\nintravenosa.","D":"O principal agente etiológico é a Neisseria gonorrhoeae."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-139665","number":"139665","sourceNumber":"139665","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente de 69 anos, diabética e portadora de artrite reumatóide de longa data, motivo\npelo qual apresenta deformidades articulares principalmente nas mãos, punhos e pés.\n\nDesenvolveu, abruptamente, febre associada a dor, calor, eritema, aumento de volume e restrição\nde movimentos no joelho esquerdo. Considerando-se\ncaso apresentado, assinale a alternativa\nCORRETA:","options":{"A":"Artrite traumática deve ser considerada dentre as principais hipóteses diagnósticas já que nestes\ncasos geralmente não há história de trauma\nprévio.","B":"Deve-se iniciar colchicina e anti-inflamatório não esteroide imediatamente para interromper a\nprogressão do quadro e reverter as manifestações clínicas.","C":"O diagnóstico mais provável é artrite séptica e deve-se colher amostra de liquido sinovial para\nconfirmação diagnóstica.","D":"Trata-se provavelmente de exarcebação da artrite reumatóide e deve-se prescrever prednisona\n40mg/dia"},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-127501","number":"127501","sourceNumber":"127501","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 42 anos, previamente assintomático, apresenta-se com dor em articulação\nmetatarsofalangiana à E de início súbito, noturna, de forte intensidade e após libação etílica\n(cerveja). Ao exame físico, está afebril e observam-se sinais evidentes de artrite na referida\narticulação. Entre as afirmativas abaixo relacionadas, assinale a ERRADA:","options":{"A":"O diagnóstico de certeza é confirmado a partir do achado de cristais de urato no líquido\narticular.","B":"Formação de cálculos renais de ácido úrico e insuficiência renal crônica são complicações em\nlongo prazo.","C":"Nível sérico de ácido úrico dentro dos valores de referência não é compatível com este caso\nclínico.","D":"Obtém-se resposta clínica dramática com o uso de anti-inflamatórios não esteroides."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-141260","number":"141260","sourceNumber":"141260","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 30 anos com história recente de diarreia invasiva, caracterizada pela\npresença de sangue nas fezes e febre, evolui\ncom oligoartrite periférica e entesite falangeana. Qual\né o diagnóstico MAIS PROVÁVEL?","options":{"A":"Artrite reativa","B":"Artrite séptica","C":"Doença de Crohn","D":"Síndrome de Behçet"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-141263","number":"141263","sourceNumber":"141263","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"As articulações afetadas com MAIS FREQUÊNCIA na artrite reumatoide são as:","options":{"A":"Interfalagianas distais","B":"Interfalangianas proximais","C":"Lombossacras","D":"Sacroilíacas"},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-112069","number":"112069","sourceNumber":"112069","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em relação aos efeitos colaterais relacionados às drogas modificadoras da doença na\nartrite reumatoide, assinale a alternativa ERRADA:","options":{"A":"Diarreia, \"rash\" e alopecia estão associados ao uso da leflunomida","B":"Durante o uso da sulfasalazina, atenção deve ser dada quanto ao risco de trombocitopenia e\nneutropenia","C":"Irritação gástrica e estomatite estão mais comumente associados ao metotrexate","D":"Hidroxicloroquina, por ser bem tolerada, não exige cuidados especiais"},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-78364","number":"78364","sourceNumber":"78364","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 55 anos, com diagnóstico de artrite reumatoide de longa data, queixa-se de\ndor cervical e torcicolo de repetição. Ao exame físico, evidencia-se dor e crepitação à flexão e\nextensão da cabeça. Qual o diagnóstico MAIS PROVÁVEL?","options":{"A":"Estenose do canal medular.","B":"Hérnia de disco entre C5 e C6.","C":"Instabilidade de C1-C2.","D":"Osteoporose."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-71472","number":"71472","sourceNumber":"71472","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 27 anos comparece à consulta para avaliação de dor lombar persistente\nassociada à rigidez, que surgiram\ninsidiosamente há três anos. Os sintomas pioram com repouso\nprolongado. Tem história de episódio de inflamação aguda no olho esquerdo, que foi tratada por\noftalmologista. Ao exame, trata-se de homem negro com hipersensibilidade à palpação das\narticulações sacroilíacas e teste de Schober normal. Qual dos seguintes procedimentos poderia\nconfirmar o diagnóstico?","options":{"A":"Dosagem sérica do fator reumatoide.","B":"Pesquisa de HLA-B27.","C":"Radiografia das articulações sacroilíacas.","D":"Dosagem sérica do ácido úrico."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-71483","number":"71483","sourceNumber":"71483","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 75 anos, com história de hipertensão arterial e de hiperuricemia, deu\nentrada no pronto atendimento com artrite de\njoelho esquerdo de 48 horas de evolução. Ao exame,\nencontrava-se levemente prostrado, com temperatura axilar de 37,8ºC e hemodinamicamente\nestável. Dentre as opções abaixo, qual é a conduta MAIS adequada?","options":{"A":"Solicitar hemograma e dosagem sérica de ácido úrico com o objetivo de avaliar a necessidade\nde artrocentese.","B":"Prescrever colchicina e anti-inflamatório não esteroide.","C":"Artrocentese e análise do líquido sinovial.","D":"Prescrever 10 mg de prednisona."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-53321","number":"53321","sourceNumber":"53321","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 27 anos comparece à consulta para avaliação de dor lombar persistente,\nassociada à rigidez, que surgiu insidiosamente há três anos. Os sintomas pioram com repouso\nprolongado. Tem história de episódio de inflamação aguda no olho esquerdo, que foi tratada por\noftalmologista. Ao exame, trata-se de homem negro com hipersensibilidade à palpação das\narticulações sacroilíacas e teste de Schober normal. Qual dos seguintes procedimentos poderia\nconfirmar o diagnóstico?","options":{"A":"Dosagem sérica do fator reumatoide","B":"Pesquisa de HLA-B27","C":"Radiografia das articulações sacroilíacas","D":"Dosagem sérica do ácido úrico"},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-346217","number":"346217","sourceNumber":"346217","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"C.M.A, 13 anos, sexo feminino, procurou atendimento no PSF após admissão\nhospitalar na qual, segundo a paciente,\napresentou diagnóstico de febre reumática. Critérios de\nJones foram criados para realizar o diagnóstico dessa patologia. De acordo com esses critérios, a\npaciente deve possuir faringoamigdalite documentada ou ASLO em ascensão, além de\nmanifestações que podem ser classificadas como critério menor ou maior. Das manifestações\ndescritas abaixo, qual a considerada um critério menor?","options":{"A":"Cardite.","B":"Nódulo subcutâneo.","C":"Cefaleia.","D":"Poliartrite migratória.","E":"Febre."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-301022","number":"301022","sourceNumber":"301022","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Analise os seguintes procedimentos. I. Pesquisa de cristais; II. Citologia / citometria;\nIII.\nCultura; IV. LDH, proteínas totais e frações e glicose; V. PH. Em pacientes adultos com monoartrite\naguda, após a punção e coleta de líquido sinovial, deve-se obrigatoriamente solicitar","options":{"A":"I e III, apenas.","B":"I, II e III, apenas.","C":"II, III e IV, apenas.","D":"I, II, IV e V."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-287612","number":"287612","sourceNumber":"287612","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"As terapias sintomáticas dos pacientes com Artrite Psoriaca (AP) incluem\nmedicamentos:","options":{"A":"anti-inflamatórios não-esteroides, glicocorticoides sistêmicos e nunca injeções locais de\nglicocorticoide.","B":"anti-inflamatórios não-esteroides, glicocorticoides sistêmicos e injeções locais de\nglicocorticoide.","C":"anti-inflamatórios não-esteroides, nunca glicocorticoides sistêmicos e sim injeções locais de\nglicocorticoide.","D":"Não estão indicados os anti-inflamatórios não-esteroides, e sim glicocorticoides sistêmicos e\ninjeções locais de glicocorticoide."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-287617","number":"287617","sourceNumber":"287617","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Para oferecer uma melhor qualidade de vida e evitando a perda da capacidade\nfuncional dos pacientes com Artrite Psoriaca (AP), pode-se afirmar que:","options":{"A":"O tratamento da Artrite Psoriaca (AP) não objetiva a redução dos sintomas, e sim a remissão ou\no controle da atividade da\n\ndoença com mínima ou baixa atividade.","B":"O tratamento da Artrite Psoriaca (AP) objetiva a redução dos sintomas, a remissão sem o\ncontrole da atividade da doença com\n\nmínima ou baixa atividade.","C":"O tratamento da Artrite Psoriaca (AP) objetiva a manutenção dos sintomas, a remissão ou o\ncontrole da atividade da doença com\n\nmínima ou baixa atividade.","D":"O tratamento da Artrite Psoriaca (AP) objetiva a redução dos sintomas, a remissão ou o controle\nda atividade da doença com\n\nmínima ou baixa atividade."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-260539","number":"260539","sourceNumber":"260539","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A manifestação extra-articular mais comum de espondilite anquilosante é:","options":{"A":"Uveíte anterior.","B":"Estenose aórtica.","C":"Amiloidose.","D":"Fibrose pulmonar."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-260540","number":"260540","sourceNumber":"260540","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Renato de 30 anos, procedente de Paraguaçu, procura a Santa Casa com relato de há\n1 semana ter iniciado com quadro de astenia,\nfebre baixa, oligoartrite assimétrica nos membros\ninferiores, daquitilite em mãos e pés associado a disúria e hiperemia ocular, qual o diagnóstico\nmais\nprovável para este paciente:","options":{"A":"Lupus eritematoso sistêmico.","B":"Sarcoidose aguda.","C":"Artrite reativa.","D":"Doença de behçet"},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-260246","number":"260246","sourceNumber":"260246","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Após intensa libação alcoólica em uma confraternização, paciente masculino de 58\nanos de idade, obeso e dislipidêmico,\ninicia com dor intensa e aumento do volume da articulação\ndo primeiro metatarso do pé esquerdo, associado à febre. Sobre esse quadro, assinale a alternativa\nincorreta.","options":{"A":"O diagnóstico de artrite gotosa é feito com a pesquisa de cristais de birrefringência negativa no\naspirado articular.","B":"Durante a crise de artrite gotosa aguda, deve ser iniciado tratamento imediato com alopurinol.","C":"O diagnóstico diferencial principal é entre artrite séptica e artrite gotosa, devendo ser\nprocedido\no aspirado do líquido articular.","D":"Na artrite séptica, a via hematogênica é a principal forma de entrada da bactéria na\narticulação."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-260554","number":"260554","sourceNumber":"260554","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Criança com diagnóstico estabelecido de Febre Reumática, sem cardite prévia ou atual\ndeverá receber profilaxia secundária com Penicilina Benzatina até:","options":{"A":"18 anos ou 3 anos após o último surto, o que cobrir maior período.","B":"21 anos ou 5 anos após o último surto, o que cobrir maior período.","C":"25 anos ou 3 anos após o último surto, o que cobrir maior período.","D":"Por toda vida."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-262929","number":"262929","sourceNumber":"262929","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em relação à artrite reumatoide, assinale com V as afirmativas Verdadeiras e com F as\nFalsas. ( ) Anticorpos anti-CCP (anticitrulina) são menos específicos que o fator reumatoide. ( )\nDerrame pleural, esplenomegalia e poliartrite assimétrica com predileção para grandes articulações\nsão características da artrite reumatoide. ( ) Início insidioso com rigidez matinal e artralgia são\nmanifestações frequentes e características. ( ) Nódulos subcutâneos ocorrem em 20% dos\npacientes e se correlacionam a uma menor soropositividade para o fator reumatoide. ( )\nManifestações extra-articulares que surgem antes do início da artrite são mais comuns nos\npacientes com história de tabagismo. Assinale a sequência CORRETA.","options":{"A":"F?F?V?F?V.","B":"F?V?V?F?F.","C":"V?V?F?F?F.","D":"F?V?V?F?V."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-259406","number":"259406","sourceNumber":"259406","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente de 4 anos de idade apresentou picadura de inseto na região da coxa direita.\nApós 72h da picada, a pequena lesão papular\ninicial evoluiu para lesão nodular de 4 cm de\ndiâmetro, edema da pele circunjacente, vermelhidão, dor local à palpação e ponto de flutuação de\naspecto purulento. Procurou pronto atendido e foi prescrito neomicina tópica. Após 2 dias de\ntratamento a criança começou a queixar de dificuldade de deambulação, dor a flexão do joelho\ndireito, derrame articular, febre (38,9°C) e prostração. Quanto ao quadro clínico supracitado marque\na afirmativa CORRETA:","options":{"A":"O agente etiológico mais comum é o Staphylococcus aureus, sendo a oxacilina uma boa opção\ncomo tratamento medicamentoso.","B":"Nesta patologia, embora frequentemente o hemograma e as provas inflamatórias são normais, a\nhemocultura é positiva em mais de 50% dos casos.","C":"A drenagem cirúrgica é indicada somente se houver persistência dos sinais flogísticos após 72h\nde antibioticoterapia adequada.","D":"Provavelmente se trata de artrite inflamatória reacional, uma vez que a antibioticoterapia\nadequada da celulite é eficaz na prevenção de\nquadros infecciosos secundários como artrite\nséptica ou osteomielite."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-259408","number":"259408","sourceNumber":"259408","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A febre reumática é uma doença sistêmica de caráter autoimune desencadeada após a\ninfecção pelo streptococo B-hemolítico do grupo A de Lancefield. Seu diagnóstico é eminentemente\nclínico. São manifestações maiores segundo os Critérios de Jones modificados, EXCETO:","options":{"A":"Eritema marginado.","B":"Nódulo subcutâneo.","C":"Artralgia.","D":"Coréia."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-266654","number":"266654","sourceNumber":"266654","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A febre reumática é a doença reumática mais comum em crianças na idade escolar e\nadolescentes. Sobre a febre reumática, assinale a alternativa INCORRETA:","options":{"A":"Normalmente ocorre entre crianças de 5 a 15 anos, podendo se manifestar com insuficiência\ncardíaca.","B":"Segundo os critérios de Jones, um caso de coreia típica confirma diagnóstico não necessitando\nde outros critérios.","C":"O ecocardiograma é um exame bem importante na confirmação das lesões valvares.","D":"A profilaxia por via oral tem o mesmo efeito da intramuscular, podendo ser decidida juntamente\ncom a equipe médica."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-238748","number":"238748","sourceNumber":"238748","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um homem de 43 anos procura o consultório de clínica médica com a queixa de\npalpitação e dispneia aos esforços\nmoderados. Nega uso de medicamentos e doenças conhecidas.\nAo exame físico, apresenta-se alerta e orientado. Os dados vitais são PA 130/80mmHg, FC 65bpm,\nFR 18ipm, SpO2 95%. Os exames respiratório e abdominal não apresentam anormalidades. Traz\nresultados de exames prévios. Ecocardiograma: aumento importante do átrio esquerdo; demais\ncâmaras de dimensões e contratilidade normais. Pressão sistólica de artéria pulmonar 53mmHg\n(VR<40mmHg), Fração de ejeção do ventrículo esquerdo 65% (VR >50%). Espessamento das\ncúspides da valva mitral, restrição da abertura valvar durante a diástole, área mitral de 1cm2 (VR\n\n>4cm2) e regurgitação mitral moderada. Eletrocardiograma: Assinale o achado do exame físico\ncardiovascular que provavelmente NÃO deve estar presente neste paciente.","options":{"A":"Sopro holossistólico suave em platô mais audível no Apex.","B":"Estalido mesossistólico no foco mitral mais audível com o diafragma do estetoscópio.","C":"Desdobramento da segunda bulha contínuo e mais acentuado à inspiração, com hiperfonese de\nP2.","D":"Sopro mesodiastólico em ruflar com reforço pré-sistólico."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-239823","number":"239823","sourceNumber":"239823","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A.F.L.K, 63 anos, masculino, sem comorbidades prévias, iniciou com dor intensa em\njoelho direito, associado a eritema e importante edema. Admitido ao pronto atendimento febril\n(38,5ºC), PA 110x60, FC 112, ritmo cardíaco regular em 2 tempos e sem sopros, sem outras\nalterações ao exame físico. O diagnóstico mais importante a ser avaliado por suas implicações\nprognósticas e a propedêutica mais indicada são?","options":{"A":"Gota e dosagem de uricemia.","B":"Doença do depósito de pirofosfato de cálcio e radiografia de joelho direito.","C":"Artrite Reativa e Reação de cadeia de polimerase para clamídia.","D":"Artrite séptica e artrocentese com análise do líquido sinovial e culturas."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-254996","number":"254996","sourceNumber":"254996","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A Osteoartrite (OA), também conhecida como Osteoartrose, representa uma falência\narticular com perda da cartilagem hialina, com\nalta prevalência em idosos e alta taxa de\nincapacitação. Sobre esta patologia, analise as afirmativas a seguir e marque a opção correta. I. O\nparacetamol é a droga de escolha inicial para controle da dor. II. Rigidez matinal maior que 1 hora\ne\nnódulos subcutâneos são critérios diagnósticos. III. Nos quadros de OA grave das mãos surgem\nnódulos de Heberden nas articulações interfalangianas distais e nódulos de Bouchard nas\ninterfalangianas proximais. IV. Aplicações de glicocorticoides intra-articulares são alternativas\npara\nalguns pacientes, sendo eficazes em reduzir a dor, pelo menos temporariamente.","options":{"A":"Estão corretas apenas as afirmativas I e III.","B":"Estão corretas apenas as afirmativas I, III e IV.","C":"Estão corretas apenas as afirmativas III e IV.","D":"Estão corretas apenas as afirmativas II e IV.","E":"Todas as afirmativas estão corretas."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-239828","number":"239828","sourceNumber":"239828","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente F.G.B., sexo masculino, 27 anos, apresenta lombalgia intensa que o acorda\ndurante a noite, piora em repouso e\nmelhora com exercício, além de rigidez matinal de 60 minutos.\nEvoluiu com hiperemia conjuntival e calcaneodinia. Ao exame físico sopro diastólico em foco\naórtico. Lasègue negativo. Proteína C-reativa 27,5 (VR < 10) e VHS (hemossedimentação) 49. Qual\na principal hipótese diagnóstica?","options":{"A":"Nefrolitíase.","B":"Hérnia discal.","C":"Doença de Whipple.","D":"Espondilite anquilosante."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-253928","number":"253928","sourceNumber":"253928","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente de 15 anos, sexo feminino, foi atendida na emergência com quadro de\nfaringoamigdalite. O médico avaliou a paciente e liberou para casa com prescrição de\n\nanti-inflamatório. Evoluiu com poliartrite, nódulos subcutâneos e cardite. Qual a lesão valvar mais\nfrequente na febre reumática crônica?","options":{"A":"Estenose mitral.","B":"Estenose aórtica.","C":"Estenose tricúspide.","D":"Insuficiência mitral."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-254630","number":"254630","sourceNumber":"254630","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Na febre reumática, a válvula mais frequentemente comprometida é a:","options":{"A":"Pulmonar","B":"Tricúspide","C":"Mitral","D":"Aórtica"},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-219418","number":"219418","sourceNumber":"219418","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Escolar de nove anos, sexo feminino, foi e ada emer ncia por ter se cortado com uma\nfaca no rosto. Anamnese revela que usou\npenicilina benzatina dos seis aos oito anos de idade por\nproblemas no coração. Mãe relata irritabilidade, choro fácil, descontrole emocional e quedas\nfrequentes. Exame físico: leve hipotonia muscular, movimentos involuntários do rosto e das mãos.\nEscolha a sequência que melhor completa a frase abaixo: Esta paciente provavelmente apresenta\n\ne caso seja necessário para controle dos sintomas apresentados poderá necessitar\nde .","options":{"A":"Síndrome de Guillain Barré ? Imunoglobulina","B":"Coreia de Sydenhan ? Haloperidol","C":"Doença de Tay Sachs ? Fenitoína","D":"Epilepsia ? fenobarbital"},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-209532","number":"209532","sourceNumber":"209532","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A profilaxia primária de febre reumática é realizada ADEQUADAMENTE com:","options":{"A":"Penicilina Benzatina de 21/21 dias até os 21 anos após o 1° surto.","B":"Amoxicilina 1 dose 1 hora antes de procedimentos odontológicos.","C":"Amoxicilina de 8/8 horas por 7 dias após quadro de faringoamigdalite.","D":"Eritromicina de 6/6 horas por 10 dias após quadro de faringoamigdalite.","E":"Penicilina Benzatina de 21/21 dias até os 25 anos ou até 10 anos após o último surto, valendo o\nque cobrir o maior período."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-217216","number":"217216","sourceNumber":"217216","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre a Artrite Reumatoide Juvenil (ARJ), marque a alternativa INCORRETA:","options":{"A":"É a artrite crônica mais comum nas crianças.","B":"Pode ter ou não febre no início da apresentação.","C":"A artrite sempre estará presente durante as primeiras semanas da doença.","D":"A ARJ de início sistêmico (doença de Still) responde por aproximadamente 20% dos casos de\nARJ em crianças."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-210470","number":"210470","sourceNumber":"210470","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Escolar do sexo feminino, com 9 anos de idade, iniciou há 2 semanas com quadro de\nfebre de até 38,2ºC e artrite em joelhos, tornozelos e cotovelos. Os níveis de PCR, VHS e\nantiestreptolisina O estão elevados. Criança estava bem até há 1 mês quando teve uma ?infecção\nde garganta muito forte? que foi com amoxicilina por 7 dias. Diante desse quadro, o diagnóstico\nmais provável é:","options":{"A":"Artrite idiopática juvenil.","B":"Artrite enteropática.","C":"Síndrome de Reiter.","D":"Febre reumática."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-179110","number":"179110","sourceNumber":"179110","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menino, dois anos, apresenta vários episódios de febre (entre 38,5ºC e 40ºC) ao dia\nnos últimos três meses. Durante esses episódios verifica-se, frequentemente, exantema\nevanescente em tronco e raiz de membros. Há oito semanas foi notada artrite persistente em\npequenas articulações das mãos, punhos e joelhos, com resposta parcial a anti-inflamatório não\nhormonal. É esperada na investigação laboratorial a presença de:","options":{"A":"Plaquetose.","B":"Anticorpos antinucleares.","C":"Fator reumatoide.","D":"Neutropenia."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-181301","number":"181301","sourceNumber":"181301","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em relação à febre reumática, é CORRETO afirmar que:","options":{"A":"O diagnóstico da febre reumática é eminentemente clínico, podendo o quadro ser bastante\nvariável, ocorrendo desde lesões leves de pouca\nexpressão clínica até casos graves de evolução\nfulminante.","B":"As recidivas da doença não são um importante fator para o agravamento das lesões valvares,\numa vez que o processo cicatricial do\nprimeiro episódio já é o determinante para progressão das\nvalvopatias.","C":"Entre os critérios menores de Jones, pode-se citar a artrite, a cardite e a coreia de Sydenham.","D":"Na maioria dos pacientes, existe uma elevação nos títulos de antiestreptolisina O ? ASLO a\npartir do terceiro dia após o quadro de infecção estreptocócica."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-181252","number":"181252","sourceNumber":"181252","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A AR é uma doença crônica, com potencial de dano articular irreversível, acarretando\naltos custos para o indivíduo acometido e para a\nsociedade. O diagnóstico da AR é estabelecido\nconsiderando-se achados clínicos e exames complementares. Nenhum teste isolado, seja\nlaboratorial, de imagem ou histopatológico, confirma o diagnóstico. Estudo multicêntrico brasileiro\nem amostras populacionais das macrorregiões do país encontrou prevalência de até 1% da\npopulação adulta, o que corresponde a uma estimativa de 1.300.000 pessoas acometidas.\n\nEntretanto, a respeito de nossa realidade nacional, assinale a alternativa INCORRETA.","options":{"A":"No Brasil, ao contrário de países de primeiro mundo, os custos relacionados à AR são elevados.\n\nOs gastos com os pacientes com AR assumem maior repercussão nos países em desenvolvimento,\nnos quais os recursos financeiros para a saúde\nsão menos robustos. Isto enfatiza a importância de\nestudos que avaliem os custos e a alocação de recursos para o diagnóstico e o tratamento da\ndoença adaptados à nossa realidade.","B":"No Brasil, assim como nos países de primeiro mundo, os custos relacionados à AR são\nelevados. Os gastos com os pacientes com AR\nassumem maior repercussão nos países em\ndesenvolvimento, nos quais os recursos financeiros para a saúde são menos robustos. Isto enfatiza\na importância de estudos que avaliem os custos e a alocação de recursos para o diagnóstico e o\ntratamento da doença adaptados à nossa realidade.","C":"No Brasil, assim como nos países de primeiro mundo, os custos relacionados à AR são baixos.\n\nOs gastos com os pacientes com AR assumem maior repercussão nos países em desenvolvimento,\nnos quais os recursos financeiros para a saúde\nsão menos robustos. Isto enfatiza a importância de\nestudos que avaliem os custos e a alocação de recursos para o diagnóstico e o tratamento da\ndoença adaptados à nossa realidade.","D":"No Brasil, assim como nos países de primeiro mundo, os custos relacionados à AR são\nelevados. Os gastos com os pacientes com AR\nassumem menor repercussão nos países em\ndesenvolvimento, nos quais os recursos financeiros para a saúde são menos robustos. Isto enfatiza\na importância de estudos que avaliem os custos e a alocação de recursos para o diagnóstico e o\n\ntratamento da doença adaptados à nossa realidade."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-179307","number":"179307","sourceNumber":"179307","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A Febre Reumática (FR) é uma doença sistêmica, não supurativa, que ocorre em\nindivíduos susceptíveis. Em relação à Febre Reumática, assinale a alternativa INCORRETA.","options":{"A":"A doença atinge, preferencialmente, crianças entre 5 e 15 anos.","B":"A artrite é a forma mais característica de apresentação da doença, acometendo cada articulação\nem um período de um a cinco dias.","C":"Os nódulos subcutâneos, a cardite, a coreia e a artrite são sinais maiores nos critérios de Jones\nmodificados.","D":"A coreia de Sydenhan ocorre principalmente em meninos, e geralmente tem duração\naproximada de seis meses."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-155245","number":"155245","sourceNumber":"155245","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre a gota, marque a afirmativa CORRETA.","options":{"A":"Os níveis de ácido úrico podem estar normais ou baixos durante a artrite gotosa aguda.","B":"O alopurinol, um inibidor da xantina oxidase, é a droga padrão-ouro no tratamento da gota,\ndevendo ser iniciada em todas as fases da\ndoença, seja no estágio de doença assintomática ou na\nartrite gotosa aguda.","C":"O probenecid, um agente uricosúrico, pode ser usado em pacientes portadores de insuficiência\nrenal que excretam pouco ácido úrico.","D":"O diagnóstico da gota é clínico e laboratorial, tornando a aspiração das articulações afetadas\ncom agulha dispensável para a confirmação\ndiagnóstica."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-158221","number":"158221","sourceNumber":"158221","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente do sexo feminino, procura atendimento devido a quadro de edema e dor em\nmãos com relato de início há 2 meses\nacompanhado de rigidez matinal, febre e emagrecimento de\n2kg. Ao exame clínico observa-se presença de edema em ambos os punhos,\nmetacarpofalangeanas e 5 interfalangeanas proximais, além de flexão da interfalangeana proximal\ne hiperextensão da hiperfalangeana distal do quinto dedo e desvio ulnar dos dedos. Nota-se ainda\npresença de nodulação subcutânea na região extensora do antebraço e edema de joelhos\nbilaterais. Quando questionada, relatou que já teve episódios prévios semelhantes, mas nunca tão\ndoloroso e nunca procurou tratamento. Considerando quadro clínico descrito e o seu provável\ndiagnóstico, assinale a alternativa CORRETA.","options":{"A":"A presença de nódulo subcutâneo é patognomônica de artrite reumatoide, o que determina o\ndiagnóstico em questão.","B":"Deve-se iniciar corticoide imediatamente na dose de 10 mg para tratamento da fase aguda da\ndoença.","C":"Deve-se iniciar medicações biológicas imediatamente para tratamento da fase aguda da doença.","D":"O fator reumatoide positivo é determinante para fecharmos o diagnóstico de artrite reumatoide."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-158031","number":"158031","sourceNumber":"158031","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Qual das alternativas abaixo contém elementos para diagnóstico de artrite reumatoide?","options":{"A":"Artrite assimétrica das mãos, proteína c reativa positiva hemossedimentação elevada, fenômeno\nde Raynaud.","B":"Artrite migratória, pancardite, antiestreptolisina elevada, eritema marginado, nódulos de\nheberden.","C":"Poliartrite, lesões cutâneas, pleuris, comprometimento renal.","D":"Rigidez matinal prolongada, artrite simétrica das mãos, fator reumatoide positivo, erosões\nósseas justa-articulares."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-158157","number":"158157","sourceNumber":"158157","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A febre reumática atinge, preferencialmente, crianças de 5 a 15 anos. No Brasil é a\ncausa mais comum de cardiopatia em crianças\ne adultos jovens. Sobre a febre reumática, assinale\na alternativa INCORRETA.","options":{"A":"A presença de duas manifestações maiores (carditite, coreia, artrite, eritema marginado e\nnódulos subcutâneos) ou de uma maior e duas\nmenores (febre, artralgia, elevação dos reagentes\nde fase aguda e intervalo PR prolongado no ECG), acrescidas de evidência de estreptococcia\nrecente, indica alta probabilidade de febre reumática.","B":"Em caso de coreia de Sydenhan é dispensável a presença de outros critérios e também não\nnecessita de comprovação de estreptococcia prévia.","C":"O tratamento inclui erradicação do streptococo, medidas gerais de sustentação e uso de\nanti-inflamatórios.","D":"A insuficiência valvar mais frequente é a pulmonar."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-158166","number":"158166","sourceNumber":"158166","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menino de 3 anos, com suspeita de Artrite Reumatoide Juvenil (ARJ) de início\nsistêmico, foi internado e, no quinto dia\nde internação, apresentou quadro de taquicardia e dispneia.\nQueixava, também, dor no peito e na ausculta cardíaca foi evidenciada um atrito pericárdico.\n\nConsiderando o caso descrito, assinale a alternativa que apresenta a MELHOR conduta a ser\nadotada.","options":{"A":"Administrar salbutamol.","B":"Administrar furosemida.","C":"Avaliar oximetria, solicitar ECG e solicitar interconsulta com cardiologista pediátrico.","D":"Avaliar oximetria, solicitar raio-X de tórax e iniciar antibiótico empiricamente."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-158001","number":"158001","sourceNumber":"158001","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Criança de 02 anos de idade, sexo masculino. É levada ao pronto-atendimento com\nhistória de febre e irritabilidade há 36\nhoras. No exame físico evidencia-se edema, calor e rubor em\njoelho direito, resistindo à mobilização passiva. Qual o diagnóstico mais provável e o exame mais\nimportante para confirmar esse diagnóstico?","options":{"A":"Febre reumática / hemograma completo.","B":"Febre reumática / Velocidade de Hemossedimentação (VHS).","C":"Artrite séptica / exame do líquido articular.","D":"Artrite séptica / ultrassonografia de joelho."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-158278","number":"158278","sourceNumber":"158278","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Adolescente de 14 anos apresenta histórico de quadro agudo de febre reumática aos\n13 anos de idade. No momento encontra-se\nassintomático, entretanto o ecocardiograma evidencia\ninsuficiência mitral leve. Neste caso, a duração da profilaxia secundária da febre reumática é:","options":{"A":"Até os 18 anos;","B":"Até os 35 anos;","C":"Por toda vida;","D":"Até os 25 anos."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-132344","number":"132344","sourceNumber":"132344","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em relação às doenças reumatológicas em geral, assinale a afirmativa verdadeira.","options":{"A":"A espondilite anquilosante comumente se apresenta por dor lombar em paciente jovem do sexo\nmasculino e, em geral, o FAN e o fator reumatoide são negativos, mas o HLAB27 pode estar\npresente em até 90% dos casos.","B":"A polimiosite acomete com mais frequência mulheres na quarta e quinta décadas de vida e está\nfortemente associada com neoplasias malignas, sendo, inclusive, indicado rastreamento daquelas\nmais comuns, como mama, pulmão e cólon.","C":"A síndrome de Sjögren é mais comum em mulheres, sendo o infiltrado inflamatório com\npredomínio de linfócitos T tipo CD4 o achado mais recorrente na histopatologia das lesões\nsalivares.","D":"As artrites reativas são comuns após infecções intestinais e/ou uretrais, podendo o quadro ser\nrecorrente, situação na qual os corticoides são minimamente eficazes, o que torna preferível a\nterapêutica por imunobiológicos mais modernos, como infliximab e rituximab.","E":"Na artrite reumatoide, o anticorpo anti-CCP tem maior sensibilidade e menor especificidade em\nrelação ao fator reumatoide (FR), servindo, desse modo, o anti-CCP como rastreamento da doença\ne devendo os casos positivos ser confirmados pelo FR."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-132350","number":"132350","sourceNumber":"132350","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Os anticorpos séricos contra peptídios citrulinados cíclicos (anti-CCP) têm valor\nprognóstico e diagnóstico na:","options":{"A":"Esclerose sistêmica.","B":"Lúpus eritematoso sistêmico.","C":"Policondrite recidivante.","D":"Doença de Behçet.","E":"Artrite reumatoide."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-131754","number":"131754","sourceNumber":"131754","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Jonathas, 15 anos, queixa-se de artrite migratória em joelhos, punho esquerdo e\ntornozelo há alguns dias. Há dois dias, apresenta dor precordial e dispneia aos grandes esforços.\nAo exame, artrite em tornozelo direito, taquicardia e sopro sistólico em foco mitral com irradiação\npara axila. Dos parâmetros abaixo, qual não faz parte dos critérios maiores de Jones modificados\npara o diagnóstico do paciente?","options":{"A":"Coreia.","B":"Intervalo PR prolongado.","C":"Eritema marginado.","D":"Nódulos subcutâneos.","E":"Artrite, cardite."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-131767","number":"131767","sourceNumber":"131767","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Ângela, 24 anos, queixa dor, tumefação articular em joelhos e tornozelos e lesão\neritematosa em região malar. Anita, 28\nanos, queixa, há quatro meses, de artrite simétrica em\npunhos, matacarpofalangeanas e interfalangeanas proximais, rigidez matinal maior que trinta\nminutos. Dos casos clínicos e laboratoriais quais não devem ser encontrados nas duas pacientes?\nAssinale a alternativa correta:","options":{"A":"Úlceras orais indolores e derrame pleural.","B":"Fotossensibilidade e fenômeno de Raynaud.","C":"Títulos elevados de fator reumatoide e erosões articulares ao RX.","D":"Anticorpo antinuclear positivo e células LE.","E":"VDRL positivo e anticorpo antinuclear positivo."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-136673","number":"136673","sourceNumber":"136673","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Qual das alternativas abaixo contém elementos para diagnóstico de artrite reumatóide:","options":{"A":"Artrite assimétrica das mãos, proteína C-reativa positiva, hemossedimentação elevada,\nfenômeno de Raynaud.","B":"Artrite migratória, pancardite, antiestreptolisina elevada, eritema marginado, nódulos de\nHeberden.","C":"Poliartrite, lesões cutâneas, pleuris, comprometimento renal.","D":"Rigidez matinal prolongada, artrite simétrica das mãos, fator reumatóide positivo, erosões\nósseas justa-articulares."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-129244","number":"129244","sourceNumber":"129244","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente de 48 anos, hipertenso e etilista diário, apresenta segundo o quadro, dor em\njoelho direito acompanhado de hiperemia e aumento de volume articular. Evoluiu com febre\ntermometrada e persistência da dor procurando atendimento médico. Ao exame físico,\n\napresenta-se com sinais de artrite, mas sem restrição de movimento e temperatura axilar de\n38,3ºC. Exames laboratoriais evidenciavam leucocitose de 16.000 com 2% de bastonetes.\n\nRealizada artrocentese diagnóstica que evidenciou 30.000 leucócitos com 55% de\npolimorfonucleares. Considerando o quadro clínico\ndescrito, assinale a alternativa CORRETA:","options":{"A":"Pelo histórico clínico e os dados apresentados pela análise do líquido articular, o diagnóstico é\nde artrite séptica.","B":"O diagnóstico ainda não pode ser confirmado apenas com os dados apresentados.","C":"O diagnóstico de gota foi descartado pela história clínica, devido à presença de febre e\nleucocitose.","D":"A ausência de restrição de movimento (artrite congelada) exclui a possibilidade de artrite\nséptica."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-105737","number":"105737","sourceNumber":"105737","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Luana, 8 anos, previamente hígida, é trazida ao pronto-socorro com \"dores fortes nas\npernas\" que se iniciaram há 10 dias em\ntornozelo direito, com melhora espontânea em cinco dias e\naparecimento a seguir em joelho ipsilateral. Hoje refere melhora deste quadro e acometimento do\njoelho esquerdo. Febre associada e mal-estar geral. Nega trauma. Febril (38,5ºC), taquicárdica,\nsopro sistólico em foco mitral, abafamento de primeira bulha, dor à movimentação passiva e ativa\ndo tornozelo e joelho direitos; dor, edema ++/4 e limitação de movimentos em joelho esquerdo. RX\nde tórax normal, ECG ? aumento do intervalo PR, aumento do VHS e PCR, cultura de orofaringe\npositiva para estreptococos. A conduta inicial deve ser:","options":{"A":"Repouso relativo, erradicação do estreptococo, anti-inflamatório não esteroidal e prednisona.","B":"Repouso absoluto, erradicação do estreptococo, anti-inflamatório não esteroidal e prednisona.","C":"Repouso absoluto, erradicação do estreptococo, anti-inflamatório não esteroidal e pulsoterapia\ncom metilprednisolona.","D":"Repouso relativo, erradicação do estreptococo, anti-inflamatório não esteroidal, prednisona e\ndiuréticos.","E":"Repouso relativo, erradicação do estreptococo, anti-inflamatório não esteroidal, prednisona e\nrestrição hídrica."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-105740","number":"105740","sourceNumber":"105740","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Luana, 8 anos, previamente hígida, é trazida ao pronto-socorro com \"dores fortes nas\npernas\" que se iniciaram há 10 dias em\ntornozelo direito, com melhora espontânea em cinco dias e\naparecimento a seguir em joelho ipsilateral. Hoje refere melhora deste quadro e acometimento do\njoelho esquerdo. Febre associada e mal-estar geral. Nega trauma. Febril (38,5ºC), taquicárdica,\nsopro sistólico em foco mitral, abafamento de primeira bulha, dor à movimentação passiva e ativa\ndo tornozelo e joelho direitos; dor, edema ++/4 e limitação de movimentos em joelho esquerdo. RX\nde tórax normal, ECG - aumento do intervalo PR, aumento do VHS e PCR, cultura de orofaringe\npositiva para estreptococos. Assinale a alternativa que representa o exame laboratorial que pode\nser usado para monitorar atividade desta doença:","options":{"A":"PCR.","B":"Velocidade de Hemossedimentação (VHS).","C":"Alfa-1-glicoproteína ácida.","D":"DHL.","E":"ASLO."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-105791","number":"105791","sourceNumber":"105791","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Antônio, 65 anos, com hipertensão, diabetes mellitus tipo 2 e doença articular\ndegenerativa, tem dor aguda intensa das\narticulações metatarsofalangianas e edema do hálux\nesquerdo. O exame físico mostra artrite da primeira metatarsiana esquerda com dor, edema, calor e\neritema. Não há história de traumatismo ou outros problemas clínicos. Assinale a alternativa\nCORRETA quanto ao diagnóstico do paciente:","options":{"A":"Artrite séptica por gonococos.","B":"Artrite reativa por Chlamydia.","C":"Artrite reativa por Borrelia.","D":"Artrite gotosa.","E":"Artrite por Mycoplasma."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-105731","number":"105731","sourceNumber":"105731","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mateus, 21 anos, queixa-se de dor lombar que persiste há quatro meses, além de\nrigidez na região lombar, que piora com a\ninatividade. Refere dificuldade para sair da cama de\nmanhã e necessidade de rolar de lado, tentando não flexionar ou girar a coluna vertebral para\ndiminuir a dor. Assinale a alternativa CORRETA que mostra as alterações esperadas na radiografia\nda coluna lombar e bacia do paciente:","options":{"A":"Doença articular degenerativa com formação de osteófitos.","B":"Osteonecrose difusa de coluna lombo sacra.","C":"Sacroileíte com esclerose das articulações sacroilíacas.","D":"Destruição do corpo vertebral com fraturas em cunha.","E":"Lesões articulares em ponta de lápis."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-120750","number":"120750","sourceNumber":"120750","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente de 54 anos com poliartrite e rigidez matinal de mais de três horas de duração\nhá mais de 10 anos, apresentou-se com\ncefaléia occipital, sensação de peso e fraqueza muscular\nnos braços, pernas saltitantes quando em recumbência (deitado ou recostado). O exame\nneurológico revelou paresia espástica de ambos membros superiores e membro inferior direito, com\nsinal de Babinski positivo. Ao Raios-X foi detectada uma subluxação de C1 sobre C2 de 14 mm em\nflexão e 3mm em extensão. Qual o diagnóstico:","options":{"A":"Febre reumática","B":"Mielopatiaespondiloartrósica","C":"Mielite transversa lúpica","D":"Sífilis terciária","E":"Artrite reumatóide"},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-85998","number":"85998","sourceNumber":"85998","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um paciente com 38 anos apresenta, há quatro meses, artrite simétrica de articulações\ndo punho, interfalangianas proximais e\nmetacarpofalangianas, e rigidez articular matinal durando\npelo menos uma hora. Avaliação laboratorial revelou fator reumatoide positivo. Qual dos\ntratamentos a seguir não modifica o curso desta doença?","options":{"A":"Prednisona.","B":"Sulfassalazina.","C":"Metotrexato.","D":"Ciclosporina."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-80780","number":"80780","sourceNumber":"80780","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Suzana, 46 anos, há seis meses com queixa de dor, calor, rubor e impotência funcional\nem mãos (MCF, IFP), punhos, cotovelos, ombros,\njoelhos, tornozelos e articulação\ntemporomandibular. Em tratamento contínuo com sulfato de hidroxicloroquina 400 mg/dia,\nmetotrexato 10 miligramas/semana, dipirona 1.500 mg, avaliação global do estado geral da\npaciente pela escala analógica igual a 7. Hemossedimentação: 36 mm/1h; Proteína C-reativa: 1,5\nmg/ml (VN < 0,5 mg/ml); Fator Antinuclear: 1/80, nuclear pontilhado fino; Fator Reumatoide:\nnegativo, Anti-CCP: 1,2 U/ml (VN < 70 U/ml); RX de mãos e punhos: aumento de partes moles,\nosteopenia em epífise óssea e diminuição do espaços interarticulares. Sobre a Artrite Reumatoide\n(AR), assinale a alternativa INCORRETA:","options":{"A":"As manifestações clínicas como febre, astenia, fadiga, mialgia e perda ponderal, podem\nanteceder o quadro de poliartrite.","B":"A artrite caracteriza-se pela dor, calor, tumefação, limitação dos movimentos e rigidez\narticular.","C":"O envolvimento articular que ocorre nas articulações sinoviais é de caráter simétrico e aditivo.","D":"O envolvimento das interfalangianas distais, do primeiro metacarpo e metatarsofalangiana é\nfrequente na doença, necessitando fazer o\ndiagnóstico diferencial com outras doenças inflamatórias\narticulares.","E":"As alterações como nódulos reumatoides, vasculite, sorologia positiva para o fator reumatoide e\npara os anticorpos antipeptídeos citrulinados cíclicos podem caracterizar uma forma grave da\ndoença."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-59000","number":"59000","sourceNumber":"59000","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente de 32 anos, sexo masculino, mecânico de automóveis, queixa-se de dor em\ncoluna lombar iniciada há alguns anos, com piora progressiva nos últimos seis meses. A dor é pior\nao acordar e melhora com atividade física. Relata rigidez em região lombar pela manhã. O exame\nclínico revelou teste de Schober alterado. Considerando a principal hipótese diagnóstica em relação\na esse caso, espera-se encontrar os seguintes achados, EXCETO:","options":{"A":"Pesquisa do HLA-B27 positiva em mais de 80% dos casos.","B":"FAN e fator reumatoide positivos em até metade dos casos.","C":"Radiografia de articulações sacroilíacas normal em casos iniciais.","D":"Melhora dos sintomas e da mobilidade com anti-inflamatórios não esteroidais."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-69407","number":"69407","sourceNumber":"69407","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"São afirmativas corretas em relação à Artrite Reumatoide, exceto:","options":{"A":"A Artrite Reumatoide caracteristicamente é uma poliartrite crônica que, em cerca de 2/3 dos\ncasos, começa insidiosamente.","B":"A duração e intensidade da rigidez podem ser usados como avaliação grosseira da atividade da\ndoença.","C":"O acometimento das articulações da coluna cervical superior resulta em subluxação atlantoaxial\ne da coluna lombar, lombalgia.","D":"A síndrome de Felty consiste em Artrite Reumatoide crônica, esplenomegalia e neutropenia."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-69423","number":"69423","sourceNumber":"69423","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A artrite reumatoide juvenil é uma patologia inflamatória crônica. Sobre a mesma\npodemos afirmar: I - Na literatura, mostram uma\nmaior prevalência da doença em irmãos, bem\ncomo em parentes de primeiro grau de portadores de outras doenças reumáticas. II - É\ncaracterizada pela presença de derrame articular ou pela presença dos seguintes sinais: dor\ndurante palpação ou movimentação, calor e limitação articular. III - Para o diagnóstico, é preciso\npresença de artrite crônica com duração maior que seis semanas, em pelo menos uma articulação.","options":{"A":"I, II, III são verdadeiras","B":"I e II são verdadeiras","C":"Somente a III é verdadeira","D":"II e III são verdadeiras"},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-44496","number":"44496","sourceNumber":"44496","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"São critérios diagnósticos de artrite reumatoide, EXCETO:","options":{"A":"Rigidez matinal por pelo menos 1 hora.","B":"Artrite simétrica.","C":"Erosões ou descalcificações localizadas em rx de mãos e punhos.","D":"Eritema marginado."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-13560","number":"13560","sourceNumber":"13560","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Qual das alterações é encontrada na doença de Still do adulto?","options":{"A":"Pancitopenia grave.","B":"Fator antinuclear positivo em altas diluições.","C":"Ferritina muito elevada.","D":"Fator reumatoide positivo no início da doença."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-9656","number":"9656","sourceNumber":"9656","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente com 38 anos de idade, apresentando há 4 meses artrite simétrica de\narticulações do punho, interfalangianas\nproximais e metacarpofalangianas, rigidez articular matinal\ndurando pelo menos 1 hora. Avaliação laboratorial revelou fator rematoide positivo. Qual dos\ntratamentos abaixo NÃO MODIFICA o curso desta doença?","options":{"A":"Prednisona.","B":"Sulfasalazina.","C":"Metotrexato.","D":"Ciclosporina."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-349183","number":"349183","sourceNumber":"349183","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um homem branco de 56 anos, sexualmente ativo, portador de síndrome metabólica,\nretorna ao ambulatório de referência 2 semanas\napós ter sido diagnosticado com artrite gotosa\naguda em joelho direito, através de artrocentese com análise do líquido sinovial. Após o\ndiagnóstico, o paciente manteve o uso de colchicina e interrompeu o tratamento com alopurinol.\nSegundo relato, apresentou melhora nos seus sintomas com o uso do anti-inflamatório não\nesteroidal prescrito. Ao exame físico, a articulação do joelho direito revela-se novamente bastante\ninflamada, com intenso rubor, calor e edema, além de impotência funcional. Realiza nova\nartrocentese, cujos resultados iniciais revelam 120 000 leucócitos/mm³, com 95% de\npolimorfonucleares. Considerando a situação desse paciente, a melhor explicação para o quadro\narticular atual é","options":{"A":"artrite séptica bacteriana.","B":"desenvolvimento de pseudogota local.","C":"re-exarcerbação da artrite gotosa aguda.","D":"artrite secundária a infecção sexualmente transmissível."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-347400","number":"347400","sourceNumber":"347400","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Uma mulher com 52 anos comparece à consulta médica na unidade básica de saúde\ncom queixa de dores musculoesqueléticas\ncrônicas, mal localizadas, difusas, acima e abaixo da\ncintura. Refere que o quadro tem cerca de 4 meses de evolução, tendo surgido aparentemente\napós episódio de dengue (não grave). A paciente também refere fadiga e quadro depressivo há\nlonga data, além de transtorno da articulação temporomandibular e síndrome do intestino irritável.\nRelata apetite preservado. Seu exame físico é normal, salvo por dor à compressão e palpação\nmuscular difusa. Digno de nota é que a simples insuflação do esfigmomanômetro leva a dor\nsignificativa em ponto localizado cerca de 2 centímetros distais do epicôndilo lateral do membro\nsuperior avaliado. Além disso, há dor à compressão digital bilateral nos pontos de inserção dos\nmúsculos subocciptais, no ponto médio da borda superior de ambos os músculos trapézios, sobre a\nborda medial das escápulas, nos quadrantes superiores externos das nádegas, posteriormente às\neminências trocantéricas dos fêmures, sobre a 2ª articulação condroesternal direita e sobre as\npartes moles localizadas superior e medialmente a ambos os joelhos. Não há alterações no\nhemograma completo, nem na dosagem de proteína C reativa, T4 livre, TSH e velocidade de\nhemossedimentação. No caso apresentado, qual o diagnóstico dessa paciente?","options":{"A":"Fibromialgia","B":"Hipotireoidismo subclínico.","C":"Transtorno psicossomático.","D":"Transtorno depressivo maior."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-318530","number":"318530","sourceNumber":"318530","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um menino com 11 anos de idade apresenta febre diária há 4 dias e claudicação de\nmembro inferior direito e vem usando ibuprofeno desde o início do quadro, sem melhora. Há 1 dia,\nrecusa-se a andar, referindo muita dor no joelho direito, onde notou inchaço e vermelhidão. Refere\nainda inapetência e indisposição geral. Tem antecedente de lesões crostosas de mucosa nasal e\npele ao redor do nariz há 2 semanas, tendo usado pomada à base de corticoide, sem melhora. Ao\nexame físico apresentou regular estado geral, corado, hidratado, febril (temperatura = 38 ºC),\nfrequência cardíaca: 103 batimentos por minuto, frequência respiratória: 16 incursões respiratórias\npor minuto, anictérico, acianótico, eupneico, pulsos cheios, boa perfusão periférica. Lesões\npustulosas e crostosas em vestíbulo nasal. Joelho direito com edema, calor e intensa dor à\nmobilização. Restante dos aparelhos sem alterações. Para a elucidação diagnóstica, quais são os\nexames/procedimentos indicados?","options":{"A":"Antiestreptolisina O e ecocardiograma.","B":"Anticorpo antinuclear e fator reumatoide.","C":"Ultrassonografia e punção articular de joelho.","D":"Hemograma e provas de atividade inflamatória."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-319984","number":"319984","sourceNumber":"319984","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 32 anos, professora de educação básica, procurou assistência médica, com\nqueixas de dores generalizadas pelo corpo e dificuldade para dormir. Não faz uso de nenhum\nmedicamento para doenças crônicas. Encontra-se de licença médica há 6 meses e ainda não\nobteve grande melhora. Refere que acorda exausta. Nega febre. Diz já ter sido muito ativa,\ntrabalhando em 4 escolas ao mesmo tempo, entretanto tem medo de retornar ao trabalho e voltar a\nter dores mais fortes. O exame físico mostrou-se normal, à exceção da dor à pressão em diversos\ngrupamentos musculares em todo o corpo, sem sinal de bloqueio articular ou de inflamação\narticular. Foram realizados alguns exames laboratoriais, que resultaram normais, incluídos TSH,\nVHS e proteína C reativa ultrassensível. Provavelmente, trata-se de","options":{"A":"polimiosite.","B":"fibromialgia.","C":"fadiga crônica.","D":"polimialgia reumática."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-352604","number":"352604","sourceNumber":"352604","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Irinete, 58 anos, vem à consulta na unidade de saúde devido a ?dor nas juntas?. Relata\nque sente dor desde a hora que acorda, principalmente enquanto faz as tarefas domésticas e cuida\ndo neto de 4 anos. Sente rigidez nas articulações ao acordar ou após muito tempo em repouso que\nduram em torno de 20 minutos. Relata que sente o sono não sendo reparador e tem a sensação de\ncabeça vazia. Ao exame físico, o joelho direito apresenta-se aumentado de tamanho e com\ncrepitações, tornozelo direito com leve edema articular. Sem outras articulações com sinais de\nsinovite. Apresenta dor à palpação em vários pontos do corpo. Dentre as hipóteses diagnósticas de\nIrinete estão:","options":{"A":"Artrite reumatoide, contudo, descarta-se pela idade e pelo acometimento apenas de grandes\narticulações.","B":"Fibromialgia é a hipótese mais provável e explica os sintomas da paciente, sem necessidades de\nexames complementares.","C":"Osteoartrite é uma hipótese diagnóstica importante a ser considerada, acometendo joelho e\nsobrecarregando tornozelo.","D":"Hipotiroidismo como causa do distúrbio do sono que pode estar causando o sintoma de cabeça\nvazia e aumentando a sensibilidade à dor e edema articular."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-331145","number":"331145","sourceNumber":"331145","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 40 anos vai ao médico devido a crise de artrite em tornozelo esquerdo há 1\ndia. Relata 3 episódios prévios, o primeiro acometendo o joelho esquerdo, o segundo acometeu o\ntornozelo direito e o último a primeira articulação metatarsofalangeana esquerda. Os episódios\nanteriores foram tratados com automedicação de formulação de corticoide intramuscular, mas como\nsoube, por meio de amigos, que estas injeções poderiam causar sérios efeitos colaterais, decidiu\nprocurar atendimento no episódio atual. O paciente relata fazer uso frequente de carne vermelha e\nbebida alcoólica, além de ser hipertenso, em uso de hidroclorotiazida 25mg/dia. Nega outras\ncomorbidades. Seu estado geral é bom e o exame físico é normal, exceto pela presença de artrite\nem tornozelo esquerdo. A medicação que pode ser útil no quadro atual é a(o)","options":{"A":"cloroquina.","B":"colchicina.","C":"metotrexato.","D":"azatioprina.","E":"penicilamina."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-326302","number":"326302","sourceNumber":"326302","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher com 57 anos e trabalha como faxineira. Procura atendimento devido queixa de\ndor articular em mãos e joelhos. Relata rigidez matinal que melhora em menos de 20 minutos com\nas atividades da manhã. Ao exame das mãos observa-se deformidade nas articulações\ninterfalangianas, sem sinais de sinovite. Joelho direito com leve edema e calor, com crepitação à\nmovimentação. Joelho esquerdo sem alterações. A condução mais adequada para o caso é:","options":{"A":"Solicitar VHS, PCR e iniciar prednisona.","B":"Fazer um AINE por no máximo 7 dias, analgesia simples e fisioterapia.","C":"Solicitar RX de mãos, joelhos, provas inflamatórias e Fator reumatóide.","D":"Fazer uma dose de corticoide intramuscular e solicitar RX das articulações."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-331182","number":"331182","sourceNumber":"331182","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Criança de 7 anos de idade, com história de trauma em joelho direito há 3 dias durante\njogo de futebol, evolui com febre e dor\nintensa no joelho, com edema, calor e rubor locais há 24\nhoras. Sobre o caso descrito, é correto afirmar:","options":{"A":"Deve-se investigar artrite idiopática juvenil solicitando fator reumatoide e FAN para definição\ndo\nsubtipo de doença.","B":"A principal hipótese diagnóstica é fratura, devendo-se imobilizar o membro e prescrever\nanti-inflamatório não hormonal e protetor gástrico.","C":"Deve ser realizada a punção articular e iniciada a antibioticoterapia parenteral com cobertura\npara estafilococo.","D":"Deve-se considerar o diagnóstico de artrite séptica e iniciar o tratamento com cefalexina oral\npor\n4 semanas.","E":"Trata-se de artrite pós-traumática, devendo ser realizada ultrassonografia de joelho e iniciado\nanti-inflamatório não hormonal."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-331184","number":"331184","sourceNumber":"331184","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Médico atende uma criança de 8 anos com queixa de dor lombar de forte intensidade,\nassociada à artrite muito dolorosa em\njoelhos e dor em região anterior da tíbia, há 3 dias. Ao exame\nfísico, apresenta palidez leve, ausência de adenomegalias, auscultas cardíaca e pulmonar sem\nalterações, abdômen sem massas ou visceromegalias palpáveis. Ela refere que a dor não melhora\ncom analgésicos comuns e tem atrapalhado suas atividades diárias e o sono. A medicação\ncontraindicada neste caso é","options":{"A":"dexametasona.","B":"naproxeno.","C":"analgésicos opioides.","D":"paracetamol.","E":"cetoprofeno."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-331186","number":"331186","sourceNumber":"331186","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A febre reumática é uma complicação tardia e não supurativa da faringite\nestreptocócica e, no Brasil, é a principal\ncausa de cardiopatia adquirida em pacientes jovens. Seu\ndiagnóstico é baseado nos critérios de Jones modificados e atualizados. As alterações que podem\nser consideradas critérios maiores em regiões de alto risco para a doença são","options":{"A":"endocardite, poliartrite e ASLO positivo.","B":"pericardite isolada, artrite, nódulos subcutâneos.","C":"pancardite, poliartralgia, corea de Sydenham.","D":"monoartrite, ASLO positivo, eritema marginado.","E":"corea de Sydenham, elevação de PCR e VHS, febre."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-302530","number":"302530","sourceNumber":"302530","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 26 anos está em acompanhamento ambulatorial devido à artrite reumatoide.\nO quadro de poliartrite iniciou há 1 ano e,\napós 3 meses, iniciou o uso oral de metotrexato 15\nmg/semana, ácido fólico 5 mg/semana e prednisona 10 mg/dia. Nas consultas posteriores, devido à\npersistência do quadro articular, houve aumento progressivo do metotrexato até a dose atual de 25\nmg/semana, a qual está em uso regular há 3 meses. As demais medicações foram mantidas nas\ndoses descritas anteriormente. O Disease Activity Score (DAS) 28 na consulta de hoje é de 4,1. A\nconduta a ser adotada neste momento é:","options":{"A":"Reduzir o metotrexato via oral para 15 mg/semana.","B":"Aumentar o metotrexato via oral para 30 mg/semana.","C":"Reduzir a prednisona para 5 mg/dia.","D":"Associar a leflunomida 20 mg/dia.","E":"Associar a azatioprina 50 mg/dia."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-320161","number":"320161","sourceNumber":"320161","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menor, 12 anos, internado com quadro de adinamia, taquicardia ocasional e dispneia\naos esforços, com tiragem subcostal e\nintercostal. Mãe refere que a menor não consegue mais\nbrincar com os primos, pois fica muito \"ofegante\", e quando isso acontecia, sentava-se na calçada\npara descansar. Refere que há 10 dias apresentou dor em joelho direito, sem relato concomitante\ncom queda, edema e choro intenso quando tentava massagear, a dor se localizou em cotovelo\nesquerdo, e atualmente a criança refere a mesma dor em ombro direito, sem sinais de hiperemia,\ncom edema, dor e limitação da movimentação. Nos Antecedentes Mórbidos Pessoais (AMP), mãe\nrefere que a menor apresentou há 3 semanas quadro de odinofagia, prostração e febre elevada\n(39°C), impossibilitando ingesta de alimentos e líquidos, foi levada à UPA (apresentou na ocasião\nhemograma com anemia discreta e leucocitose sem desvio à esquerda/VHS de 65 mm/PCR de 21\nmg/dl), sendo prescrito sulfametoxazol-trimetoprima e analgésicos, com melhora do quadro após 7\ndias de uso; antes do quadro atual, a criança era hígida. Quanto ao diagnóstico mais provável, a\ncomplicação, o agente etiológico e o tratamento indicado para ele, marque a única alternativa\nCORRETA.","options":{"A":"Lúpus eritematoso sistêmico, com insuficiência cardíaca congestiva/vírus influenza/aciclovir.","B":"Púrpura de Henoch-Schönlein, com artrite séptica/Staphylococcus aureus/oxacilina.","C":"Artrite reumatoide juvenil, com pneumonia atípica/Mycoplasma pneumoniae/eritromicina.","D":"Febre reumática, com cardite reumática/Streptococcus pyogenes/penicilina G benzatina.","E":"Endocardite infecciosa, com artrite séptica/Streptococcus viridans/penicilina G cristalina."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-277723","number":"277723","sourceNumber":"277723","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 45 anos com diagnóstico de artrite reumatoide, fator reumatoide positivo, há\n20 anos. Faz uso de metotrexato, ácido\nfólico e tocilizumabe. Relata que há 6 meses iniciou com\nperda de peso (inicial = 60 kg; atual = 45 kg) e aumento progressivo de linfonodos, primeiramente\ncervicais e com generalização com o passar dos meses. Ao exame físico, apresenta\nlinfonodomegalia exuberante em cadeias cervicais, supraclaviculares, axilares e inguinais, sem\ncoalescência, sem fistulização e sem sinais inflamatórios. A maior chega a ter diâmetro superior a 5\ncm. A conduta a ser adotada e a sua justificativa devem ser:","options":{"A":"Suspender o tocilizumabe devido a sua associação com a linfonodomegalia descrita.","B":"Suspender o metotrexato devido a sua associação com a linfonodomegalia descrita.","C":"Realizar uma biópsia excisional de linfonodo devido à possibilidade de linfoma.","D":"Associar prednisona para reduzir a linfonodomegalia relacionada à atividade de doença.","E":"Investigar a sobreposição de lúpus, o qual justificaria a linfonodomegalia descrita."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-269766","number":"269766","sourceNumber":"269766","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente feminina, 55 anos, apresentando quadro de fadiga, anemia leve de doença\ncrônica e artrite bilateral simétrica,\nprincipalmente em mãos e punhos, há mais ou menos 8\nsemanas. Refere, ainda, rigidez matinal de cerca de 1 hora e meia de duração. É corredora\nprofissional e relata melhora dos sintomas álgicos, quando realiza sua atividade física. O exame\nfísico articular mostrou edema, calor e dor à palpação em punhos, metacarpofalangianas e\ninterfalangianas proximais. Em relação à conduta diagnóstica e terapêutica, desta paciente, marque\na alternativa CORRETA.","options":{"A":"Artrite reumatoide é a principal hipótese diagnóstica. Exames laboratoriais, como VHS, PCR,\ndosagem do fator reumatoide e pesquisa do anti-CCP ajudam a diferenciar de artrites\nsoronegativas, além de fazerem parte dos critérios classificatórios da doença. Deve-se iniciar\nmetotrexato.","B":"Doença degenerativa (osteoartrite) é a principal hipótese diagnóstica, pela característica do\nacometimento articular. Nas radiografias simples espera-se encontrar osteofitose, cistos\nsubcondrais e esclerose óssea nas articulações acometidas e as provas inflamatórias estariam\nalteradas. Devem-se iniciar antimaláricos.","C":"Artrite reumatoide é a principal hipótese diagnóstica. Não há a necessidade de realizar provas\ninflamatórias ou dosagem de autoanticorpos, pois a paciente já fecha critérios de classificação da\ndoença. Nas radiografias simples espera-se encontrar cistos e erosões ósseas nas articulações\nacometidas. Deve-se iniciar anti-inflamatórios não hormonais.","D":"A principal hipótese diagnóstica é espondilite anquilosante sem comprometimento axial. Exames\nde imagem, VHS, PCR e pesquisa do antígeno\nHLA-B27 são necessários para fechar o\ndiagnóstico. Deve-se iniciar medicação imunobiológica, assim que possível, preferencialmente\n\nanti-TNF associado ao uso de anti-inflamatórios não hormonais.","E":"Artrite psoriásica é a principal hipótese diagnóstica, pelo não acometimento de interfalangianas\ndistais. O comprometimento simétrico e\nbilateral é característico da doença. Ao realizar o exame\nfísico, procurar por lesões em placas descamativas em áreas extensoras dos membros e couro\n\ncabeludo. Deve-se iniciar corticoide oral."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-269767","number":"269767","sourceNumber":"269767","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente masculino, 60 anos, etilista, tabagista e hipertenso, chega no pronto\natendimento carregado pelo filho, relatando ser\nportador de gota há 8 anos. Refere ter acordado no\nmeio da noite do dia anterior, com dor de forte intensidade e hiperemia em tornozelo direito, que o\nimpossibilita de deambular. Histórico de crises agudas de gota de repetição por tratamento\nirregular. No momento, não está em uso de nenhuma medicação. Ao exame físico apresenta tofos\nem cotovelos bilateralmente. A melhor estratégia de tratamento deste caso é:","options":{"A":"Colchicina, corticoide injetável e alopurinol.","B":"Alopurinol e analgésicos opioides.","C":"Colchicina e, se necessário, anti-inflamatório não hormonal.","D":"Analgésicos, como paracetamol e orientar dieta.","E":"Somente Alopurinol."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-269768","number":"269768","sourceNumber":"269768","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente masculino, 35 anos, comerciante, relata histórico de lombalgia que melhora ao\nmovimento e piora quando está em repouso. Procurou um clínico há quatro meses, sendo prescrito\nibuprofeno de horário, diariamente. Durante o período que estava fazendo uso da medicação,\nhouve melhora da dor. Há cerca de dois meses, voltou a apresentar dor lombar mais intensa, em\nespecial no período da manhã, com as mesmas características, porém com irradiação para as\nnádegas. Iniciou, também, quadro de artrite em joelho direito. Em relação ao caso clínico descrito,\nmarque a alternativa CORRETA.","options":{"A":"Nesses casos, a pesquisa do antígeno HLA-B27 é de pouca relevância clínica para o\ndiagnóstico, pois é encontrado em menos de 50% desses pacientes.","B":"Seria também esperado esse paciente evoluir com acometimento inflamatório progressivo de\npequenas articulações, de forma assimétrica e\noligoarticular.","C":"O envolvimento discal e degenerativo vertebral justifica o sintoma lombar e a irradiação da dor\npara as nádegas, podendo simular ciática ou lesão por trauma.","D":"A fisioterapia corresponde ao tratamento padrão-ouro nos estágios iniciais. Não havendo\nmedicações que alterem seu prognóstico, até o momento.","E":"Na investigação diagnóstica, é importante que esse paciente seja questionado sobre o\ncomportamento sexual, sintomas intestinais, oculares e lesões de pele."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-259999","number":"259999","sourceNumber":"259999","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 42 anos, dona de casa, refere dor em articulações das mãos e joelhos há\nmais de 6 meses. Relata que a dor é associada ao uso da articulação, piora com o frio e acorda\ncom rigidez matinal que dura em torno de 15 minutos. Nega febre ou lesões de pele. Relata ganho\nde peso no período e dispneia aos grandes esforços. Não pratica atividade física regularmente há\num ano. Faz uso irregular de diclofenaco e já fez corticoide IM. Ao exame físico: artrite de 2ª, 3ª\ne\n4ª interfalangeanas proximais e distais (foto da mão a seguir). Joelhos com crepitação, mas sem\nsinais de artrite. Ausculta cardiopulmonar normal. PA:140x85mmHg, FC:80bpm, FR:18irpm,\nIMC:31kg/m2. A conduta mais adequada seria:","options":{"A":"Solicitar RM de joelho e Rx de mão e punhos, fazer curso de 14 dias com AINES via oral, manter\nanalgesia com paracetamol ou dipirona.","B":"Solicitar hemograma, VHS, PCR e Fator reumatoide, Rx de mãos e punhos e RM de joelho,\nfazer curso de 7 dias com AINES via oral,\nmanter analgesia com paracetamol, dipirona ou codeína.","C":"Solicitar fisioterapia para o joelho, orientar necessidade de prática de exercício físico\nregular e\nperda de peso, AINE tópico para as mãos e analgesia simples em caso de dor.","D":"Solicitar hemograma, VHS, PCR e Fator reumatoide, Rx de mãos e punhos e RM de joelho,\nfazer infiltração com corticoide intra-articular e fisioterapia, além de analgesia simples."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-230898","number":"230898","sourceNumber":"230898","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher, 52 anos, empregada doméstica. Refere dor em joelho direito e nas articulações\ndas mãos. Relata rigidez matinal em torno de\n20minutos. Refere que as dores pioravam com o frio\ne com o esforço físico e melhoravam com o repouso. Atualmente vem fazendo uso de diclofenaco\ncom melhora; contudo, refere epigastralgia. Ao exame articular notam-se nas mãos nódulos de\nHeberden e Bouchard e no joelho há crepitação. No momento, nenhuma articulação com sinal de\nsinovite. Qual a conduta mais adequada para o tratamento paciente?","options":{"A":"Manter diclofenaco e associar com IBP.","B":"Prescrever analgesia simples e fisioterapia.","C":"Iniciar Metotrexato associado a ácido fólico.","D":"Iniciar corticoide em dose imunossupressora."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-240460","number":"240460","sourceNumber":"240460","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher de 35 anos com diagnóstico de artrite reumatoide há 2 anos. Faz uso de\nmetotrexato 20 mg/semana, ácido fólico 5\nmg/dia e prednisona 15 mg/dia. Na consulta, vem com\nDisease Activity Score (DAS) 28 de 2,1. A conduta a ser adotada deve ser:","options":{"A":"Reduzir a prednisona e manter as demais medicações nas mesmas doses.","B":"Aumentar a dose do metotrexato e manter as demais medicações.","C":"Aumentar a dose da prednisona e manter as demais medicações.","D":"Manter todas as medicações nas mesmas doses.","E":"Trocar o metotrexato pela leflunomida e manter as demais medicações."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-240467","number":"240467","sourceNumber":"240467","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 40 anos apresenta-se com queixa de crises de monoartrites recorrentes. O\nquadro iniciou há 2 anos, já tendo acometido o joelho esquerdo, a primeira metatarsofalangeana\nesquerda, o punho direito e o joelho direito, nesta sequência. Faz uso de anti-inflamatórios com\nmelhora das queixas em cerca de 5 a 7 dias, permanecendo assintomático entre as crises.\n\nAtualmente, está em crise com dor, calor e rubor há 2 dias no joelho direito. Nega febre e seu\nestado geral é bom. Neste momento, a medicação a ser prescrita é a(o)","options":{"A":"alopurinol.","B":"benzobromarona.","C":"probenecide.","D":"nimesulida.","E":"uricase."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-227639","number":"227639","sourceNumber":"227639","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Em relação à doença valvar adquirida, o principal fator etiológico é:","options":{"A":"Artrite reumatoide.","B":"Doença autoimune associada ao HCV.","C":"Hipercolesterolemia familiar.","D":"Infecção pelo HIV.","E":"Cardiopatia reumática."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-227699","number":"227699","sourceNumber":"227699","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Criança de 12 anos de idade apresenta artrite migratória em joelhos, tornozelos e\npunhos, associada à febre de 39ºC. Exames de\nlaboratório revelam ASLO 600 (valor de referência:\naté 200), PCR 5 (normal até 0,1), VHS 120 mm/primeira hora (normal até 20 mm). Realizado\necocardiograma, normal. Em relação ao caso descrito, assinale a alternativa CORRETA.","options":{"A":"O paciente apresenta 2 critérios maiores e 3 critérios menores para febre reumática e deve\niniciar profilaxia primária com penicilina G benzatina a cada 21 dias.","B":"O paciente apresenta 1 critério maior e 2 critérios menores para febre reumática e deve iniciar\nprofilaxia secundária com penicilina G benzatina a cada 15 dias.","C":"O paciente apresenta 1 critério maior e 2 critérios menores para febre reumática e deve iniciar\nprofilaxia secundária com penicilina G benzatina a cada 21 dias.","D":"O paciente não preenche critérios para febre reumática, devendo receber anti-inflamatório não\nhormonal para tratamento de artrite pós-estreptocócica.","E":"O paciente não preenche critérios para febre reumática, devendo ser repetido o ecocardiograma\nem 48 horas para avaliar a evolução do quadro."},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-203689","number":"203689","sourceNumber":"203689","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente de 32 anos, sexo masculino, vem à consulta por queixa de lombalgia há 6\nmeses. Relata dor tipo pontada e rigidez matinal de cerca de 2h. Refere melhora à medida que se\nmovimenta. Realizou radiografia da coluna lombar com sinais de osteófitos incipientes. O\ntratamento com nimesulida ou diclofenaco leva à melhora temporária dos sintomas, necessitando\nfazer uso diário desses medicamentos para manter-se em suas atividades laborais (engenheiro\ncivil). Neste momento, a conduta adequada é:","options":{"A":"Manter uso de anti-inflamatórios e encaminhar para fisioterapia.","B":"Solicitar VHS, PCR e ressonância magnética de sacroilíacas.","C":"Solicitar ressonância magnética lombar.","D":"Encaminhar para ortopedia, devido aos osteófitos.","E":"Fornecer atestado médico para repouso absoluto por 7 dias."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-216193","number":"216193","sourceNumber":"216193","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre a Espondilite Anquilosante é correto afirmar que: I. Homens entre 20 e 40 anos\nsão o principal grupo acometido pela\ndoença. II. O antígeno leucocitário humano, ou HLA-B27 pode\nocorrer em até 90% dos pacientes portadores da doença. III. A sacroileíte, colite, inflamações nos\nolhos e tendinites são sintomas da Espondilite Anquilosante. IV. O sintoma mais clássico da\nEspondilite Anquilosante é o acometimento da coluna vertebral, caracterizando por dores e rigidez\nmatinal. A alternativa que contám todas as afirmativas corretas é:","options":{"A":"I e II","B":"I e III","C":"I, II e III","D":"I, III e IV","E":"I, II, III e IV"},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-203709","number":"203709","sourceNumber":"203709","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Homem de 35 anos procura pronto atendimento devido à febre (39°C) há 2 dias, além\nde dor, calor e rubor em joelho direito, com\nlimitação funcional para flexão e extensão. Nega história\nde trauma ou episódios prévios. Consome bebida alcoólica pelo menos 5 vezes por semana,\ngeralmente cerveja. Relata que tem diagnóstico prévio de gota devido a episódios de lombalgia. Ao\nexame, apresenta índice de massa corpórea de 35 kg/m², pressão de 150 x 90 mmHg, temperatura\nde 39°C, artrite em joelho direito. No caso, a conduta adequada é:","options":{"A":"Prescrever alopurinol.","B":"Prescrever benzobromarona.","C":"Infiltrar articulação com corticoide.","D":"Solicitar ressonância magnética.","E":"Realizar artrocentese diagnóstica."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-216105","number":"216105","sourceNumber":"216105","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"A artrite reumatoide pode levar ao acometimento de diversos órgãos. Entre os órgãos\nabaixo, o mais raro de ser acometido, é:","options":{"A":"Pleura","B":"Pele","C":"Rins","D":"Olhos","E":"Pericárdio"},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-215642","number":"215642","sourceNumber":"215642","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Paciente de 9 anos de idade, 30 Kg de peso, tem diagnóstico recente de Febre\nReumática por apresentar os seguintes\ncritérios: poliartrite migratória, febre, elevação de PCR e\nVHS e antiestreptolisina O positiva. Para esse paciente, é correto afirmar que:","options":{"A":"está indicada a profilaxia primária com Penicilina G benzatina 1.200.000 unidades internacionais\nem dose única, repetida a cada faringotonsilite\nbacteriana para evitar novos surtos.","B":"deve ser realizada a profilaxia secundária com Penicilina G Benzatina 1.200.000 unidades\ninternacionais a cada 21 dias, até os 18 anos de idade ou 10 anos após o último surto.","C":"deve ser realizada a profilaxia secundária com Penicilina G Benzatina 1.200.000 unidades\ninternacionais a cada 21 dias, até os 25 anos de idade ou 5 anos após o último surto.","D":"não está indicada a profilaxia com Penicilina G Benzatina profilática por não apresentar cardite,\ndevendo fazer profilaxia primária a cada faringotonsilite bacteriana para evitar novos surtos.","E":"deve ser feita profilaxia secundária com Penicilina G Benzatina 1.200.000 unidades\ninternacionais a cada 21 dias, até os 21 anos de idade ou 5 anos após o último surto."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-175245","number":"175245","sourceNumber":"175245","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Sobre artrites, é correto afirmar:","options":{"A":"Pacientes com osteomielite geralmente são decorrentes de quadros poliarticulares.","B":"Sorologias para hepatites e HIV são indicadas especificamente para serem realizadas em\npacientes com mais de 6 semanas de evolução.","C":"Nos casos suspeitos ou confirmados de Doença Articular Crônica Inflamatória por Chikungunya,\no uso de biológico está indicado quando há\nfalha terapêutica ao corticoide.","D":"Em casos de artrite crônica nas formas oligo ou poliarticular de um padrão assimétrico,\nconsiderar a\n\ninvestigação de gota e espondiloartropatia.","E":"Poliartrite é uma manifestação comum da doença enxerto vs hospedeiro."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-175227","number":"175227","sourceNumber":"175227","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Segundo as diretrizes brasileiras para o diagnóstico, tratamento e prevenção de febre\nreumática, a profilaxia secundária instituída para um paciente de 23 kg, com quadro de Coreia de\nSydenham, é","options":{"A":"penicilina benzatina 600.000UI de 21 em 21 dias até 18 anos ou 5 anos do último episódio.","B":"penicilina benzatina 1.200.000UI de 15 em 15 dias até 25 anos ou 10 anos do último episódio.","C":"penicilina benzatina 600.000UI de 21 em 21 dias até 21 anos ou 10 anos do último episódio.","D":"penicilina benzatina 1.200.000 UI de 21 em 21 dias até 21 anos ou 5 anos do último episódio.","E":"penicilina benzatina 1.200.000UI de 18 em 18 dias até 18 anos ou 5 anos do último episódio."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-181794","number":"181794","sourceNumber":"181794","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Menina de 10 anos de idade apresenta febre de até 39°C há 7 dias, associada à artrite\nmuito dolorosa que iniciou em joelho esquerdo e atualmente encontra-se em cotovelo direito.\n\nExames laboratoriais revelam leucocitose e elevação de VHS e PCR, ASLO 800 (normal até 200).\nSobre o caso descrito, marque a alternativa CORRETA.","options":{"A":"A paciente preenche critérios para febre reumática, devendo receber profilaxia primária com\npenicilina G benzatina e realizar ecocardiograma para pesquisa de cardite reumática.","B":"Deve ser solicitado ecocardiograma e caso haja estenose de valva mitral ou aórtica, confirma o\ndiagnóstico de febre reumática, com indicação de receber penicilina G benzatina e corticoterapia.","C":"A paciente preenche critérios para febre reumática, devendo receber profilaxia primária com\npenicilina G benzatina a cada 15 dias durante 3 meses, além de ácido acetilsalicílico em dose\nanti-inflamatória.","D":"As alterações citadas não são suficientes para fechar diagnóstico de febre reumática, devendo\nser pesquisados os demais critérios diagnósticos e\nrealizado diagnóstico diferencial com lúpus\neritematoso sistêmico juvenil.","E":"As alterações citadas não são suficientes para fechar diagnóstico de febre reumática, devendo\nser pesquisados os demais critérios diagnósticos e\nrealizar mielograma para excluir leucemia."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-181950","number":"181950","sourceNumber":"181950","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Um menino de 11 anos, jogador de futebol, teve dor de garganta, mas não contou nada\npara a família com medo de perder os jogos\nda final. Como muitas crianças na região tiveram o\ndiagnóstico de febre reumática, a mãe ao saber desta informação do filho se preocupa com o fato\nde se filho também poder estar com este diagnóstico Você diz a ela que vários critérios devem ser\nencontrados, sendo que o mais comum é:","options":{"A":"Cardite","B":"Poliartrite","C":"Eritema marginado","D":"Coreia","E":"Nódulos subcutâneos"},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-159944","number":"159944","sourceNumber":"159944","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Artrite significa a evidência de alteração inflamatória ou degenerativa da articulação. O\npatógeno mais frequentemente causador de artrite não-gonocócica é:","options":{"A":"Estreptococo do grupo A e B","B":"E. coli","C":"S. Aureus","D":"P. Aeruginosa","E":"Chlamydia"},"answer":"C","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-159947","number":"159947","sourceNumber":"159947","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Joaquim Augusto tem 8 anos de idade e há cerca de seis meses sua mãe relata que\ntem apresentado inchaço doloroso na região do\ntornozelo bilateral, com prejuízo da deambulação,\nque surge de forma intermitente, com intervalos longos sem qualquer alteração. A mãe associa o\ninchaço doloroso à reação alérgica a determinados alimentos. Os dados utilizados para estabelecer\no diagnóstico inclui respectivamente:","options":{"A":"Idade; artrite; duração de mais de 6 semanas; hemograma ? anemia, leucocitose; ECG","B":"Idade; artrite; duração de mais de 6 semanas; hemograma - leucopenia; eritema facial; fator\nantinuclear positivo.","C":"Idade; artrite; duração de mais de 6 semanas; enzimas aumentadas (CPK, TGO); edema e\neritema facial de pálpebras, cotovelos e joelhos; fraqueza muscular.","D":"Idade; artrite; duração de mais de 6 semanas; hemograma - leucocitose com neutrofilia; VHS\nelevado; fator reumatoide elevado.","E":"Idade; artrite; duração de mais de 6 semanas; conjuntivite bilateral com uveíte anterior aguda;\nfotofobia; uretrite."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-156670","number":"156670","sourceNumber":"156670","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Mulher com artrite em tornozelos, quatro metacarpofalangianas e cinco interfalangianas\npróximas da mão direita há 8 semanas, com\nrigidez matinal de 40 minutos e VHS de 30 mm/1ªh.\n\nDemais exames sem alterações, incluindo sorologias e autoanticorpos. O diagnóstico mais provável\ne a melhor conduta são:","options":{"A":"Artrite reativa; AINE e antibióticos.","B":"Reumatismo palindrômico; AINE.","C":"Espondiloartrite periférica; AINE.","D":"Artrite indiferenciada; AINE ou baixas doses de prednisona.","E":"Artrite reumatoide inicial; metotrexato, AINE ou baixas doses de prednisona."},"answer":"E","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-159966","number":"159966","sourceNumber":"159966","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Estivador de 32 anos com um quadro de artrite em joelho esquerdo há 2 dias, refere\nque há 10 dias apresentou um quadro de\npoliartralgia migratória assimétrica, mialgia, exantema e\nfebre, com melhorara nos três últimos dias. O diagnóstico mais provável deste paciente é:","options":{"A":"Artrite reumatoide.","B":"Artrite gonocócica.","C":"Espondilite anquilosante.","D":"Artrite gotosa.","E":"Lupus eritematoso sistêmico."},"answer":"B","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-156741","number":"156741","sourceNumber":"156741","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"De acordo com as diretrizes brasileiras para o diagnóstico, tratamento e prevenção da\nfebre Reumática, a profilaxia secundária para um paciente, sexo masculino, 9 anos, 30 kg, com\nquadro de artrite e coreia, é:","options":{"A":"Penicilina G benzatina, 1.200.000UI de 15 em 15 dias até 21 anos.","B":"Penicilina G cristalina, 600.000UI de 15 em 15 dias até 18 anos.","C":"Penicilina G benzatina, 1.200.000UI de 21 em 21 dias até 18 anos.","D":"Penicilina G benzatina, 1.200.000UI de 21 em 21 dias até 21 anos.","E":"Penicilina G benzatina, 1.200.000UI de 15 em 15 dias até 15 anos."},"answer":"A","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-reumatologia-reu-1-160017","number":"160017","sourceNumber":"160017","collectionBlock":"medcurso:medcurso-reumatologia-reu-1","collectionLabel":"Medcurso · REU 1","documentBlock":"","area":"Reumatologia","specialty":"Reumatologia","topic":"REU 1","subtopic":"","stem":"Escolar com quadro de febre reumática, a primeira escolha de antibioticoterapia para a\nerradicação do agente etiológico é:","options":{"A":"cefalexina.","B":"amoxicilina.","C":"eritromicina.","D":"penicilina benzatina.","E":"ceftriaxona."},"answer":"D","source":"Reumatologia/REU 1/REU 1.txt","sourceLabel":"Medcurso · REU 1","images":[],"optionImages":{},"commentImages":[],"tags":["Reumatologia","REU 1","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
